-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.cfg_vehicles_costs_types (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code character varying NOT NULL UNIQUE,
    description character varying NOT NULL,
    active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.cfg_vehicles_rentals_contracts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id bigint NOT NULL REFERENCES public.vehicles(id),
    monthly_value numeric NOT NULL CHECK (monthly_value >= 0),
    start_date date NOT NULL,
    end_date date,
    active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false,
    created_user_id bigint,
    created_at timestamp with time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT cfg_vehicles_rentals_contracts_dates_ck CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_cfg_vehicles_rentals_contracts_vehicle
    ON public.cfg_vehicles_rentals_contracts (vehicle_id, start_date, end_date)
    WHERE active AND NOT is_deleted;

CREATE TABLE IF NOT EXISTS public.cfg_vehicle_rate_contracts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id bigint NOT NULL REFERENCES public.vehicles(id),
    value_unit numeric NOT NULL CHECK (value_unit >= 0),
    start_date date NOT NULL,
    end_date date,
    active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false,
    created_user_id bigint,
    created_at timestamp with time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT cfg_vehicle_rate_contracts_dates_ck CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE TABLE IF NOT EXISTS public.vehicles_monthly_expenses (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id bigint NOT NULL REFERENCES public.vehicles(id),
    reference_month date NOT NULL,
    description character varying NOT NULL,
    value numeric NOT NULL CHECK (value >= 0),
    expense_type_id bigint REFERENCES public.cfg_vehicles_costs_types(id),
    active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false,
    created_user_id bigint,
    created_at timestamp with time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vehicles_monthly_expenses_month_ck CHECK (reference_month = date_trunc('month', reference_month)::date)
);

CREATE INDEX IF NOT EXISTS idx_vehicles_monthly_expenses_lookup
    ON public.vehicles_monthly_expenses (vehicle_id, reference_month)
    WHERE NOT is_deleted;

CREATE TABLE IF NOT EXISTS public.vehicles_rentals_periods (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehicle_id bigint NOT NULL REFERENCES public.vehicles(id),
    reference_month date NOT NULL,
    contract_id bigint REFERENCES public.cfg_vehicles_rentals_contracts(id),
    contract_value numeric NOT NULL DEFAULT 0 CHECK (contract_value >= 0),
    total_km bigint DEFAULT 0,
    cost_per_km numeric,
    variable_value numeric DEFAULT 0,
    variable_per_km numeric,
    allocated_value numeric DEFAULT 0,
    idle_value numeric DEFAULT 0,
    has_conflict boolean NOT NULL DEFAULT false,
    status character varying NOT NULL DEFAULT 'OPEN'
        CHECK (status IN ('OPEN','CALCULATED','ALLOCATED','CLOSED')),
    created_user_id bigint,
    created_at timestamp with time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vehicles_rentals_periods_month_uq UNIQUE (vehicle_id, reference_month),
    CONSTRAINT vehicles_rentals_periods_month_ck CHECK (reference_month = date_trunc('month', reference_month)::date)
);

CREATE INDEX IF NOT EXISTS idx_vehicles_rentals_periods_reference_month
    ON public.vehicles_rentals_periods (reference_month);

CREATE TABLE IF NOT EXISTS public.vehicles_rentals_allocations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    period_id bigint NOT NULL REFERENCES public.vehicles_rentals_periods(id),
    ov_id bigint NOT NULL REFERENCES public.orders_visits(id),
    ovv_id bigint NOT NULL REFERENCES public.orders_visits_vehicles(id),
    rental_ovv_id bigint REFERENCES public.orders_visits_vehicles(id),
    km bigint NOT NULL DEFAULT 0,
    rate numeric,
    value numeric NOT NULL DEFAULT 0,
    cost_component character varying NOT NULL CHECK (cost_component IN ('RENTAL','VARIABLE')),
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vehicles_rentals_allocations_uq UNIQUE (period_id, ovv_id, cost_component)
);

CREATE INDEX IF NOT EXISTS idx_vehicles_rentals_allocations_period
    ON public.vehicles_rentals_allocations (period_id);

CREATE INDEX IF NOT EXISTS idx_vehicles_rentals_allocations_ov
    ON public.vehicles_rentals_allocations (ov_id);

-- ---------------------------------------------------------------------------
-- Functions
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fc_vehicle_rate_contract(
    p_vehicle_id bigint,
    p_on_date date
) RETURNS TABLE (value_unit numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT c.value_unit
    FROM public.cfg_vehicle_rate_contracts c
    WHERE c.vehicle_id = p_vehicle_id
      AND c.active
      AND NOT c.is_deleted
      AND c.start_date <= p_on_date
      AND (c.end_date IS NULL OR c.end_date >= p_on_date)
    ORDER BY c.start_date DESC, c.id DESC
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_period_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF coalesce(current_setting('app.vehicle_rental_write', true), '') = '1' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF OLD.status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Competência % do veículo % não pode ser excluída: rateio já alocado/fechado.',
                OLD.reference_month, OLD.vehicle_id;
        END IF;
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Período de rateio de aluguel é gerenciado exclusivamente pelas RPCs de apuração (fc_vehicle_rental_*).';
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status character varying;
BEGIN
    IF coalesce(current_setting('app.vehicle_rental_write', true), '') = '1' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Rateio de aluguel é gerado pela apuração mensal e não pode ser editado diretamente.';
    END IF;
    SELECT p.status INTO v_status FROM public.vehicles_rentals_periods p WHERE p.id = OLD.period_id;
    IF v_status = 'CLOSED' THEN
        RAISE EXCEPTION 'Competência fechada: o rateio é imutável.';
    END IF;
    RETURN OLD;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_monthly_expenses_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status character varying;
BEGIN
    IF TG_OP <> 'DELETE' THEN
        SELECT p.status INTO v_status
        FROM public.vehicles_rentals_periods p
        WHERE p.vehicle_id = NEW.vehicle_id AND p.reference_month = NEW.reference_month;
        IF v_status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Despesas da competência % (veículo %) estão bloqueadas: período %.',
                NEW.reference_month, NEW.vehicle_id, v_status;
        END IF;
    END IF;
    IF TG_OP <> 'INSERT' THEN
        SELECT p.status INTO v_status
        FROM public.vehicles_rentals_periods p
        WHERE p.vehicle_id = OLD.vehicle_id AND p.reference_month = OLD.reference_month;
        IF v_status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Despesas da competência % (veículo %) estão bloqueadas: período %.',
                OLD.reference_month, OLD.vehicle_id, v_status;
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_orders_visits_vehicles_rateio_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_flag boolean := coalesce(current_setting('app.vehicle_rental_write', true), '') = '1';
    v_status character varying;
    v_period_id bigint;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF v_flag THEN RETURN NEW; END IF;
        IF NEW.cost_type <> 'odometer' THEN
            RAISE EXCEPTION 'Linha de rateio só pode ser criada pela apuração mensal.';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.ov_id IS NOT DISTINCT FROM OLD.ov_id
           AND NEW.vehicle_id IS NOT DISTINCT FROM OLD.vehicle_id
           AND NEW.recorder_start IS NOT DISTINCT FROM OLD.recorder_start
           AND NEW.recorder_end IS NOT DISTINCT FROM OLD.recorder_end
           AND NEW.amount IS NOT DISTINCT FROM OLD.amount
           AND NEW.discount IS NOT DISTINCT FROM OLD.discount
           AND NEW.cost_type IS NOT DISTINCT FROM OLD.cost_type
           AND NEW.is_deleted IS NOT DISTINCT FROM OLD.is_deleted THEN
            RETURN NEW;
        END IF;
        IF NEW.cost_type IN ('rental', 'variable', 'rate') THEN
            IF v_flag THEN RETURN NEW; END IF;
            RAISE EXCEPTION 'Linha de rateio é gerada pela apuração mensal e não pode ser editada.';
        END IF;
        SELECT p.status, p.id INTO v_status, v_period_id
        FROM public.vehicles_rentals_allocations a
        JOIN public.vehicles_rentals_periods p ON p.id = a.period_id
        WHERE a.ovv_id = OLD.id LIMIT 1;
        IF v_status IN ('ALLOCATED', 'CLOSED') AND NOT v_flag THEN
            RAISE EXCEPTION 'Linha de Km já rateada: competência % — faça o estorno antes de alterar o odômetro.', v_status;
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF v_flag THEN RETURN OLD; END IF;
        IF OLD.cost_type IN ('rental', 'variable', 'rate') THEN
            RAISE EXCEPTION 'Linha de rateio não pode ser excluída diretamente: use o estorno.';
        END IF;
        RETURN OLD;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_contract(
    p_vehicle_id bigint,
    p_reference_month date
) RETURNS TABLE (contract_id bigint, monthly_value numeric, has_conflict boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_month_end date := (date_trunc('month', p_reference_month::timestamp) + interval '1 month - 1 day')::date;
BEGIN
    RETURN QUERY
    SELECT c.id, c.monthly_value, (count(*) OVER ()) > 1
    FROM public.cfg_vehicles_rentals_contracts c
    WHERE c.vehicle_id = p_vehicle_id
      AND c.active AND NOT c.is_deleted
      AND c.start_date <= v_month_end
      AND (c.end_date IS NULL OR c.end_date >= v_month)
    ORDER BY c.start_date DESC, c.id DESC LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_calculate(
    p_vehicle_id bigint,
    p_reference_month date,
    p_user_id bigint DEFAULT NULL
) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_contract_id bigint; v_contract_value numeric; v_has_conflict boolean;
    v_total_km bigint; v_expenses numeric; v_rate numeric;
    v_rental_rate numeric; v_var_rate numeric;
    v_alloc numeric; v_alloc_rental numeric; v_alloc_variable numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);
    SELECT p.* INTO v_period FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month FOR UPDATE;
    IF v_period.id IS NOT NULL AND v_period.status IN ('ALLOCATED', 'CLOSED') THEN
        RAISE EXCEPTION 'Competência % do veículo % já alocada/fechada.', v_month, p_vehicle_id;
    END IF;
    SELECT COALESCE(sum(e.value), 0) INTO v_expenses
    FROM public.vehicles_monthly_expenses e
    WHERE e.vehicle_id = p_vehicle_id AND e.reference_month = v_month;
    SELECT c.contract_id, c.monthly_value, c.has_conflict INTO v_contract_id, v_contract_value, v_has_conflict
    FROM public.fc_vehicle_rental_contract(p_vehicle_id, v_month) c;
    IF v_contract_id IS NULL THEN
        IF COALESCE(v_expenses, 0) > 0 THEN v_contract_value := 0; v_has_conflict := false;
        ELSE RAISE EXCEPTION 'Sem contrato de aluguel e sem despesas no mês.'; END IF;
    END IF;
    SELECT COALESCE(sum(ovv.amount), 0)::bigint INTO v_total_km
    FROM public.orders_visits_vehicles ovv JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate') AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';
    v_rate := CASE WHEN v_total_km > 0 THEN round((COALESCE(v_contract_value,0) + v_expenses) / v_total_km::numeric, 6) ELSE NULL END;
    v_rental_rate := CASE WHEN v_total_km > 0 THEN round(COALESCE(v_contract_value,0) / v_total_km::numeric, 6) ELSE NULL END;
    v_var_rate := CASE WHEN v_total_km > 0 AND v_expenses > 0 THEN round(v_expenses / v_total_km::numeric, 6) ELSE NULL END;
    SELECT COALESCE(sum(round(ovv.amount * v_rental_rate, 2)), 0), COALESCE(sum(round(ovv.amount * v_var_rate, 2)), 0)
    INTO v_alloc_rental, v_alloc_variable
    FROM public.orders_visits_vehicles ovv JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate') AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';
    v_alloc := v_alloc_rental + v_alloc_variable;
    INSERT INTO public.vehicles_rentals_periods (
        vehicle_id, reference_month, contract_id, contract_value, total_km,
        cost_per_km, variable_value, variable_per_km, allocated_value,
        idle_value, has_conflict, status, created_user_id, created_at, updated_user_id, updated_at
    ) VALUES (
        p_vehicle_id, v_month, v_contract_id, COALESCE(v_contract_value, 0), v_total_km,
        v_rate, v_expenses, v_var_rate, v_alloc,
        (COALESCE(v_contract_value,0) + v_expenses) - v_alloc, COALESCE(v_has_conflict, false), 'CALCULATED',
        p_user_id, now(), p_user_id, now()
    )
    ON CONFLICT (vehicle_id, reference_month) DO UPDATE SET
        contract_id = EXCLUDED.contract_id, contract_value = EXCLUDED.contract_value,
        total_km = EXCLUDED.total_km, cost_per_km = EXCLUDED.cost_per_km,
        variable_value = EXCLUDED.variable_value, variable_per_km = EXCLUDED.variable_per_km,
        allocated_value = EXCLUDED.allocated_value, idle_value = EXCLUDED.idle_value,
        has_conflict = EXCLUDED.has_conflict, status = 'CALCULATED',
        updated_user_id = EXCLUDED.updated_user_id, updated_at = now();
    RETURN QUERY SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_allocate(
    p_vehicle_id bigint,
    p_reference_month date,
    p_user_id bigint DEFAULT NULL
) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_line record; v_rental_id bigint; v_var_id bigint;
    v_rental_rate numeric; v_var_rate numeric; v_value numeric; v_alloc_total numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);
    SELECT p.* INTO v_period FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month FOR UPDATE;
    IF v_period.id IS NULL THEN RAISE EXCEPTION 'Competência não calculada.'; END IF;
    IF v_period.status NOT IN ('CALCULATED', 'ALLOCATED') THEN RAISE EXCEPTION 'Competência % está %: reabra antes de alocar.', v_month, v_period.status; END IF;
    IF v_period.cost_per_km IS NULL THEN RAISE EXCEPTION 'Sem Km rodado: nada a alocar.'; END IF;
    v_rental_rate := CASE WHEN v_period.contract_id IS NOT NULL AND v_period.total_km > 0
        THEN round(v_period.contract_value / v_period.total_km::numeric, 6) ELSE NULL END;
    v_var_rate := CASE WHEN COALESCE(v_period.variable_value, 0) > 0
        THEN round(v_period.variable_value / v_period.total_km::numeric, 6) ELSE NULL END;
    FOR v_line IN
        SELECT ovv.id AS ovv_id, ovv.ov_id, ovv.amount AS km, ovs.ov_costs_status AS visit_status
        FROM public.orders_visits_vehicles ovv JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
        WHERE ovv.vehicle_id = p_vehicle_id AND NOT ovv.is_deleted
          AND ovv.cost_type IN ('odometer', 'rate') AND ovv.amount > 0
          AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
          AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month'
        ORDER BY ovv.id
    LOOP
        IF v_period.contract_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.vehicles_rentals_allocations a
            WHERE a.period_id = v_period.id AND a.ovv_id = v_line.ovv_id AND a.cost_component = 'RENTAL'
        ) THEN
            v_value := round(v_line.km * v_rental_rate, 2);
            INSERT INTO public.orders_visits_vehicles (ov_id, vehicle_id, amount, value_unit, discount, cost_type, ov_costs_status, created_user_id, created_at, is_deleted)
            VALUES (v_line.ov_id, p_vehicle_id, v_line.km, v_rental_rate, 1, 'rental', COALESCE(v_line.visit_status, 'pending'), p_user_id, now(), false)
            RETURNING id INTO v_rental_id;
            INSERT INTO public.vehicles_rentals_allocations (period_id, ov_id, ovv_id, rental_ovv_id, km, rate, value, cost_component, created_at)
            VALUES (v_period.id, v_line.ov_id, v_line.ovv_id, v_rental_id, v_line.km, v_rental_rate, v_value, 'RENTAL', now())
            ON CONFLICT (period_id, ovv_id, cost_component) DO NOTHING;
        END IF;
        IF v_var_rate IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.vehicles_rentals_allocations a
            WHERE a.period_id = v_period.id AND a.ovv_id = v_line.ovv_id AND a.cost_component = 'VARIABLE'
        ) THEN
            v_value := round(v_line.km * v_var_rate, 2);
            INSERT INTO public.orders_visits_vehicles (ov_id, vehicle_id, amount, value_unit, discount, cost_type, ov_costs_status, created_user_id, created_at, is_deleted)
            VALUES (v_line.ov_id, p_vehicle_id, v_line.km, v_var_rate, 1, 'variable', COALESCE(v_line.visit_status, 'pending'), p_user_id, now(), false)
            RETURNING id INTO v_var_id;
            INSERT INTO public.vehicles_rentals_allocations (period_id, ov_id, ovv_id, rental_ovv_id, km, rate, value, cost_component, created_at)
            VALUES (v_period.id, v_line.ov_id, v_line.ovv_id, v_var_id, v_line.km, v_var_rate, v_value, 'VARIABLE', now())
            ON CONFLICT (period_id, ovv_id, cost_component) DO NOTHING;
        END IF;
        UPDATE public.orders_visits_vehicles ovv SET cost_type = 'rate'
        WHERE ovv.id = v_line.ovv_id AND ovv.cost_type = 'odometer';
    END LOOP;
    SELECT COALESCE(sum(a.value), 0) INTO v_alloc_total FROM public.vehicles_rentals_allocations a WHERE a.period_id = v_period.id;
    UPDATE public.vehicles_rentals_periods p SET
        allocated_value = v_alloc_total,
        idle_value = (p.contract_value + COALESCE(p.variable_value, 0)) - v_alloc_total,
        status = 'ALLOCATED', updated_user_id = p_user_id, updated_at = now()
    WHERE p.id = v_period.id;
    RETURN QUERY SELECT p.* FROM public.vehicles_rentals_periods p WHERE p.id = v_period.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_revert(
    p_vehicle_id bigint,
    p_reference_month date,
    p_user_id bigint DEFAULT NULL
) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_total_km bigint; v_expenses numeric; v_rate numeric;
    v_rental_rate numeric; v_var_rate numeric;
    v_alloc numeric; v_alloc_rental numeric; v_alloc_variable numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);
    SELECT p.* INTO v_period FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month FOR UPDATE;
    IF v_period.id IS NULL THEN RAISE EXCEPTION 'Competência % do veículo % não existe.', v_month, p_vehicle_id; END IF;
    IF v_period.status = 'CLOSED' THEN RAISE EXCEPTION 'Competência % está fechada: reabra antes de estornar.', v_month; END IF;
    IF v_period.status <> 'ALLOCATED' THEN RAISE EXCEPTION 'Competência % não tem rateio alocado (status: %).', v_month, v_period.status; END IF;
    UPDATE public.orders_visits_vehicles ovv SET cost_type = 'odometer'
    WHERE ovv.cost_type = 'rate' AND ovv.id IN (SELECT a.ovv_id FROM public.vehicles_rentals_allocations a WHERE a.period_id = v_period.id);
    DELETE FROM public.orders_visits_vehicles ovv
    WHERE ovv.id IN (SELECT a.rental_ovv_id FROM public.vehicles_rentals_allocations a WHERE a.period_id = v_period.id AND a.rental_ovv_id IS NOT NULL);
    DELETE FROM public.vehicles_rentals_allocations a WHERE a.period_id = v_period.id;
    SELECT COALESCE(sum(ovv.amount), 0)::bigint INTO v_total_km
    FROM public.orders_visits_vehicles ovv JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate') AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';
    SELECT COALESCE(sum(e.value), 0) INTO v_expenses FROM public.vehicles_monthly_expenses e
    WHERE e.vehicle_id = p_vehicle_id AND e.reference_month = v_month;
    v_rate := CASE WHEN v_total_km > 0 THEN round((v_period.contract_value + v_expenses) / v_total_km::numeric, 6) ELSE NULL END;
    v_rental_rate := CASE WHEN v_total_km > 0 THEN round(v_period.contract_value / v_total_km::numeric, 6) ELSE NULL END;
    v_var_rate := CASE WHEN v_total_km > 0 AND v_expenses > 0 THEN round(v_expenses / v_total_km::numeric, 6) ELSE NULL END;
    SELECT COALESCE(sum(round(ovv.amount * v_rental_rate, 2)), 0), COALESCE(sum(round(ovv.amount * v_var_rate, 2)), 0)
    INTO v_alloc_rental, v_alloc_variable
    FROM public.orders_visits_vehicles ovv JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate') AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';
    v_alloc := v_alloc_rental + v_alloc_variable;
    UPDATE public.vehicles_rentals_periods p SET
        total_km = v_total_km, cost_per_km = v_rate, variable_value = v_expenses,
        variable_per_km = v_var_rate, allocated_value = v_alloc,
        idle_value = (p.contract_value + v_expenses) - v_alloc,
        status = 'CALCULATED', updated_user_id = p_user_id, updated_at = now()
    WHERE p.id = v_period.id;
    RETURN QUERY SELECT p.* FROM public.vehicles_rentals_periods p WHERE p.id = v_period.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_close(
    p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL
) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);
    SELECT p.* INTO v_period FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month FOR UPDATE;
    IF v_period.id IS NULL OR v_period.status = 'OPEN' THEN RAISE EXCEPTION 'Competência não calculada.'; END IF;
    IF v_period.status = 'CLOSED' THEN RAISE EXCEPTION 'Competência já está fechada.'; END IF;
    IF v_period.status = 'CALCULATED' AND v_period.total_km > 0 THEN RAISE EXCEPTION 'Há Km para alocar: execute a alocação antes de fechar.'; END IF;
    UPDATE public.vehicles_rentals_periods p SET status = 'CLOSED', updated_user_id = p_user_id, updated_at = now() WHERE p.id = v_period.id;
    RETURN QUERY SELECT p.* FROM public.vehicles_rentals_periods p WHERE p.id = v_period.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.fc_vehicle_rental_reopen(
    p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL
) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);
    SELECT p.* INTO v_period FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id AND p.reference_month = v_month FOR UPDATE;
    IF v_period.id IS NULL THEN RAISE EXCEPTION 'Competência não existe.'; END IF;
    IF v_period.status <> 'CLOSED' THEN RAISE EXCEPTION 'Somente competências fechadas podem ser reabertas (status: %).', v_period.status; END IF;
    UPDATE public.vehicles_rentals_periods p SET
        status = CASE WHEN EXISTS (SELECT 1 FROM public.vehicles_rentals_allocations a WHERE a.period_id = p.id) THEN 'ALLOCATED' ELSE 'CALCULATED' END,
        updated_user_id = p_user_id, updated_at = now()
    WHERE p.id = v_period.id;
    RETURN QUERY SELECT p.* FROM public.vehicles_rentals_periods p WHERE p.id = v_period.id;
END;
$$;

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------

CREATE TRIGGER trg_vehicles_rentals_period_guard
    BEFORE INSERT OR UPDATE ON public.vehicles_rentals_periods
    FOR EACH ROW EXECUTE FUNCTION public.fc_vehicle_rental_period_guard();

CREATE TRIGGER trg_vehicles_rentals_allocation_guard
    BEFORE INSERT OR UPDATE OR DELETE ON public.vehicles_rentals_allocations
    FOR EACH ROW EXECUTE FUNCTION public.fc_vehicle_rental_allocation_guard();

CREATE TRIGGER trg_vehicles_monthly_expenses_guard
    BEFORE INSERT OR UPDATE OR DELETE ON public.vehicles_monthly_expenses
    FOR EACH ROW EXECUTE FUNCTION public.fc_vehicle_monthly_expenses_guard();

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------

GRANT USAGE ON SEQUENCE public.vehicles_monthly_expenses_id_seq   TO authenticated, service_role;
GRANT USAGE ON SEQUENCE public.vehicles_rentals_allocations_id_seq TO authenticated, service_role;
GRANT USAGE ON SEQUENCE public.vehicles_rentals_periods_id_seq     TO authenticated, service_role;

