--
-- Name: public; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA public;

--
-- Name: SCHEMA public; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON SCHEMA public IS 'standard public schema';

--
-- Name: approve_order_visit_with_maintenance_plans(bigint, bigint, bigint, double precision, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_order_visit_with_maintenance_plans(p_visit_id bigint, p_user_id bigint, p_order_status_id bigint, p_progress double precision, p_suspended_reason_id bigint DEFAULT NULL::bigint, p_cause_reason_id bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_order_id bigint;
    v_current_status_id bigint;
    v_ended_at timestamp without time zone;
    v_authenticated_user_id bigint;
BEGIN
    SELECT id INTO v_authenticated_user_id
    FROM public.users
    WHERE uuid = auth.uid();

    IF auth.uid() IS NULL OR v_authenticated_user_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION 'Usuário não autorizado para aprovar a visita';
    END IF;

    IF p_progress IS NULL OR p_progress < 0 OR p_progress > 100 THEN
        RAISE EXCEPTION 'Progresso inválido para aprovação da visita';
    END IF;

    SELECT ov.o_id, ov.ov_ended_at
    INTO v_order_id, v_ended_at
    FROM public.orders_visits ov
    WHERE ov.id = p_visit_id
      AND COALESCE(ov.is_deleted, false) = false
    FOR UPDATE;

    IF NOT FOUND OR v_order_id IS NULL THEN
        RAISE EXCEPTION 'Visita não encontrada ou sem ordem associada';
    END IF;

    SELECT o.status_id
    INTO v_current_status_id
    FROM public.orders o
    WHERE o.id = v_order_id
      AND COALESCE(o.is_deleted, false) = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ordem de serviço não encontrada';
    END IF;

    IF v_current_status_id IS DISTINCT FROM 5 THEN
        UPDATE public.orders
        SET status_id = p_order_status_id,
            status_at = v_ended_at,
            progress = CASE WHEN p_order_status_id = 8 THEN 1 ELSE p_progress / 100.0 END,
            cause_reason_id = COALESCE(p_cause_reason_id, cause_reason_id),
            updated_user_id = p_user_id,
            updated_at = now()
        WHERE id = v_order_id;
    END IF;

    UPDATE public.orders_visits
    SET ov_processing_id = 5,
        ov_approved_user_id = p_user_id,
        ov_approved_at = now(),
        ov_o_status_id = p_order_status_id,
        ov_o_progress = CASE WHEN p_order_status_id = 8 THEN 1 ELSE p_progress / 100.0 END,
        ov_o_suspended_reason_id = CASE WHEN p_order_status_id = 6 THEN p_suspended_reason_id ELSE NULL END,
        updated_user_id = p_user_id,
        updated_at = now()
    WHERE id = p_visit_id;

    INSERT INTO public.orders_visits_maintenances_plans (o_id, ov_id, maintenance_plan_id)
    SELECT DISTINCT v_order_id, p_visit_id, ova.maintenance_plan_id
    FROM public.orders_visits_assets ova
    WHERE ova.ov_id = p_visit_id
      AND COALESCE(ova.is_deleted, false) = false
      AND ova.processing_id IN (2, 3, 5)
      AND ova.maintenance_plan_id > 0
    ON CONFLICT (ov_id, maintenance_plan_id) DO NOTHING;
END;
$$;

--
-- Name: cfg_app_notices_limit_workers_periods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cfg_app_notices_limit_workers_periods() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.view_end_date IS DISTINCT FROM OLD.view_end_date THEN
        UPDATE public.cfg_app_notices_workers_periods p
        SET period_end = NEW.view_end_date,
            updated_at = now()
        WHERE p.notice_id = NEW.id
          AND p.period_start <= NEW.view_end_date
          AND (p.period_end IS NULL OR p.period_end > NEW.view_end_date);
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: cfg_app_notices_workers_periods_validate_janela(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cfg_app_notices_workers_periods_validate_janela() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    janela_inicio timestamp;   -- sem fuso: mesma natureza de period_start
    janela_fim    timestamp;   -- sem fuso: mesma natureza de period_start
    conflito_id   bigint;
    conflito_ini  timestamp;
    conflito_fim  timestamp;
BEGIN
    SELECT n.view_start_date, n.view_end_date
      INTO janela_inicio, janela_fim
      FROM public.cfg_app_notices n
     WHERE n.id = NEW.notice_id;

    IF janela_inicio IS NULL OR janela_fim IS NULL THEN
        RAISE EXCEPTION 'Janela de visualização do aviso não configurada (view_start_date / view_end_date)';
    END IF;

    -- 2a) O turno deve começar e terminar dentro da janela
    IF NEW.period_start < janela_inicio OR NEW.period_start >= janela_fim THEN
        RAISE EXCEPTION 'Período fora da janela de visualização do aviso (period_start = %, view_start_date = %, view_end_date = %)',
            NEW.period_start, janela_inicio, janela_fim;
    END IF;

    IF NEW.period_end IS NOT NULL AND NEW.period_end > janela_fim THEN
        RAISE EXCEPTION 'Fim do período após a janela de visualização do aviso (period_end = %, view_end_date = %)',
            NEW.period_end, janela_fim;
    END IF;

    -- 2b) Turnos do mesmo aviso não podem se sobrepor.
    --     Intervalos semiabertos [start, end): encostar é permitido
    --     (06:00-14:00 e 14:00-22:00 são válidos).
    --     Período em aberto (period_end NULL) é tratado como válido até a
    --     janela, mantendo compatibilidade com os registros antigos.
    SELECT p.id, p.period_start, COALESCE(p.period_end, janela_fim)
      INTO conflito_id, conflito_ini, conflito_fim
      FROM public.cfg_app_notices_workers_periods p
     WHERE p.notice_id = NEW.notice_id
       AND p.id IS DISTINCT FROM NEW.id
       AND NEW.period_start < COALESCE(p.period_end, janela_fim)
       AND p.period_start < COALESCE(NEW.period_end, janela_fim)
     ORDER BY p.period_start
     LIMIT 1;

    IF conflito_id IS NOT NULL THEN
        RAISE EXCEPTION 'Sobreposição de escala: o período % (%) conflita com o intervalo informado (% a %)',
            conflito_id, conflito_ini, NEW.period_start, COALESCE(NEW.period_end::text, 'janela');
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: change_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
  BEGIN
    IF row(NEW.*) IS DISTINCT FROM row(OLD.*) THEN
      NEW.updated_at = now(); 
      RETURN NEW;
    ELSE
      RETURN OLD;
    END IF;
  END;
$$;


