--
-- Name: fc_orders_visits_vehicles_before_save(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_orders_visits_vehicles_before_save() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_price numeric;
    v_on_date date;
BEGIN
    IF NEW.cost_type IN ('rental', 'variable') THEN
        NEW.recorder_start := NULL;
        NEW.recorder_end := NULL;
        NEW.value_unit := COALESCE(NEW.value_unit, 0);
        NEW.amount := COALESCE(NEW.amount, 0);
        NEW.value_total := ROUND(
            NEW.amount * NEW.value_unit * COALESCE(NEW.discount, 1), 2
        );
        RETURN NEW;
    END IF;

    IF NEW.cost_type = 'rate' THEN
        NEW.amount := COALESCE(NEW.amount, 0);
        NEW.value_unit := COALESCE(NEW.value_unit, 0);
        NEW.value_total := ROUND(NEW.amount * NEW.value_unit, 2);
        RETURN NEW;
    END IF;

    v_on_date := COALESCE(
        NEW.created_at::date,
        (
            SELECT ovs.ov_created_at::date
            FROM public.orders_visits ovs
            WHERE ovs.id = NEW.ov_id
        ),
        now()::date
    );

    NEW.amount := GREATEST(
        COALESCE(NEW.recorder_end, 0) - COALESCE(NEW.recorder_start, 0),
        0
    );

    SELECT contract.value_unit
      INTO v_price
    FROM public.fc_vehicle_rate_contract(NEW.vehicle_id, v_on_date) contract;

    IF v_price IS NULL THEN
        IF NEW.amount > 0 THEN
            RAISE EXCEPTION 'Veículo (%) sem contrato de R$/km vigente em % — cadastre um contrato antes de informar o Km.',
                COALESCE(
                    (SELECT vehicle.description FROM public.vehicles vehicle WHERE vehicle.id = NEW.vehicle_id),
                    NEW.vehicle_id::text
                ),
                to_char(v_on_date, 'DD/MM/YYYY');
        END IF;
        v_price := 0;
    END IF;

    NEW.value_unit := COALESCE(v_price, 0);
    NEW.value_total := NEW.amount * NEW.value_unit * COALESCE(NEW.discount, 1);
    RETURN NEW;
END;
$_$;

--
-- Name: fc_orders_visits_vehicles_rateio_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_orders_visits_vehicles_rateio_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_flag boolean := coalesce(current_setting('app.vehicle_rental_write', true), '') = '1';
    v_status character varying;
    v_period_id bigint;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF v_flag THEN
            RETURN NEW;
        END IF;
        IF NEW.cost_type <> 'odometer' THEN
            RAISE EXCEPTION 'Linha de rateio (aluguel/despesa/R$/km) só pode ser criada pela apuração mensal (fc_vehicle_rental_*).';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.ov_id IS NOT DISTINCT FROM OLD.ov_id
           AND NEW.vehicle_id IS NOT DISTINCT FROM OLD.vehicle_id
           AND NEW.recorder_start IS NOT DISTINCT FROM OLD.recorder_start
           AND NEW.recorder_end IS NOT DISTINCT FROM OLD.recorder_end
           AND NEW.amount IS NOT DISTINCT FROM OLD.amount
           AND NEW.discount IS NOT DISTINCT FROM OLD.discount
           AND NEW.cost_type IS NOT DISTINCT FROM OLD.cost_type
           AND NEW.value_unit IS NOT DISTINCT FROM OLD.value_unit
           AND NEW.is_deleted IS NOT DISTINCT FROM OLD.is_deleted THEN
            RETURN NEW;
        END IF;

        IF NEW.cost_type = 'rate' THEN
            IF NOT v_flag THEN
                RAISE EXCEPTION 'Linha de Km apropriada é gerada pela apuração mensal e não pode ser editada.';
            END IF;
            RETURN NEW;
        END IF;

        IF NEW.cost_type IN ('rental', 'variable') THEN
            IF v_flag THEN
                RETURN NEW;
            END IF;
            RAISE EXCEPTION 'Linha de rateio (aluguel/despesa/R$/km) é gerada pela apuração mensal e não pode ser editada.';
        END IF;

        SELECT p.status, p.id INTO v_status, v_period_id
        FROM public.vehicles_rentals_allocations a
        JOIN public.vehicles_rentals_periods p ON p.id = a.period_id
        WHERE a.ovv_id = NEW.id
        LIMIT 1;

        IF v_status IS NOT NULL AND NOT v_flag THEN
            RAISE EXCEPTION 'Km já rateado na competência % — faça o estorno (fc_vehicle_rental_revert) antes de alterar a leitura do odômetro.',
                v_period_id;
        END IF;

        RETURN NEW;
    END IF;

    IF OLD.cost_type IN ('rental', 'variable') THEN
        IF v_flag THEN
            RETURN OLD;
        END IF;

        SELECT p.status INTO v_status
        FROM public.vehicles_rentals_allocations a
        JOIN public.vehicles_rentals_periods p ON p.id = a.period_id
        WHERE a.rental_ovv_id = OLD.id
        LIMIT 1;

        IF v_status = 'CLOSED' THEN
            RAISE EXCEPTION 'Competência fechada: o rateio (aluguel/despesa) é imutável (reabra a competência para alterar).';
        END IF;

        RETURN OLD;
    END IF;

    SELECT p.status INTO v_status
    FROM public.vehicles_rentals_allocations a
    JOIN public.vehicles_rentals_periods p ON p.id = a.period_id
    WHERE a.ovv_id = OLD.id
    LIMIT 1;

    IF v_status IS NOT NULL AND NOT v_flag THEN
        RAISE EXCEPTION 'Km já rateado — faça o estorno (fc_vehicle_rental_revert) antes de remover a linha do veículo.';
    END IF;

    RETURN OLD;
END;
$_$;

--
-- Name: fc_orders_visits_vehicles_update_vehicles_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_orders_visits_vehicles_update_vehicles_value() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
    target_ov_id bigint;
begin
    -- Identifica qual visita deve ser recalculada
    if TG_OP = 'DELETE' then
        target_ov_id := OLD.ov_id;
    else
        target_ov_id := NEW.ov_id;
    end if;

    -- Faz a soma e atualiza diretamente a tabela orders_visits
    update public.orders_visits
    set ov_vehicles_value = (
        select coalesce(sum(value_total), 0)
        from public.orders_visits_vehicles
        where ov_id = target_ov_id
    )
    where id = target_ov_id;

    return null; -- Gatilhos 'AFTER' podem retornar null
end;
$$;

--
-- Name: fc_regenerate_asset_description(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_regenerate_asset_description(p_asset_id bigint) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_pattern TEXT;
    v_result TEXT;
    v_type_desc VARCHAR;
    v_brand VARCHAR;
    v_model VARCHAR;
    v_code VARCHAR;
    v_serial VARCHAR;
    v_attr RECORD;
    v_val TEXT;
    v_label TEXT;
BEGIN
    -- Buscar padrão de nomenclatura e dados do tipo
    SELECT
        t.naming_pattern,
        t.description,
        a.brand,
        a.model,
        a.code,
        a.serial
    INTO v_pattern, v_type_desc, v_brand, v_model, v_code, v_serial
    FROM assets a
    JOIN cfg_assets_types t ON t.id = a.type_id
    WHERE a.id = p_asset_id;

    IF v_pattern IS NULL OR v_pattern = '' THEN
        RETURN NULL;
    END IF;

    v_result := v_pattern;

    -- Substituir atributos dinâmicos PRIMEIRO (inclui brand/model que são select)
    -- assets_attributes_values tem: asset_id, field_key, value
    -- cfg_assets_attributes tem: id, field_key, data_type, select_options_group_id
    FOR v_attr IN
        SELECT
            aa.field_key,
            aav.value AS raw_value,
            aa.data_type,
            aa.select_options_group_id,
            aa.unit
        FROM assets_attributes_values aav
        JOIN cfg_assets_attributes aa ON aa.field_key = aav.field_key
        WHERE aav.asset_id = p_asset_id
          AND v_pattern LIKE '%{' || aa.field_key || '}%'
    LOOP
        v_val := v_attr.raw_value;

        IF v_val IS NOT NULL AND v_val != '' THEN
            IF v_attr.data_type = 'select' AND v_attr.select_options_group_id IS NOT NULL THEN
                SELECT g.group_name INTO v_label
                FROM cfg_assets_attributes_groups g
                WHERE g.id = CAST(v_val AS BIGINT);

                IF v_label IS NOT NULL THEN
                    v_val := v_label;
                END IF;
            ELSIF v_attr.data_type = 'boolean' THEN
                v_val := CASE WHEN v_val = 'true' THEN 'SIM' ELSE 'NÃO' END;
            END IF;

            -- Adicionar unidade se existir
            IF v_attr.unit IS NOT NULL AND v_attr.unit != '' THEN
                v_val := v_val || v_attr.unit;
            END IF;

            v_result := replace(v_result, '{' || v_attr.field_key || '}', v_val);
        END IF;
    END LOOP;

    -- Substituir campos padrão APENAS se o placeholder ainda existir
    -- (para ativos que não têm atributo dinâmico correspondente)
    IF v_result LIKE '%{type}%' THEN
        v_result := replace(v_result, '{type}', COALESCE(v_type_desc, ''));
    END IF;
    IF v_result LIKE '%{brand}%' THEN
        v_result := replace(v_result, '{brand}', COALESCE(v_brand, ''));
    END IF;
    IF v_result LIKE '%{model}%' THEN
        v_result := replace(v_result, '{model}', COALESCE(v_model, ''));
    END IF;
    IF v_result LIKE '%{code}%' THEN
        v_result := replace(v_result, '{code}', COALESCE(v_code, ''));
    END IF;
    IF v_result LIKE '%{serial}%' THEN
        v_result := replace(v_result, '{serial}', COALESCE(v_serial, ''));
    END IF;

    -- Limpar espaços duplos
    v_result := regexp_replace(v_result, '\s+', ' ', 'g');
    v_result := trim(v_result);

    RETURN v_result;
END;
$$;

--
-- Name: fc_set_ov_started_date_parts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_set_ov_started_date_parts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- Only update if ov_started_at is not null
  if new.ov_started_at is not null then
    new.ov_started_month := extract(month from new.ov_started_at);
    new.ov_started_year  := extract(year from new.ov_started_at);
  else
    -- If the date is removed, clear derived fields
    new.ov_started_month := null;
    new.ov_started_year  := null;
  end if;

  return new;
end;
$$;

--
-- Name: fc_sync_ov_costs_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_sync_ov_costs_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF OLD.ov_costs_status IS DISTINCT FROM NEW.ov_costs_status THEN
        UPDATE public.orders_visits_services
        SET ov_costs_status = NEW.ov_costs_status
        WHERE ov_id = NEW.id;

        UPDATE public.orders_visits_vehicles
        SET ov_costs_status = NEW.ov_costs_status
        WHERE ov_id = NEW.id;

        UPDATE public.orders_visits_assets_materials
        SET ov_costs_status = NEW.ov_costs_status
        WHERE ov_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: fc_system_parent_id_10_at_id_33_46_uata_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_system_parent_id_10_at_id_33_46_uata_rate() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE
  result jsonb;
  v_api_key text;
  req_count integer;
BEGIN

  -- pega API key do header
  v_api_key :=
    (current_setting('request.headers', true)::json ->> 'x-api-key');

  IF v_api_key IS NULL THEN
    RAISE EXCEPTION 'API key missing';
  END IF;

  -- valida API key
  IF NOT public.fc_api_key_validate(v_api_key) THEN
    RAISE EXCEPTION 'Invalid API key';
  END IF;

  -- rate limit
  SELECT count(*)
  INTO req_count
  FROM public.logs_api
  WHERE logs_api.api_key = v_api_key
  AND created_at > now() - interval '5 minutes';

  IF req_count >= 1 THEN
    RAISE EXCEPTION 'Rate limit exceeded: only one request every 5 minutes';
  END IF;

  -- log
  INSERT INTO public.logs_api(api_key, endpoint)
  VALUES (v_api_key, 'fc_system_parent_id_10_at_id_33_46_uata_rate');

  -- consulta
  RETURN (
    WITH dados AS (
    SELECT
        cs.description AS system_parent_description,
        vuatar.asset_tag_description,
        TRIM(vuatar.unit_description) AS unit_description,
        ROUND(vuatar.total_last_asset_available_rate * 100) AS disponibilidade,
        -- Substitua "vuatar.updated_at" pelo nome correto da sua coluna de data
        TO_CHAR(vuatar.last_reported_at, 'YYYY-MM-DD HH24:MI:SS') AS ultima_atualizacao
    FROM public.v_units_assets_tags_available_rate AS vuatar
    LEFT JOIN public.cfg_systems AS cs
        ON vuatar.system_parent_id = cs.id
    WHERE
        vuatar.system_parent_id = 10
        AND vuatar.asset_tag_id IN (33, 46)
        AND vuatar.asset_tag_description IS NOT NULL
        AND TRIM(vuatar.unit_description) <> ''
)
SELECT COALESCE(
    jsonb_object_agg(
        sistema,
        setores
        ORDER BY sistema
    ),
    '{}'::jsonb
)
FROM (
    SELECT
        system_parent_description AS sistema,
        jsonb_object_agg(
            setor,
            unidades
            ORDER BY setor
        ) AS setores
    FROM (
        SELECT
            system_parent_description,
            asset_tag_description AS setor,
            jsonb_object_agg(
                unit_description,
                jsonb_build_object(
                    'disponibilidade', disponibilidade,
                    'data_ultima atualizacao', ultima_atualizacao
                )
                ORDER BY unit_description
            ) AS unidades
        FROM dados
        GROUP BY
            system_parent_description,
            asset_tag_description
    ) s
    GROUP BY
        system_parent_description
) t

  );

END;$$;

--
-- Name: fc_team_descendants(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_team_descendants(team_id bigint) RETURNS TABLE(id bigint, parent_id bigint, code character varying, description character varying, department_id bigint, level integer, full_path text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH RECURSIVE team_descendants AS (
    SELECT
      t.id,
      t.parent_id,
      t.code,
      t.description,
      t.department_id,
      1 AS level,
      t.code::text AS full_path
    FROM public.cfg_teams t
    WHERE t.id = team_id
      AND COALESCE(t.is_deleted, false) = false
      AND t.is_available = true

    UNION ALL

    SELECT
      c.id,
      c.parent_id,
      c.code,
      c.description,
      c.department_id,
      d.level + 1,
      d.full_path || ' > ' || c.code
    FROM public.cfg_teams c
    INNER JOIN team_descendants d ON c.parent_id = d.id
    WHERE COALESCE(c.is_deleted, false) = false
      AND c.is_available = true
  )
  SELECT
    d.id,
    d.parent_id,
    d.code,
    d.description,
    d.department_id,
    d.level,
    d.full_path
  FROM team_descendants d
  --WHERE d.id != team_id --Remover para listar o team_id
  ORDER BY d.full_path;
END;
$$;

--
-- Name: fc_tgr_units_searchable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_tgr_units_searchable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    unit_type_code text;
BEGIN
    SELECT c.code
    INTO unit_type_code
    FROM public.cfg_units_types c
    WHERE c.id = NEW.unit_type_id;

    NEW.description_full :=
        COALESCE(unit_type_code, '') || ' ' || COALESCE(NEW.code, '') || ' ' || COALESCE(NEW.description, '');

    RETURN NEW;
END;
$$;

