--
-- Name: fc_update_op_counter(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_update_op_counter(p_unit_asset_tag_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE cfg_units_assets_tags
    SET op_counter = (
        SELECT COUNT(*)::bigint
        FROM orders
        WHERE orders.unit_asset_tag_id = p_unit_asset_tag_id
          AND orders.unit_asset_tag_has_order = true
          AND (orders.parent_id = 0 OR orders.parent_id IS NULL)
          AND orders.status_id NOT IN (7, 8)
    )
    WHERE cfg_units_assets_tags.id = p_unit_asset_tag_id;
END;
$$;

--
-- Name: fc_update_profile_routes(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_update_profile_routes(p_profile_id bigint, p_routes jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    DELETE FROM public.cfg_profiles_access
    WHERE profile_id = p_profile_id;

    INSERT INTO public.cfg_profiles_access (
        profile_id, route_id, can_view, can_create, can_edit, can_delete, can_search
    )
    SELECT
        p_profile_id,
        (route->>'route_id')::bigint,
        COALESCE((route->>'can_view')::boolean, false),
        COALESCE((route->>'can_create')::boolean, false),
        COALESCE((route->>'can_edit')::boolean, false),
        COALESCE((route->>'can_delete')::boolean, false),
        COALESCE((route->>'can_search')::boolean, false)
    FROM jsonb_array_elements(p_routes) AS route
    WHERE (route->>'route_id') IS NOT NULL;
END;
$$;

--
-- Name: fc_vehicle_monthly_expenses_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_monthly_expenses_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status character varying;
BEGIN
    IF TG_OP <> 'DELETE' THEN
        SELECT p.status INTO v_status
        FROM public.vehicles_rentals_periods p
        WHERE p.vehicle_id = NEW.vehicle_id
          AND p.reference_month = NEW.reference_month;

        IF v_status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Despesas da competência % (veículo %) estão bloqueadas: período % — faça o estorno (fc_vehicle_rental_revert) ou reabra antes de alterar.',
                NEW.reference_month, NEW.vehicle_id, v_status;
        END IF;
    END IF;

    IF TG_OP <> 'INSERT' THEN
        SELECT p.status INTO v_status
        FROM public.vehicles_rentals_periods p
        WHERE p.vehicle_id = OLD.vehicle_id
          AND p.reference_month = OLD.reference_month;

        IF v_status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Despesas da competência % (veículo %) estão bloqueadas: período % — faça o estorno (fc_vehicle_rental_revert) ou reabra antes de alterar.',
                OLD.reference_month, OLD.vehicle_id, v_status;
        END IF;
    END IF;

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

--
-- Name: fc_vehicle_rate_contract(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rate_contract(p_vehicle_id bigint, p_on_date date) RETURNS TABLE(contract_id bigint, value_unit numeric, has_conflict boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT rental.id,
           rental.value_unit,
           (count(*) OVER ()) > 1
    FROM public.cfg_vehicles_rentals_contracts rental
    WHERE rental.vehicle_id = p_vehicle_id
      AND rental.active
      AND NOT rental.is_deleted
      AND rental.start_date <= p_on_date
      AND (rental.end_date IS NULL OR rental.end_date >= p_on_date)
    ORDER BY rental.start_date DESC, rental.id DESC
    LIMIT 1;
END;
$$;

--
-- Name: vehicles_rentals_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicles_rentals_periods (
    id bigint NOT NULL,
    vehicle_id bigint NOT NULL,
    reference_month date NOT NULL,
    contract_id bigint,
    contract_value numeric(14,2) DEFAULT 0 NOT NULL,
    total_km bigint DEFAULT 0 NOT NULL,
    cost_per_km numeric(14,6),
    variable_value numeric(14,2) DEFAULT 0 NOT NULL,
    variable_per_km numeric(14,6),
    allocated_value numeric(14,2) DEFAULT 0 NOT NULL,
    idle_value numeric(14,2) DEFAULT 0 NOT NULL,
    has_conflict boolean DEFAULT false NOT NULL,
    status character varying(20) DEFAULT 'OPEN'::character varying NOT NULL,
    created_user_id bigint,
    created_at timestamp without time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp without time zone,
    CONSTRAINT vehicles_rentals_periods_month_ck CHECK ((reference_month = (date_trunc('month'::text, (reference_month)::timestamp with time zone))::date)),
    CONSTRAINT vehicles_rentals_periods_status_ck CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'CALCULATED'::character varying, 'ALLOCATED'::character varying, 'CLOSED'::character varying])::text[]))),
    CONSTRAINT vehicles_rentals_periods_value_ck CHECK ((contract_value >= (0)::numeric))
);

--
-- Name: TABLE vehicles_rentals_periods; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vehicles_rentals_periods IS 'Competência (mês) de apuração do aluguel de um veículo. status: OPEN -> CALCULATED -> ALLOCATED -> CLOSED. Fechada é imutável (trigger de guarda).';

--
-- Name: COLUMN vehicles_rentals_periods.variable_per_km; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.vehicles_rentals_periods.variable_per_km IS 'Reservado para a Fase 2 (custos variáveis reais por Km).';

--
-- Name: fc_vehicle_rental_allocate(bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_allocate(p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL::bigint) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_month_end date := (date_trunc('month', p_reference_month::timestamp) + interval '1 month - 1 day')::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_line record;
    v_rental_rate numeric;
    v_var_rate numeric;
    v_fixed_rate numeric;
    v_appropriate_rate numeric;
    v_alloc_total numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);

    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month
    FOR UPDATE;

    IF v_period.id IS NULL THEN
        RAISE EXCEPTION 'Competência % do veículo % não foi calculada: execute o cálculo antes da alocação.',
            v_month, p_vehicle_id;
    END IF;

    IF v_period.status NOT IN ('CALCULATED', 'ALLOCATED') THEN
        RAISE EXCEPTION 'Competência % está %: reabra antes de alocar.',
            v_month, v_period.status;
    END IF;

    IF v_period.cost_per_km IS NULL THEN
        RAISE EXCEPTION 'Competência % sem Km rodado: nada a alocar (aluguel e despesas ficam integralmente em ociosidade).',
            v_month;
    END IF;

    v_rental_rate := CASE
        WHEN v_period.contract_id IS NOT NULL AND v_period.total_km > 0
            THEN round(v_period.contract_value / v_period.total_km::numeric, 6)
        ELSE NULL
    END;
    v_var_rate := CASE
        WHEN COALESCE(v_period.variable_value, 0) > 0 AND v_period.total_km > 0
            THEN round(v_period.variable_value / v_period.total_km::numeric, 6)
        ELSE NULL
    END;

    SELECT contract.value_unit
      INTO v_fixed_rate
    FROM public.fc_vehicle_rate_contract(p_vehicle_id, v_month) contract;

    IF v_fixed_rate IS NULL THEN
        SELECT contract.value_unit
          INTO v_fixed_rate
        FROM public.fc_vehicle_rate_contract(p_vehicle_id, v_month_end) contract;
    END IF;

    v_appropriate_rate :=
        COALESCE(v_rental_rate, 0)
        + COALESCE(v_var_rate, 0)
        + COALESCE(v_fixed_rate, 0);

    FOR v_line IN
        SELECT ovv.id AS ovv_id,
               ovv.ov_id,
               ovv.amount AS km
        FROM public.orders_visits_vehicles ovv
        JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
        WHERE ovv.vehicle_id = p_vehicle_id
          AND NOT ovv.is_deleted
          AND ovv.cost_type IN ('odometer', 'rate')
          AND ovv.amount > 0
          AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
          AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month'
        ORDER BY ovv.id
    LOOP
        IF v_period.contract_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM public.vehicles_rentals_allocations a
            WHERE a.period_id = v_period.id
              AND a.ovv_id = v_line.ovv_id
              AND a.cost_component = 'RENTAL'
        ) THEN
            INSERT INTO public.vehicles_rentals_allocations (
                period_id, ov_id, ovv_id, rental_ovv_id, km, rate, value,
                cost_component, created_at
            ) VALUES (
                v_period.id, v_line.ov_id, v_line.ovv_id, NULL,
                v_line.km, v_rental_rate, round(v_line.km * v_rental_rate, 2), 'RENTAL', now()
            )
            ON CONFLICT (period_id, ovv_id, cost_component) DO NOTHING;
        END IF;

        IF v_var_rate IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM public.vehicles_rentals_allocations a
            WHERE a.period_id = v_period.id
              AND a.ovv_id = v_line.ovv_id
              AND a.cost_component = 'VARIABLE'
        ) THEN
            INSERT INTO public.vehicles_rentals_allocations (
                period_id, ov_id, ovv_id, rental_ovv_id, km, rate, value,
                cost_component, created_at
            ) VALUES (
                v_period.id, v_line.ov_id, v_line.ovv_id, NULL,
                v_line.km, v_var_rate, round(v_line.km * v_var_rate, 2), 'VARIABLE', now()
            )
            ON CONFLICT (period_id, ovv_id, cost_component) DO NOTHING;
        END IF;

        UPDATE public.orders_visits_vehicles ovv
        SET cost_type = 'rate',
            value_unit = v_appropriate_rate
        WHERE ovv.id = v_line.ovv_id
          AND ovv.cost_type IN ('odometer', 'rate');
    END LOOP;

    SELECT COALESCE(sum(a.value), 0)
      INTO v_alloc_total
    FROM public.vehicles_rentals_allocations a
    WHERE a.period_id = v_period.id;

    UPDATE public.vehicles_rentals_periods p
    SET allocated_value = v_alloc_total,
        idle_value = (p.contract_value + COALESCE(p.variable_value, 0)) - v_alloc_total,
        status = 'ALLOCATED',
        updated_user_id = p_user_id,
        updated_at = now()
    WHERE p.id = v_period.id;

    RETURN QUERY
    SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.id = v_period.id;
END;
$$;

--
-- Name: fc_vehicle_rental_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status character varying;
BEGIN
    IF coalesce(current_setting('app.vehicle_rental_write', true), '') = '1' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Rateio de aluguel é gerado pela apuração mensal e não pode ser editado diretamente.';
    END IF;

    SELECT p.status INTO v_status
    FROM public.vehicles_rentals_periods p
    WHERE p.id = OLD.period_id;

    IF v_status = 'CLOSED' THEN
        RAISE EXCEPTION 'Competência fechada: o rateio é imutável (reabra a competência para alterar).';
    END IF;

    RETURN OLD;
END;
$$;

--
-- Name: fc_vehicle_rental_calculate(bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_calculate(p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL::bigint) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_contract_id bigint;
    v_contract_value numeric;
    v_has_conflict boolean;
    v_total_km bigint;
    v_expenses numeric;
    v_rate numeric;
    v_rental_rate numeric;
    v_var_rate numeric;
    v_alloc numeric;
    v_alloc_rental numeric;
    v_alloc_variable numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);

    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month
    FOR UPDATE;

    IF v_period.id IS NOT NULL AND v_period.status IN ('ALLOCATED', 'CLOSED') THEN
        RAISE EXCEPTION 'Competência % do veículo % já alocada/fechada: faça o estorno antes de recalcular.',
            v_month, p_vehicle_id;
    END IF;

    SELECT COALESCE(sum(e.value), 0)
    INTO v_expenses
    FROM public.vehicles_monthly_expenses e
    WHERE e.vehicle_id = p_vehicle_id
      AND e.reference_month = v_month;

    SELECT c.contract_id, c.monthly_value, c.has_conflict
    INTO v_contract_id, v_contract_value, v_has_conflict
    FROM public.fc_vehicle_rental_contract(p_vehicle_id, v_month) c;

    IF v_contract_id IS NULL THEN
        IF COALESCE(v_expenses, 0) > 0 THEN
            v_contract_value := 0;
            v_has_conflict := false;
        ELSE
            RAISE EXCEPTION 'Sem contrato de aluguel e sem despesas no mês: nada a apurar para o veículo % na competência %.',
                p_vehicle_id, v_month;
        END IF;
    END IF;

    SELECT COALESCE(sum(ovv.amount), 0)::bigint
    INTO v_total_km
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

    v_rate := CASE
        WHEN v_total_km > 0 THEN round((COALESCE(v_contract_value,0) + v_expenses) / v_total_km::numeric, 6)
        ELSE NULL
    END;
    v_rental_rate := CASE
        WHEN v_total_km > 0 THEN round(COALESCE(v_contract_value,0) / v_total_km::numeric, 6)
        ELSE NULL
    END;
    v_var_rate := CASE
        WHEN v_total_km > 0 AND v_expenses > 0 THEN round(v_expenses / v_total_km::numeric, 6)
        ELSE NULL
    END;

    SELECT COALESCE(sum(round(ovv.amount * v_rental_rate, 2)), 0),
           COALESCE(sum(round(ovv.amount * v_var_rate, 2)), 0)
    INTO v_alloc_rental, v_alloc_variable
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

    v_alloc := v_alloc_rental + v_alloc_variable;

    INSERT INTO public.vehicles_rentals_periods (
        vehicle_id, reference_month, contract_id, contract_value, total_km,
        cost_per_km, variable_value, variable_per_km, allocated_value,
        idle_value, has_conflict, status,
        created_user_id, created_at, updated_user_id, updated_at
    ) VALUES (
        p_vehicle_id, v_month, v_contract_id, COALESCE(v_contract_value, 0), v_total_km,
        v_rate, v_expenses, v_var_rate, v_alloc,
        (COALESCE(v_contract_value,0) + v_expenses) - v_alloc, COALESCE(v_has_conflict, false), 'CALCULATED',
        p_user_id, now(), p_user_id, now()
    )
    ON CONFLICT (vehicle_id, reference_month) DO UPDATE SET
        contract_id = EXCLUDED.contract_id,
        contract_value = EXCLUDED.contract_value,
        total_km = EXCLUDED.total_km,
        cost_per_km = EXCLUDED.cost_per_km,
        variable_value = EXCLUDED.variable_value,
        variable_per_km = EXCLUDED.variable_per_km,
        allocated_value = EXCLUDED.allocated_value,
        idle_value = EXCLUDED.idle_value,
        has_conflict = EXCLUDED.has_conflict,
        status = 'CALCULATED',
        updated_user_id = EXCLUDED.updated_user_id,
        updated_at = now();

    RETURN QUERY
    SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month;
END;
$$;

--
-- Name: fc_vehicle_rental_close(bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_close(p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL::bigint) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);

    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month
    FOR UPDATE;

    IF v_period.id IS NULL OR v_period.status = 'OPEN' THEN
        RAISE EXCEPTION 'Competência % do veículo % não foi calculada.', v_month, p_vehicle_id;
    END IF;

    IF v_period.status = 'CLOSED' THEN
        RAISE EXCEPTION 'Competência % do veículo % já está fechada.', v_month, p_vehicle_id;
    END IF;

    IF v_period.status = 'CALCULATED' AND v_period.total_km > 0 THEN
        RAISE EXCEPTION 'Há Km para alocar na competência %: execute a alocação antes de fechar.', v_month;
    END IF;

    UPDATE public.vehicles_rentals_periods p
    SET status = 'CLOSED',
        updated_user_id = p_user_id,
        updated_at = now()
    WHERE p.id = v_period.id;

    RETURN QUERY
    SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.id = v_period.id;
END;
$$;

--
-- Name: fc_vehicle_rental_contract(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_contract(p_vehicle_id bigint, p_reference_month date) RETURNS TABLE(contract_id bigint, monthly_value numeric, has_conflict boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_month_end date := (date_trunc('month', p_reference_month::timestamp) + interval '1 month - 1 day')::date;
BEGIN
    RETURN QUERY
    SELECT c.id,
           c.monthly_value,
           (count(*) OVER ()) > 1
    FROM public.cfg_vehicles_rentals_contracts c
    WHERE c.vehicle_id = p_vehicle_id
      AND c.active
      AND NOT c.is_deleted
      AND c.start_date <= v_month_end
      AND (c.end_date IS NULL OR c.end_date >= v_month)
    ORDER BY c.start_date DESC, c.id DESC
    LIMIT 1;
END;
$$;

--
-- Name: fc_vehicle_rental_detail(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_detail(p_vehicle_id bigint, p_reference_month date) RETURNS TABLE(period_id bigint, period_status character varying, ov_id bigint, ovv_id bigint, visit_mask character varying, km bigint, rate numeric, value numeric, rental_value numeric, variable_value numeric, rental_ovv_id bigint, variable_ovv_id bigint, operational_value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_contract numeric;
    v_variable numeric;
    v_rate numeric;
    v_rental_rate numeric;
    v_var_rate numeric;
    v_rate_km bigint;
    v_total bigint;
BEGIN
    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month;

    SELECT COALESCE(sum(ovv.amount), 0)::bigint
    INTO v_total
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

    IF v_period.id IS NOT NULL AND v_period.status IN ('ALLOCATED', 'CLOSED') THEN
        v_contract := COALESCE(v_period.contract_value, 0);
        v_variable := COALESCE(v_period.variable_value, 0);
        v_rate_km := v_period.total_km;
        v_rate := v_period.cost_per_km;
    ELSE
        SELECT c.monthly_value INTO v_contract
        FROM public.fc_vehicle_rental_contract(p_vehicle_id, v_month) c;

        v_contract := COALESCE(v_contract, 0);

        SELECT COALESCE(sum(e.value), 0) INTO v_variable
        FROM public.vehicles_monthly_expenses e
        WHERE e.vehicle_id = p_vehicle_id
          AND e.reference_month = v_month;

        v_rate_km := v_total;
        v_rate := CASE
            WHEN v_total > 0 THEN (v_contract + v_variable) / v_total::numeric
            ELSE NULL
        END;
    END IF;

    v_rental_rate := CASE
        WHEN v_rate_km > 0 THEN round(v_contract / v_rate_km::numeric, 6)
        ELSE NULL
    END;
    v_var_rate := CASE
        WHEN v_rate_km > 0 AND v_variable > 0 THEN round(v_variable / v_rate_km::numeric, 6)
        ELSE NULL
    END;

    RETURN QUERY
    SELECT
        v_period.id,
        COALESCE(v_period.status, 'OPEN')::character varying,
        ovv.ov_id,
        ovv.id,
        ovs.ov_mask,
        ovv.amount,
        v_rate,
        COALESCE(round(ovv.amount * v_rental_rate, 2), 0)
            + COALESCE(round(ovv.amount * v_var_rate, 2), 0),
        round(ovv.amount * v_rental_rate, 2),
        round(ovv.amount * v_var_rate, 2),
        a_rental.rental_ovv_id,
        a_var.rental_ovv_id,
        ovv.value_total
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    LEFT JOIN public.vehicles_rentals_allocations a_rental
           ON a_rental.ovv_id = ovv.id
          AND a_rental.period_id IS NOT DISTINCT FROM v_period.id
          AND a_rental.cost_component = 'RENTAL'
    LEFT JOIN public.vehicles_rentals_allocations a_var
           ON a_var.ovv_id = ovv.id
          AND a_var.period_id IS NOT DISTINCT FROM v_period.id
          AND a_var.cost_component = 'VARIABLE'
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month'
    ORDER BY COALESCE(ovv.created_at, ovs.ov_created_at), ovv.id;
END;
$$;

--
-- Name: fc_vehicle_rental_period_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_period_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF coalesce(current_setting('app.vehicle_rental_write', true), '') = '1' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF TG_OP = 'DELETE' THEN
        IF OLD.status IN ('ALLOCATED', 'CLOSED') THEN
            RAISE EXCEPTION 'Competência % do veículo % não pode ser excluída: rateio já alocado/fechado. Use a apuração (fc_vehicle_rental_revert).',
                OLD.reference_month, OLD.vehicle_id;
        END IF;
        RETURN OLD;
    END IF;

    RAISE EXCEPTION 'Período de rateio de aluguel é gerenciado exclusivamente pelas RPCs de apuração (fc_vehicle_rental_*).';
END;
$$;

--
-- Name: fc_vehicle_rental_reopen(bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_reopen(p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL::bigint) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);

    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month
    FOR UPDATE;

    IF v_period.id IS NULL THEN
        RAISE EXCEPTION 'Competência % do veículo % não existe.', v_month, p_vehicle_id;
    END IF;

    IF v_period.status <> 'CLOSED' THEN
        RAISE EXCEPTION 'Somente competências fechadas podem ser reabertas (status atual: %).', v_period.status;
    END IF;

    UPDATE public.vehicles_rentals_periods p
    SET status = CASE
            WHEN EXISTS (
                SELECT 1 FROM public.vehicles_rentals_allocations a
                WHERE a.period_id = p.id
            ) THEN 'ALLOCATED'
            ELSE 'CALCULATED'
        END,
        updated_user_id = p_user_id,
        updated_at = now()
    WHERE p.id = v_period.id;

    RETURN QUERY
    SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.id = v_period.id;
END;
$$;

--
-- Name: fc_vehicle_rental_revert(bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_revert(p_vehicle_id bigint, p_reference_month date, p_user_id bigint DEFAULT NULL::bigint) RETURNS SETOF public.vehicles_rentals_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_total_km bigint;
    v_expenses numeric;
    v_rate numeric;
    v_rental_rate numeric;
    v_var_rate numeric;
    v_alloc numeric;
    v_alloc_rental numeric;
    v_alloc_variable numeric;
BEGIN
    PERFORM set_config('app.vehicle_rental_write', '1', true);

    SELECT p.* INTO v_period
    FROM public.vehicles_rentals_periods p
    WHERE p.vehicle_id = p_vehicle_id
      AND p.reference_month = v_month
    FOR UPDATE;

    IF v_period.id IS NULL THEN
        RAISE EXCEPTION 'Competência % do veículo % não existe.', v_month, p_vehicle_id;
    END IF;

    IF v_period.status = 'CLOSED' THEN
        RAISE EXCEPTION 'Competência % está fechada: reabra antes de estornar.', v_month;
    END IF;

    IF v_period.status <> 'ALLOCATED' THEN
        RAISE EXCEPTION 'Competência % não tem rateio alocado (status: %).', v_month, v_period.status;
    END IF;

    UPDATE public.orders_visits_vehicles ovv
    SET cost_type = 'odometer'
    WHERE ovv.cost_type = 'rate'
      AND ovv.id IN (
          SELECT a.ovv_id
          FROM public.vehicles_rentals_allocations a
          WHERE a.period_id = v_period.id
      );

    DELETE FROM public.orders_visits_vehicles ovv
    WHERE ovv.id IN (
        SELECT a.rental_ovv_id
        FROM public.vehicles_rentals_allocations a
        WHERE a.period_id = v_period.id
          AND a.rental_ovv_id IS NOT NULL
    );

    DELETE FROM public.vehicles_rentals_allocations a
    WHERE a.period_id = v_period.id;

    SELECT COALESCE(sum(ovv.amount), 0)::bigint
    INTO v_total_km
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

    SELECT COALESCE(sum(e.value), 0)
    INTO v_expenses
    FROM public.vehicles_monthly_expenses e
    WHERE e.vehicle_id = p_vehicle_id
      AND e.reference_month = v_month;

    v_rate := CASE
        WHEN v_total_km > 0 THEN round((v_period.contract_value + v_expenses) / v_total_km::numeric, 6)
        ELSE NULL
    END;
    v_rental_rate := CASE
        WHEN v_total_km > 0 THEN round(v_period.contract_value / v_total_km::numeric, 6)
        ELSE NULL
    END;
    v_var_rate := CASE
        WHEN v_total_km > 0 AND v_expenses > 0 THEN round(v_expenses / v_total_km::numeric, 6)
        ELSE NULL
    END;

    SELECT COALESCE(sum(round(ovv.amount * v_rental_rate, 2)), 0),
           COALESCE(sum(round(ovv.amount * v_var_rate, 2)), 0)
    INTO v_alloc_rental, v_alloc_variable
    FROM public.orders_visits_vehicles ovv
    JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
    WHERE ovv.vehicle_id = p_vehicle_id
      AND NOT ovv.is_deleted
      AND ovv.cost_type IN ('odometer', 'rate')
      AND ovv.amount > 0
      AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
      AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

    v_alloc := v_alloc_rental + v_alloc_variable;

    UPDATE public.vehicles_rentals_periods p
    SET total_km = v_total_km,
        cost_per_km = v_rate,
        variable_value = v_expenses,
        variable_per_km = v_var_rate,
        allocated_value = v_alloc,
        idle_value = (p.contract_value + v_expenses) - v_alloc,
        status = 'CALCULATED',
        updated_user_id = p_user_id,
        updated_at = now()
    WHERE p.id = v_period.id;

    RETURN QUERY
    SELECT p.* FROM public.vehicles_rentals_periods p
    WHERE p.id = v_period.id;
END;
$$;

--
-- Name: fc_vehicle_rental_summary(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fc_vehicle_rental_summary(p_reference_month date) RETURNS TABLE(period_id bigint, period_status character varying, vehicle_id bigint, vehicle_description text, vehicle_plates text, contract_id bigint, contract_value numeric, has_conflict boolean, total_km bigint, cost_per_km numeric, allocated_value numeric, idle_value numeric, utilization numeric, variable_value numeric, variable_per_km numeric, operational_value numeric, operational_per_km numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_month date := (date_trunc('month', p_reference_month::timestamp))::date;
    v_month_end date := (date_trunc('month', p_reference_month::timestamp) + interval '1 month - 1 day')::date;
    v_row record;
    v_period public.vehicles_rentals_periods%ROWTYPE;
    v_km bigint;
    v_rate numeric;
    v_rental_rate numeric;
    v_var_rate numeric;
    v_alloc numeric;
    v_alloc_rental numeric;
    v_alloc_variable numeric;
    v_value numeric;
    v_variable numeric;
    v_op numeric;
BEGIN
    FOR v_row IN
        WITH contract_info AS (
            SELECT c.vehicle_id,
                   count(*) AS n_contracts,
                   (array_agg(c.id ORDER BY c.start_date DESC, c.id DESC))[1] AS best_id,
                   (array_agg(c.monthly_value ORDER BY c.start_date DESC, c.id DESC))[1] AS best_value
            FROM public.cfg_vehicles_rentals_contracts c
            WHERE c.active AND NOT c.is_deleted
              AND c.start_date <= v_month_end
              AND (c.end_date IS NULL OR c.end_date >= v_month)
            GROUP BY c.vehicle_id
        ),
        base AS (
            SELECT u.vvehicle, u.vcid, u.vvalue, u.prio
            FROM (
                SELECT p.vehicle_id AS vvehicle, p.contract_id AS vcid,
                       p.contract_value AS vvalue, 0 AS prio
                FROM public.vehicles_rentals_periods p
                WHERE p.reference_month = v_month
                UNION ALL
                SELECT ci.vehicle_id, ci.best_id, ci.best_value, 1
                FROM contract_info ci
                UNION ALL
                SELECT e.vehicle_id, NULL::bigint, NULL::numeric, 2
                FROM public.vehicles_monthly_expenses e
                WHERE e.reference_month = v_month
                GROUP BY e.vehicle_id
                UNION ALL
                SELECT rc.vehicle_id, NULL::bigint, NULL::numeric, 3
                FROM public.cfg_vehicle_rate_contracts rc
                WHERE rc.active AND NOT rc.is_deleted
                  AND rc.start_date <= v_month_end
                  AND (rc.end_date IS NULL OR rc.end_date >= v_month)
                GROUP BY rc.vehicle_id
            ) u
        )
        SELECT DISTINCT ON (b.vvehicle)
               b.vvehicle, b.vcid, b.vvalue,
               COALESCE(ci.n_contracts, 0) > 1 AS vconflict,
               ve.description AS vd, ve.plates AS vp
        FROM base b
        LEFT JOIN contract_info ci ON ci.vehicle_id = b.vvehicle
        JOIN public.vehicles ve ON ve.id = b.vvehicle AND NOT ve.is_deleted
        ORDER BY b.vvehicle, b.prio, ve.description
    LOOP
        SELECT p.* INTO v_period
        FROM public.vehicles_rentals_periods p
        WHERE p.vehicle_id = v_row.vvehicle
          AND p.reference_month = v_month;

        SELECT COALESCE(sum(ovv.amount), 0)::bigint,
               COALESCE(sum(ovv.value_total), 0)
        INTO v_km, v_op
        FROM public.orders_visits_vehicles ovv
        JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
        WHERE ovv.vehicle_id = v_row.vvehicle
          AND NOT ovv.is_deleted
          AND ovv.cost_type IN ('odometer', 'rate')
          AND ovv.amount > 0
          AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
          AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

        v_value := COALESCE(v_period.contract_value, v_row.vvalue, 0);

        SELECT COALESCE(sum(e.value), 0)
        INTO v_variable
        FROM public.vehicles_monthly_expenses e
        WHERE e.vehicle_id = v_row.vvehicle
          AND e.reference_month = v_month;

        IF v_period.id IS NOT NULL THEN
            period_id := v_period.id;
            period_status := v_period.status;
        ELSE
            period_id := NULL;
            period_status := 'OPEN';
        END IF;

        IF v_period.id IS NOT NULL AND v_period.status IN ('ALLOCATED', 'CLOSED') THEN
            total_km := v_period.total_km;
            v_rate := v_period.cost_per_km;
            v_alloc := v_period.allocated_value;
            v_variable := COALESCE(v_period.variable_value, 0);
        ELSE
            total_km := v_km;
            v_rate := CASE WHEN v_km > 0 THEN (v_value + v_variable) / v_km::numeric ELSE NULL END;
            v_rental_rate := CASE WHEN v_km > 0 THEN v_value / v_km::numeric ELSE NULL END;
            v_var_rate := CASE WHEN v_km > 0 AND v_variable > 0 THEN v_variable / v_km::numeric ELSE NULL END;

            SELECT COALESCE(sum(round(ovv.amount * v_rental_rate, 2)), 0),
                   COALESCE(sum(round(ovv.amount * v_var_rate, 2)), 0)
            INTO v_alloc_rental, v_alloc_variable
            FROM public.orders_visits_vehicles ovv
            JOIN public.orders_visits ovs ON ovs.id = ovv.ov_id
            WHERE ovv.vehicle_id = v_row.vvehicle
              AND NOT ovv.is_deleted
              AND ovv.cost_type IN ('odometer', 'rate')
              AND ovv.amount > 0
              AND COALESCE(ovv.created_at, ovs.ov_created_at) >= v_month
              AND COALESCE(ovv.created_at, ovs.ov_created_at) < v_month + interval '1 month';

            v_alloc := v_alloc_rental + v_alloc_variable;
        END IF;

        vehicle_id := v_row.vvehicle;
        vehicle_description := v_row.vd;
        vehicle_plates := v_row.vp;
        contract_id := v_row.vcid;
        contract_value := v_value;
        has_conflict := v_row.vconflict;
        cost_per_km := v_rate;
        allocated_value := v_alloc;
        idle_value := (v_value + v_variable) - v_alloc;
        utilization := CASE
            WHEN (v_value + v_variable) > 0 THEN round(v_alloc / (v_value + v_variable), 4)
            ELSE NULL
        END;
        variable_value := v_variable;
        variable_per_km := CASE
            WHEN total_km > 0 AND v_variable > 0 THEN round(v_variable / total_km::numeric, 6)
            ELSE NULL
        END;
        operational_value := v_op;
        operational_per_km := CASE
            WHEN total_km > 0 THEN round(v_op / total_km::numeric, 6)
            ELSE NULL
        END;

        RETURN NEXT;
    END LOOP;
END;
$$;

--
-- Name: flow_order_visit_close_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_close_v2(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    p_visit_id BIGINT;
    p_user_id BIGINT;
    p_order_status_id INTEGER;
    p_suspended_reason_id INTEGER;
    p_progress INTEGER;
    p_vehicles_check_override BOOLEAN;

    v_visit RECORD;
    v_order RECORD;
    v_user_name_short TEXT;
    v_notification_body TEXT;
    v_timestamp TIMESTAMP;
BEGIN
    -- 1. Extração de parâmetros
    p_visit_id := (payload->>'visit_id')::BIGINT;
    p_user_id := (payload->>'user_id')::BIGINT;
    p_order_status_id := (payload->>'order_status_id')::INTEGER;
    
    IF (payload->>'suspended_reason_id') IS NULL OR (payload->>'suspended_reason_id') = 'null' THEN
        p_suspended_reason_id := NULL;
    ELSE
        p_suspended_reason_id := (payload->>'suspended_reason_id')::INTEGER;
    END IF;

    IF (payload->>'progress') IS NULL OR (payload->>'progress') = 'null' THEN
        p_progress := NULL;
    ELSE
        p_progress := (payload->>'progress')::INTEGER;
    END IF;

    p_vehicles_check_override := COALESCE((payload->>'vehicles_check_override')::BOOLEAN, FALSE);
    v_timestamp := timezone('America/Sao_Paulo', CURRENT_TIMESTAMP);

    -- 2. Validar Visita e OS
    SELECT id, o_id, ov_status_id INTO v_visit FROM orders_visits WHERE id = p_visit_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Visita não encontrada.');
    END IF;

    IF v_visit.ov_status_id = 2 THEN
         RETURN jsonb_build_object('success', false, 'message', 'Visita já está encerrada.');
    END IF;

    SELECT id, mask, client_name, unit_description, requested_services INTO v_order FROM v_orders WHERE id = v_visit.o_id;

    SELECT name_short INTO v_user_name_short FROM users WHERE id = p_user_id;

    -- 3. Atualizar orders_visits
    UPDATE orders_visits
    SET 
        ov_ended_at = v_timestamp,
        ov_status_id = 2, -- Encerrada
        ov_o_status_id = p_order_status_id,
        ov_o_suspended_reason_id = CASE WHEN p_order_status_id = 6 THEN p_suspended_reason_id ELSE NULL END,
        ov_o_progress = CASE WHEN p_order_status_id = 8 THEN 1 ELSE p_progress / 100.0 END
    WHERE id = p_visit_id;

    -- 4. Atualizar orders
    UPDATE orders
    SET
        status_id = p_order_status_id,
        suspended_reason_id = CASE WHEN p_order_status_id = 6 THEN p_suspended_reason_id ELSE suspended_reason_id END,
        progress = CASE WHEN p_order_status_id = 8 THEN 1 ELSE p_progress / 100.0 END,
        status_at = v_timestamp
    WHERE id = v_visit.o_id;

    -- 5. Liberar equipe em batch
    UPDATE users
    SET
        is_available = TRUE,
        ov_in_progress_leader_id = 0,
        o_contract_id_in_progress = 0,
        o_type_id_in_progress = 0,
        o_type_sub_id_in_progress = 0,
        o_plan_id_in_progress = 0,
        o_asset_tag_id_in_progress = 0,
        o_unit_id_in_progress = 0,
        o_system_id_in_progress = 0,
        o_system_parent_id_in_progress = 0,
        o_unit_type_id_in_progress = 0,
        o_unit_type_parent_id_in_progress = 0,
        o_object_id_in_progress = 0,
        ov_id_in_progress = 0,
        o_id_in_progress = 0,
        op_id_in_progress = 0,
        is_ov_in_progress = FALSE,
        ov_id_in_progress_mask = NULL
    WHERE id IN (
        SELECT user_id FROM orders_visits_teams WHERE ov_id = p_visit_id
    );

    -- 6. Enviar Notificações em LOTE (INSERT ... SELECT direto em 1 comando, SEM LOOP!)
    v_notification_body := COALESCE(v_user_name_short, 'Equipe') || ' encerrou a visita:' || E'\n' ||
                           'OS ' || COALESCE(v_order.mask, '') || E'\n' ||
                           'Cliente: ' || COALESCE(v_order.client_name, '') || E'\n' ||
                           'Unidade: ' || COALESCE(v_order.unit_description, '');

    INSERT INTO users_notifications (
        user_id_to,
        user_id_from,
        title,
        body,
        type,
        user_to_whatsapp,
        created_at,
        is_read
    )
    SELECT 
        f.user_id,
        p_user_id,
        'Visita encerrada.',
        v_notification_body,
        'Visita encerrada',
        u.mobile_whatsapp,
        v_timestamp,
        FALSE
    FROM orders_followers f
    JOIN users u ON u.id = f.user_id
    WHERE f.o_id = v_visit.o_id;

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Visita encerrada com sucesso.',
        'visit_id', p_visit_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Erro ao encerrar visita: ' || SQLERRM);
END;
$$;

--
-- Name: flow_order_visit_close_v3(bigint, bigint, integer, text, bigint, bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_close_v3(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_now        TIMESTAMP := timezone('America/Sao_Paulo', now());
    v_end        TIMESTAMP;
    v_user       RECORD;
    v_started_at TIMESTAMP;
    v_contract   BIGINT;
    v_manual_ok  BOOLEAN := false;
    v_order      RECORD;
    v_target     RECORD;
    v_team_ids   BIGINT[];
    v_client     TEXT;
    v_unit       TEXT;
    v_tag        TEXT;
    v_tag_sub    TEXT;
BEGIN
    SELECT u.id, u.name_short, u.name_full INTO v_user
      FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user.id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    -- 1. Veículos
    IF EXISTS (
        SELECT 1 FROM public.orders_visits_vehicles v
         WHERE v.ov_id = p_visit_id
           AND v.cost_type IS DISTINCT FROM 'idle'
           AND (v.recorder_start IS NULL OR v.recorder_end IS NULL
                OR v.recorder_start::numeric >= v.recorder_end::numeric)
    ) THEN
        RAISE EXCEPTION 'Existem veículos com apontamento inválido ou incompleto (Km Inicial >= Km Final).'
            USING ERRCODE = '22023';
    END IF;

    -- 2. Encerramento manual
    v_end := v_now;
    IF NULLIF(btrim(COALESCE(p_ended_at, '')), '') IS NOT NULL THEN
        SELECT ov.ov_started_at INTO v_started_at FROM public.orders_visits ov WHERE ov.id = p_visit_id;
        SELECT o.contract_id INTO v_contract FROM public.orders o WHERE o.id = p_order_id;
        IF v_contract IS NOT NULL THEN
            -- to_jsonb: não quebra se a coluna ainda não existir no banco.
            SELECT COALESCE((to_jsonb(c) ->> 'is_manual_visit_start_end')::boolean, false)
              INTO v_manual_ok
              FROM public.contracts c WHERE c.id = v_contract;
        END IF;
        IF COALESCE(v_manual_ok, false) THEN
            v_end := replace(p_ended_at, 'T', ' ')::timestamp;
            IF v_started_at IS NOT NULL AND v_end < v_started_at THEN
                RAISE EXCEPTION 'Data/hora de encerramento não pode ser anterior ao início da visita.'
                    USING ERRCODE = '22023';
            END IF;
        END IF;
    END IF;

    -- 3. Visita
    UPDATE public.orders_visits
       SET ov_ended_at    = v_end,
           ov_status_id   = 2,
           ov_o_status_id = p_status_id,
           ov_o_progress  = CASE WHEN p_status_id = 8 THEN 1 ELSE p_progress / 100 END,
           ov_o_suspended_reason_id = CASE
               WHEN p_status_id = 6 AND p_suspended_reason_id IS NOT NULL THEN p_suspended_reason_id
               ELSE ov_o_suspended_reason_id END
     WHERE id = p_visit_id;

    -- 4. OS
    UPDATE public.orders
       SET status_id = p_status_id,
           status_at = v_end,
           progress  = CASE WHEN p_status_id = 8 THEN 1 ELSE p_progress / 100 END,
           cause_reason_id = p_cause_reason_id
     WHERE id = p_order_id
    RETURNING parent_id, order_mask, requested_services, client_id, unit_id, asset_tag_id, asset_tag_sub_id
      INTO v_order;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'OS % não encontrada ou sem permissão para alterar.', p_order_id USING ERRCODE = 'P0002';
    END IF;

    -- 5. SS pai
    IF v_order.parent_id IS NOT NULL THEN
        SELECT o.status_id, o.status_at, o.cancel_reason_id, o.cancel_comments,
               o.canceled_user_id, o.canceled_team_id, o.canceled_at
          INTO v_target
          FROM public.orders o
          LEFT JOIN public.cfg_orders_statuses s ON s.id = o.status_id
         WHERE o.parent_id = v_order.parent_id
           AND o.is_deleted = false
         ORDER BY COALESCE(s.priority_level, 0) DESC, o.status_at DESC NULLS LAST
         LIMIT 1;

        IF FOUND THEN
            UPDATE public.orders
               SET status_id  = v_target.status_id,
                   status_at  = v_target.status_at,
                   updated_at = v_now,
                   cancel_reason_id = CASE WHEN v_target.status_id = 7 THEN v_target.cancel_reason_id ELSE cancel_reason_id END,
                   cancel_comments  = CASE WHEN v_target.status_id = 7 THEN v_target.cancel_comments  ELSE cancel_comments  END,
                   canceled_user_id = CASE WHEN v_target.status_id = 7 THEN v_target.canceled_user_id ELSE canceled_user_id END,
                   canceled_team_id = CASE WHEN v_target.status_id = 7 THEN v_target.canceled_team_id ELSE canceled_team_id END,
                   canceled_at      = CASE WHEN v_target.status_id = 7 THEN COALESCE(v_target.canceled_at, v_target.status_at) ELSE canceled_at END
             WHERE id = v_order.parent_id;
        END IF;
    END IF;

    -- 6. Equipe
    SELECT array_agg(DISTINCT t.user_id) INTO v_team_ids
      FROM public.orders_visits_teams t WHERE t.ov_id = p_visit_id;
    IF v_team_ids IS NULL THEN
        SELECT array_agg(u.id) INTO v_team_ids
          FROM public.users u WHERE u.ov_id_in_progress = p_visit_id;
    END IF;

    IF v_team_ids IS NOT NULL THEN
        UPDATE public.users
           SET is_available = true,
               ov_in_progress_leader_id = 0,
               o_contract_id_in_progress = 0,
               o_type_id_in_progress = 0,
               o_type_sub_id_in_progress = 0,
               o_plan_id_in_progress = 0,
               o_asset_tag_id_in_progress = 0,
               o_unit_id_in_progress = 0,
               o_system_id_in_progress = 0,
               o_system_parent_id_in_progress = 0,
               o_unit_type_id_in_progress = 0,
               o_unit_type_parent_id_in_progress = 0,
               o_object_id_in_progress = 0,
               ov_id_in_progress = 0,
               o_id_in_progress = 0,
               op_id_in_progress = 0,
               is_ov_in_progress = false,
               ov_id_in_progress_mask = NULL,
               updated_at = v_now
         WHERE id = ANY (v_team_ids);
    END IF;

    -- 7. Seguidores da SS pai
    IF v_order.parent_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.orders_followers f WHERE f.o_id = v_order.parent_id) THEN
        SELECT c.description INTO v_client FROM public.v_companies c WHERE c.id = v_order.client_id;
        SELECT u.description INTO v_unit   FROM public.units u WHERE u.id = v_order.unit_id;
        IF v_order.asset_tag_id IS NOT NULL THEN
            SELECT t.description INTO v_tag FROM public.cfg_assets_tags t WHERE t.id = v_order.asset_tag_id;
        END IF;
        IF v_order.asset_tag_sub_id IS NOT NULL THEN
            SELECT t.description INTO v_tag_sub FROM public.cfg_assets_tags_subs t WHERE t.id = v_order.asset_tag_sub_id;
        END IF;

        INSERT INTO public.users_notifications
               (user_id_to, user_id_from, title, body, type, created_at, is_read, user_to_whatsapp)
        SELECT f.user_id,
               v_user.id,
               'Visita encerrada.',
               COALESCE(NULLIF(v_user.name_short, ''), v_user.name_full) || ' encerrou a visita:' || chr(10) ||
               'OS ' || COALESCE(v_order.order_mask, '') || ': ' || COALESCE(p_status_description, '') || chr(10) ||
               'Cliente: ' || COALESCE(v_client, 'N/A') || chr(10) ||
               'Unidade: ' || COALESCE(v_unit, 'N/A') || chr(10) ||
               'Setor/Posição: ' || COALESCE(v_tag, '') ||
                   CASE WHEN NULLIF(v_tag_sub, '') IS NOT NULL THEN '/' || v_tag_sub ELSE '' END || chr(10) ||
               'Servicos a realizar: ' || COALESCE(v_order.requested_services, ''),
               'Visita encerrada',
               v_now,
               false,
               fu.mobile_whatsapp
          FROM public.orders_followers f
          LEFT JOIN public.users fu ON fu.id = f.user_id
         WHERE f.o_id = v_order.parent_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'ended_at', v_end);
END;
$$;

--
-- Name: FUNCTION flow_order_visit_close_v3(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.flow_order_visit_close_v3(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text) IS 'Encerra a visita (visita, OS, SS pai, equipe e notificações) numa única transação. SECURITY INVOKER.';

--
-- Name: flow_order_visit_close_v4(bigint, bigint, integer, text, bigint, bigint, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_close_v4(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text DEFAULT NULL::text, p_client_ended_at text DEFAULT NULL::text, p_client_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_now        TIMESTAMP := timezone('America/Sao_Paulo', now());
    v_tolerance  INTERVAL  := interval '10 minutes';
    v_end        TIMESTAMP;
    v_client_end TIMESTAMP;
    v_user       RECORD;
    v_visit      RECORD;
    v_contract   BIGINT;
    v_manual_ok  BOOLEAN := false;
    v_order      RECORD;
    v_target     RECORD;
    v_team_ids   BIGINT[];
    v_client     TEXT;
    v_unit       TEXT;
    v_tag        TEXT;
    v_tag_sub    TEXT;
    v_done_end   TIMESTAMP;
BEGIN
    SELECT u.id, u.name_short, u.name_full INTO v_user
      FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user.id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    -- 0. Idempotência: a mesma operação da fila já foi aplicada?
    IF p_client_op_id IS NOT NULL THEN
        SELECT ov.ov_ended_at INTO v_done_end
          FROM public.orders_visits ov
         WHERE ov.ov_close_client_op_id = p_client_op_id;
        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'already_applied', true, 'ended_at', v_done_end);
        END IF;
    END IF;

    -- Trava a linha da visita: dois encerramentos simultâneos não se cruzam.
    SELECT ov.id, ov.ov_status_id, ov.ov_started_at INTO v_visit
      FROM public.orders_visits ov WHERE ov.id = p_visit_id
       FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Visita % não encontrada ou sem permissão.', p_visit_id USING ERRCODE = 'P0002';
    END IF;

    -- Conflito (só para a fila offline): já encerrada por outra pessoa/aparelho.
    IF p_client_op_id IS NOT NULL AND v_visit.ov_status_id = 2 THEN
        RAISE EXCEPTION 'A visita já foi encerrada por outro usuário enquanto você estava sem internet.'
            USING ERRCODE = 'SG409';
    END IF;

    -- 1. Veículos
    IF EXISTS (
        SELECT 1 FROM public.orders_visits_vehicles v
         WHERE v.ov_id = p_visit_id
           AND v.cost_type IS DISTINCT FROM 'idle'
           AND (v.recorder_start IS NULL OR v.recorder_end IS NULL
                OR v.recorder_start::numeric >= v.recorder_end::numeric)
    ) THEN
        RAISE EXCEPTION 'Existem veículos com apontamento inválido ou incompleto (Km Inicial >= Km Final).'
            USING ERRCODE = '22023';
    END IF;

    -- 2. Hora do encerramento
    v_end := v_now;

    --    2a. Hora do aparelho (fila offline)
    IF NULLIF(btrim(COALESCE(p_client_ended_at, '')), '') IS NOT NULL THEN
        v_client_end := replace(p_client_ended_at, 'T', ' ')::timestamp;
        IF v_client_end > v_now + v_tolerance THEN
            v_client_end := v_now;                       -- relógio adiantado
        END IF;
        IF v_visit.ov_started_at IS NOT NULL AND v_client_end < v_visit.ov_started_at THEN
            IF v_client_end < v_visit.ov_started_at - v_tolerance THEN
                RAISE EXCEPTION 'Data/hora de encerramento não pode ser anterior ao início da visita.'
                    USING ERRCODE = '22023';
            END IF;
            v_client_end := v_visit.ov_started_at;       -- diferença de relógio
        END IF;
        v_end := v_client_end;
    END IF;

    --    2b. Encerramento manual (mesma regra da v3) — tem prioridade
    IF NULLIF(btrim(COALESCE(p_ended_at, '')), '') IS NOT NULL THEN
        SELECT o.contract_id INTO v_contract FROM public.orders o WHERE o.id = p_order_id;
        IF v_contract IS NOT NULL THEN
            SELECT COALESCE((to_jsonb(c) ->> 'is_manual_visit_start_end')::boolean, false)
              INTO v_manual_ok
              FROM public.contracts c WHERE c.id = v_contract;
        END IF;
        IF COALESCE(v_manual_ok, false) THEN
            v_end := replace(p_ended_at, 'T', ' ')::timestamp;
            IF v_visit.ov_started_at IS NOT NULL AND v_end < v_visit.ov_started_at THEN
                RAISE EXCEPTION 'Data/hora de encerramento não pode ser anterior ao início da visita.'
                    USING ERRCODE = '22023';
            END IF;
        END IF;
    END IF;

    -- 3. Visita
    UPDATE public.orders_visits
       SET ov_ended_at    = v_end,
           ov_status_id   = 2,
           ov_o_status_id = p_status_id,
           ov_o_progress  = CASE WHEN p_status_id = 8 THEN 1 ELSE p_progress / 100 END,
           ov_o_suspended_reason_id = CASE
               WHEN p_status_id = 6 AND p_suspended_reason_id IS NOT NULL THEN p_suspended_reason_id
               ELSE ov_o_suspended_reason_id END,
           ov_close_client_op_id = COALESCE(p_client_op_id, ov_close_client_op_id),
           ov_close_received_at  = CASE WHEN p_client_op_id IS NOT NULL THEN v_now
                                        ELSE ov_close_received_at END
     WHERE id = p_visit_id;

    -- 4. OS
    UPDATE public.orders
       SET status_id = p_status_id,
           status_at = v_end,
           progress  = CASE WHEN p_status_id = 8 THEN 1 ELSE p_progress / 100 END,
           cause_reason_id = p_cause_reason_id
     WHERE id = p_order_id
    RETURNING parent_id, order_mask, requested_services, client_id, unit_id, asset_tag_id, asset_tag_sub_id
      INTO v_order;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'OS % não encontrada ou sem permissão para alterar.', p_order_id USING ERRCODE = 'P0002';
    END IF;

    -- 5. SS pai
    IF v_order.parent_id IS NOT NULL THEN
        SELECT o.status_id, o.status_at, o.cancel_reason_id, o.cancel_comments,
               o.canceled_user_id, o.canceled_team_id, o.canceled_at
          INTO v_target
          FROM public.orders o
          LEFT JOIN public.cfg_orders_statuses s ON s.id = o.status_id
         WHERE o.parent_id = v_order.parent_id
           AND o.is_deleted = false
         ORDER BY COALESCE(s.priority_level, 0) DESC, o.status_at DESC NULLS LAST
         LIMIT 1;

        IF FOUND THEN
            UPDATE public.orders
               SET status_id  = v_target.status_id,
                   status_at  = v_target.status_at,
                   updated_at = v_now,
                   cancel_reason_id = CASE WHEN v_target.status_id = 7 THEN v_target.cancel_reason_id ELSE cancel_reason_id END,
                   cancel_comments  = CASE WHEN v_target.status_id = 7 THEN v_target.cancel_comments  ELSE cancel_comments  END,
                   canceled_user_id = CASE WHEN v_target.status_id = 7 THEN v_target.canceled_user_id ELSE canceled_user_id END,
                   canceled_team_id = CASE WHEN v_target.status_id = 7 THEN v_target.canceled_team_id ELSE canceled_team_id END,
                   canceled_at      = CASE WHEN v_target.status_id = 7 THEN COALESCE(v_target.canceled_at, v_target.status_at) ELSE canceled_at END
             WHERE id = v_order.parent_id;
        END IF;
    END IF;

    -- 6. Equipe
    SELECT array_agg(DISTINCT t.user_id) INTO v_team_ids
      FROM public.orders_visits_teams t WHERE t.ov_id = p_visit_id;
    IF v_team_ids IS NULL THEN
        SELECT array_agg(u.id) INTO v_team_ids
          FROM public.users u WHERE u.ov_id_in_progress = p_visit_id;
    END IF;

    IF v_team_ids IS NOT NULL THEN
        UPDATE public.users
           SET is_available = true,
               ov_in_progress_leader_id = 0,
               o_contract_id_in_progress = 0,
               o_type_id_in_progress = 0,
               o_type_sub_id_in_progress = 0,
               o_plan_id_in_progress = 0,
               o_asset_tag_id_in_progress = 0,
               o_unit_id_in_progress = 0,
               o_system_id_in_progress = 0,
               o_system_parent_id_in_progress = 0,
               o_unit_type_id_in_progress = 0,
               o_unit_type_parent_id_in_progress = 0,
               o_object_id_in_progress = 0,
               ov_id_in_progress = 0,
               o_id_in_progress = 0,
               op_id_in_progress = 0,
               is_ov_in_progress = false,
               ov_id_in_progress_mask = NULL,
               updated_at = v_now
         WHERE id = ANY (v_team_ids);
    END IF;

    -- 7. Seguidores da SS pai
    IF v_order.parent_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.orders_followers f WHERE f.o_id = v_order.parent_id) THEN
        SELECT c.description INTO v_client FROM public.v_companies c WHERE c.id = v_order.client_id;
        SELECT u.description INTO v_unit   FROM public.units u WHERE u.id = v_order.unit_id;
        IF v_order.asset_tag_id IS NOT NULL THEN
            SELECT t.description INTO v_tag FROM public.cfg_assets_tags t WHERE t.id = v_order.asset_tag_id;
        END IF;
        IF v_order.asset_tag_sub_id IS NOT NULL THEN
            SELECT t.description INTO v_tag_sub FROM public.cfg_assets_tags_subs t WHERE t.id = v_order.asset_tag_sub_id;
        END IF;

        INSERT INTO public.users_notifications
               (user_id_to, user_id_from, title, body, type, created_at, is_read, user_to_whatsapp)
        SELECT f.user_id,
               v_user.id,
               'Visita encerrada.',
               COALESCE(NULLIF(v_user.name_short, ''), v_user.name_full) || ' encerrou a visita:' || chr(10) ||
               'OS ' || COALESCE(v_order.order_mask, '') || ': ' || COALESCE(p_status_description, '') || chr(10) ||
               'Cliente: ' || COALESCE(v_client, 'N/A') || chr(10) ||
               'Unidade: ' || COALESCE(v_unit, 'N/A') || chr(10) ||
               'Setor/Posição: ' || COALESCE(v_tag, '') ||
                   CASE WHEN NULLIF(v_tag_sub, '') IS NOT NULL THEN '/' || v_tag_sub ELSE '' END || chr(10) ||
               'Servicos a realizar: ' || COALESCE(v_order.requested_services, ''),
               'Visita encerrada',
               v_now,
               false,
               fu.mobile_whatsapp
          FROM public.orders_followers f
          LEFT JOIN public.users fu ON fu.id = f.user_id
         WHERE f.o_id = v_order.parent_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'already_applied', false,
        'ended_at', v_end,
        'offline', p_client_op_id IS NOT NULL
    );
END;
$$;

--
-- Name: FUNCTION flow_order_visit_close_v4(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text, p_client_ended_at text, p_client_op_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.flow_order_visit_close_v4(p_visit_id bigint, p_order_id bigint, p_status_id integer, p_status_description text, p_suspended_reason_id bigint, p_cause_reason_id bigint, p_progress numeric, p_ended_at text, p_client_ended_at text, p_client_op_id uuid) IS 'Encerra a visita numa única transação; aceita a hora do aparelho e é idempotente para a fila offline. SECURITY INVOKER.';

--
-- Name: flow_order_visit_create_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_create_v2(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_order_id bigint;
    v_user_id bigint;
    v_now timestamp;
    v_started_at timestamp;
    v_requested_start timestamp;
    v_allow_manual boolean := false;
    v_visit_id bigint;
    v_ov_mask text;
    v_new_ov_counter int;
    v_parent_id bigint;
    v_team_member record;
    v_follower record;
    v_order_info record;
    v_user_info record;
    v_order_mask text;
    v_team_id bigint;
    v_vehicle_id bigint;
    v_member_order int := 1;
BEGIN
    -- 1. Parse payload
    v_order_id := (payload->>'order_id')::bigint;
    v_user_id := (payload->>'user_id')::bigint;
    v_now := TIMEZONE('America/Sao_Paulo', CURRENT_TIMESTAMP);

    -- 1.1 A flag do contrato decide se o início informado é aceito.
    SELECT COALESCE(c.is_manual_visit_start_end, false)
      INTO v_allow_manual
      FROM orders o
      LEFT JOIN contracts c ON c.id = o.contract_id
     WHERE o.id = v_order_id;

    v_allow_manual := COALESCE(v_allow_manual, false);
    v_requested_start := NULLIF(payload->>'started_at', '')::timestamp;

    IF v_allow_manual AND v_requested_start IS NOT NULL THEN
        IF v_requested_start > v_now THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Data/hora de início não pode ser futura.'
            );
        END IF;
        v_started_at := v_requested_start;
    ELSE
        v_started_at := v_now;
    END IF;

    -- 2. Fetch User and Order Info
    SELECT team_id, vehicle_id INTO v_team_id, v_vehicle_id FROM users WHERE id = v_user_id;
    SELECT parent_id, order_mask, COALESCE(ov_counter, 0) INTO v_parent_id, v_order_mask, v_new_ov_counter FROM orders WHERE id = v_order_id;

    IF v_order_mask IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'OS não encontrada.');
    END IF;

    v_new_ov_counter := v_new_ov_counter + 1;
    v_ov_mask := v_order_mask || '.' || LPAD(v_new_ov_counter::text, 2, '0');

    -- 3. Execute Updates in Transaction
    -- A. Update Parent SS if exists
    IF v_parent_id IS NOT NULL THEN
        UPDATE orders
        SET
            status_id = 5, -- Em Andamento
            status_at = v_started_at,
            ov_counter = ov_counter + 1
        WHERE id = v_parent_id;
    END IF;

    -- B. Update Order (OS)
    UPDATE orders
    SET
        status_id = 5, -- Em Andamento
        status_at = v_started_at,
        ov_counter = v_new_ov_counter
    WHERE id = v_order_id;

    -- C. Insert orders_visits
    -- ov_started_at segue o horário informado; ov_created_at é auditoria (agora).
    INSERT INTO orders_visits (
        o_id,
        ov_status_id,
        ov_processing_id,
        ov_started_at,
        ov_team_leader_id,
        ov_created_user_id,
        ov_created_at,
        ov_mask
    ) VALUES (
        v_order_id,
        1, -- Em Andamento
        1, -- Rascunho
        v_started_at,
        v_user_id,
        v_user_id,
        v_now,
        v_ov_mask
    ) RETURNING id INTO v_visit_id;

    -- D. Handle Vehicle
    IF v_vehicle_id IS NOT NULL AND v_vehicle_id > 0 THEN
        INSERT INTO orders_visits_vehicles (
            ov_id,
            vehicle_id,
            created_user_id,
            created_at
        ) VALUES (
            v_visit_id,
            v_vehicle_id,
            v_user_id,
            v_now
        );
    END IF;

    -- E. Handle Team (Leader)
    INSERT INTO orders_visits_teams (
        ov_id,
        user_id,
        is_leader,
        order_id
    ) VALUES (
        v_visit_id,
        v_user_id,
        true,
        0
    );

    -- F. Update Leader Progress
    UPDATE users
    SET
        ov_id_in_progress = v_visit_id,
        is_available = false,
        is_ov_in_progress = true,
        o_id_in_progress = v_order_id,
        op_id_in_progress = v_parent_id,
        ov_id_in_progress_mask = v_ov_mask
    WHERE id = v_user_id;

    -- G. Handle Other Team Members
    FOR v_team_member IN
        SELECT id FROM users
        WHERE team_id = v_team_id
        AND is_available = true
        AND id != v_user_id
        ORDER BY name_short ASC
    LOOP
        INSERT INTO orders_visits_teams (
            ov_id,
            user_id,
            is_leader,
            order_id
        ) VALUES (
            v_visit_id,
            v_team_member.id,
            false,
            v_member_order
        );

        UPDATE users
        SET
            ov_id_in_progress = v_visit_id,
            is_available = false,
            is_ov_in_progress = true,
            o_id_in_progress = v_order_id,
            op_id_in_progress = v_parent_id,
            ov_id_in_progress_mask = v_ov_mask
        WHERE id = v_team_member.id;

        v_member_order := v_member_order + 1;
    END LOOP;

    -- 4. Send Notifications to Followers of Parent (SS)
    IF v_parent_id IS NOT NULL THEN
        SELECT * INTO v_order_info FROM v_orders WHERE id = v_order_id;
        SELECT name_short INTO v_user_info FROM users WHERE id = v_user_id;

        FOR v_follower IN
            SELECT f.user_id, u.mobile_whatsapp
            FROM orders_followers f
            JOIN users u ON u.id = f.user_id
            WHERE f.o_id = v_parent_id
        LOOP
            INSERT INTO users_notifications (
                user_id_to,
                user_id_from,
                title,
                body,
                type,
                user_to_whatsapp
            ) VALUES (
                v_follower.user_id,
                v_user_id,
                'OS em atendimento.',
                COALESCE(v_user_info.name_short, 'Técnico') || ' iniciou a visita:' || chr(10) ||
                'OS ' || COALESCE(v_order_info.order_mask, '') || ': ' || COALESCE(v_order_info.status_description, '') || chr(10) ||
                'Cliente: ' || COALESCE(v_order_info.client_name, '') || chr(10) ||
                'Unidade: ' || COALESCE(v_order_info.unit_description, '') || chr(10) ||
                'Setor/Posição: ' || COALESCE(v_order_info.asset_tag_description, '') || ' / ' || COALESCE(v_order_info.asset_tag_sub_description, '') || chr(10) ||
                'Serviços a realizar: ' || COALESCE(v_order_info.requested_services, ''),
                'OS em atendimento',
                v_follower.mobile_whatsapp
            );
        END LOOP;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Visita iniciada com sucesso.',
        'visit_id', v_visit_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'message', 'Erro ao iniciar visita: ' || SQLERRM
    );
END;
$$;

--
-- Name: flow_order_visit_create_v3(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_create_v3(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_order_id          bigint;
    v_user_id           bigint;
    v_auth_user_id      bigint;
    v_offline_uuid       uuid;
    v_vehicle_uuid      uuid;
    v_now               timestamp := timezone('America/Sao_Paulo', now());
    v_started_at        timestamp;
    v_requested_start   timestamp;
    v_client_started    timestamp;
    v_allow_manual      boolean := false;
    v_existing          record;
    v_order             record;
    v_visit_id          bigint;
    v_ov_mask           text;
    v_new_ov_counter    int;
    v_team_member       record;
    v_follower          record;
    v_order_info        record;
    v_user_info         record;
    v_team_id           bigint;
    v_vehicle_id        bigint;
    v_member_order      int := 1;
BEGIN
    -- 1. Payload
    v_order_id     := (payload->>'order_id')::bigint;
    v_user_id      := (payload->>'user_id')::bigint;
    -- offline_uuid (APK novo) ou client_uuid (APK anterior à 20261125).
    v_offline_uuid := COALESCE(NULLIF(payload->>'offline_uuid', ''), NULLIF(payload->>'client_uuid', ''))::uuid;
    v_vehicle_uuid := COALESCE(NULLIF(payload->>'vehicle_offline_uuid', ''), NULLIF(payload->>'vehicle_client_uuid', ''))::uuid;

    -- Quem chama precisa ser o líder informado.
    SELECT u.id INTO v_auth_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_auth_user_id IS NULL OR v_auth_user_id IS DISTINCT FROM v_user_id THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    -- 0. Idempotência: a mesma operação da fila já criou a visita?
    IF v_offline_uuid IS NOT NULL THEN
        SELECT ov.id, ov.ov_mask, ov.ov_started_at INTO v_existing
          FROM public.orders_visits ov WHERE ov.offline_uuid = v_offline_uuid;
        IF FOUND THEN
            RETURN jsonb_build_object(
                'success', true, 'already_applied', true, 'message', 'Visita iniciada com sucesso.',
                'visit_id', v_existing.id, 'ov_mask', v_existing.ov_mask, 'started_at', v_existing.ov_started_at
            );
        END IF;
    END IF;

    -- 2. OS (linha travada: contador de visitas sem corrida)
    SELECT o.id, o.parent_id, o.order_mask, COALESCE(o.ov_counter, 0) AS ov_counter,
           o.status_id, o.team_leader_id, COALESCE(o.is_deleted, false) AS is_deleted, o.contract_id
      INTO v_order
      FROM public.orders o
     WHERE o.id = v_order_id
       FOR UPDATE;
    IF NOT FOUND OR v_order.order_mask IS NULL THEN
        RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE = 'P0002';
    END IF;

    -- Conflito (só para a fila offline): a OS mudou enquanto o técnico estava sem internet.
    IF v_offline_uuid IS NOT NULL THEN
        IF v_order.is_deleted OR v_order.status_id IN (7, 8) THEN
            RAISE EXCEPTION 'A OS foi concluída ou cancelada enquanto você estava sem internet.'
                USING ERRCODE = 'SG409';
        END IF;
        IF v_order.team_leader_id IS NOT NULL AND v_order.team_leader_id <> v_user_id THEN
            RAISE EXCEPTION 'A OS passou para outro líder enquanto você estava sem internet.'
                USING ERRCODE = 'SG409';
        END IF;
    END IF;

    -- 3. Hora de início
    SELECT COALESCE(c.is_manual_visit_start_end, false) INTO v_allow_manual
      FROM public.contracts c WHERE c.id = v_order.contract_id;
    v_allow_manual := COALESCE(v_allow_manual, false);

    v_requested_start := NULLIF(payload->>'started_at', '')::timestamp;
    v_client_started  := NULLIF(replace(COALESCE(payload->>'client_started_at', ''), 'T', ' '), '')::timestamp;

    IF v_allow_manual AND v_requested_start IS NOT NULL THEN
        IF v_requested_start > v_now THEN
            RAISE EXCEPTION 'Data/hora de início não pode ser futura.' USING ERRCODE = '22023';
        END IF;
        v_started_at := v_requested_start;
    ELSIF v_client_started IS NOT NULL THEN
        v_started_at := LEAST(v_client_started, v_now);   -- relógio adiantado → agora
    ELSE
        v_started_at := v_now;
    END IF;

    -- 4. Usuário
    SELECT u.team_id, u.vehicle_id INTO v_team_id, v_vehicle_id FROM public.users u WHERE u.id = v_user_id;

    v_new_ov_counter := v_order.ov_counter + 1;
    v_ov_mask := v_order.order_mask || '.' || LPAD(v_new_ov_counter::text, 2, '0');

    -- A. SS pai
    IF v_order.parent_id IS NOT NULL THEN
        UPDATE public.orders
           SET status_id  = 5, -- Em Andamento
               status_at  = v_started_at,
               ov_counter = ov_counter + 1
         WHERE id = v_order.parent_id;
    END IF;

    -- B. OS
    UPDATE public.orders
       SET status_id  = 5,
           status_at  = v_started_at,
           ov_counter = v_new_ov_counter
     WHERE id = v_order_id;

    -- C. Visita
    INSERT INTO public.orders_visits (
        o_id, ov_status_id, ov_processing_id, ov_started_at,
        ov_team_leader_id, ov_created_user_id, ov_created_at, ov_mask, offline_uuid
    ) VALUES (
        v_order_id, 1, 1, v_started_at,
        v_user_id, v_user_id, v_now, v_ov_mask, v_offline_uuid
    ) RETURNING id INTO v_visit_id;

    -- D. Veículo do líder
    IF v_vehicle_id IS NOT NULL AND v_vehicle_id > 0 THEN
        INSERT INTO public.orders_visits_vehicles (ov_id, vehicle_id, created_user_id, created_at, offline_uuid)
        VALUES (v_visit_id, v_vehicle_id, v_user_id, v_now, v_vehicle_uuid);
    END IF;

    -- E. Equipe: líder
    INSERT INTO public.orders_visits_teams (ov_id, user_id, is_leader, order_id)
    VALUES (v_visit_id, v_user_id, true, 0);

    -- F. Líder em visita
    UPDATE public.users
       SET ov_id_in_progress = v_visit_id,
           is_available = false,
           is_ov_in_progress = true,
           o_id_in_progress = v_order_id,
           op_id_in_progress = v_order.parent_id,
           ov_id_in_progress_mask = v_ov_mask
     WHERE id = v_user_id;

    -- G. Demais membros disponíveis da equipe (no momento do envio)
    FOR v_team_member IN
        SELECT u.id FROM public.users u
         WHERE u.team_id = v_team_id
           AND u.is_available = true
           AND u.id <> v_user_id
         ORDER BY u.name_short ASC
    LOOP
        INSERT INTO public.orders_visits_teams (ov_id, user_id, is_leader, order_id)
        VALUES (v_visit_id, v_team_member.id, false, v_member_order);

        UPDATE public.users
           SET ov_id_in_progress = v_visit_id,
               is_available = false,
               is_ov_in_progress = true,
               o_id_in_progress = v_order_id,
               op_id_in_progress = v_order.parent_id,
               ov_id_in_progress_mask = v_ov_mask
         WHERE id = v_team_member.id;

        v_member_order := v_member_order + 1;
    END LOOP;

    -- 5. Seguidores da SS
    IF v_order.parent_id IS NOT NULL THEN
        SELECT * INTO v_order_info FROM public.v_orders WHERE id = v_order_id;
        SELECT name_short INTO v_user_info FROM public.users WHERE id = v_user_id;

        FOR v_follower IN
            SELECT f.user_id, u.mobile_whatsapp
              FROM public.orders_followers f
              JOIN public.users u ON u.id = f.user_id
             WHERE f.o_id = v_order.parent_id
        LOOP
            INSERT INTO public.users_notifications (
                user_id_to, user_id_from, title, body, type, user_to_whatsapp
            ) VALUES (
                v_follower.user_id,
                v_user_id,
                'OS em atendimento.',
                COALESCE(v_user_info.name_short, 'Técnico') || ' iniciou a visita:' || chr(10) ||
                'OS ' || COALESCE(v_order_info.order_mask, '') || ': ' || COALESCE(v_order_info.status_description, '') || chr(10) ||
                'Cliente: ' || COALESCE(v_order_info.client_name, '') || chr(10) ||
                'Unidade: ' || COALESCE(v_order_info.unit_description, '') || chr(10) ||
                'Setor/Posição: ' || COALESCE(v_order_info.asset_tag_description, '') || ' / ' || COALESCE(v_order_info.asset_tag_sub_description, '') || chr(10) ||
                'Serviços a realizar: ' || COALESCE(v_order_info.requested_services, ''),
                'OS em atendimento',
                v_follower.mobile_whatsapp
            );
        END LOOP;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'already_applied', false,
        'message', 'Visita iniciada com sucesso.',
        'visit_id', v_visit_id,
        'ov_mask', v_ov_mask,
        'started_at', v_started_at,
        'offline', v_offline_uuid IS NOT NULL
    );
END;
$$;

--
-- Name: FUNCTION flow_order_visit_create_v3(payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.flow_order_visit_create_v3(payload jsonb) IS 'Inicia a visita (OS/SS, visita, veículo, equipe, notificações) numa transação; idempotente por offline_uuid para a fila offline. SECURITY DEFINER.';

--
-- Name: flow_order_visit_reassign_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flow_order_visit_reassign_v1(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_visit_id        bigint;
    v_user_id         bigint;
    v_target_order_id bigint;
    v_now             timestamp;
    v_auth_user_id    bigint;
    v_visit           record;
    v_os1             record;
    v_os2             record;
    v_pre             record;
    v_anchor_id       bigint;
    v_new_counter     int;
    v_new_mask        text;
    v_restored_id     bigint;
    v_restored_at     timestamp;
    v_remaining_max   int;
    v_os1_counter     int;
BEGIN
    -- 1. Payload
    v_visit_id        := (payload->>'visit_id')::bigint;
    v_user_id         := (payload->>'user_id')::bigint;
    v_target_order_id := (payload->>'target_order_id')::bigint;
    v_now             := TIMEZONE('America/Sao_Paulo', CURRENT_TIMESTAMP);

    IF v_visit_id IS NULL OR v_user_id IS NULL OR v_target_order_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'message', 'Parâmetros inválidos: informe visit_id, user_id e target_order_id.');
    END IF;

    -- 2. Guard 1 — visita válida e aberta (trava a linha)
    SELECT * INTO v_visit
    FROM public.orders_visits
    WHERE id = v_visit_id
      AND is_deleted = false
      AND is_canceled = false
      AND ov_status_id = 1
      AND ov_ended_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false,
            'message', 'Visita inválida ou já finalizada.');
    END IF;

    -- 3. Guard 2a — identidade (quando há JWT, impede passar outro user_id)
    IF auth.uid() IS NOT NULL THEN
        SELECT id INTO v_auth_user_id FROM public.users WHERE uuid = auth.uid();
        IF v_auth_user_id IS NOT NULL AND v_auth_user_id <> v_user_id THEN
            RETURN jsonb_build_object('success', false,
                'message', 'Usuário inválido para esta operação.');
        END IF;
    END IF;

    -- Guard 2b — apenas o líder da visita
    IF v_visit.ov_team_leader_id IS DISTINCT FROM v_user_id THEN
        RETURN jsonb_build_object('success', false,
            'message', 'Apenas o líder da visita pode transferi-la.');
    END IF;

    -- 4. Guard 3 — sem ativos registrados na visita
    IF EXISTS (
        SELECT 1 FROM public.orders_visits_assets
        WHERE ov_id = v_visit.id AND is_deleted = false
    ) THEN
        RETURN jsonb_build_object('success', false,
            'message', 'A visita possui ativos registrados e não pode ser transferida.');
    END IF;

    -- 5. Guard 4 — sem serviços registrados na visita
    IF EXISTS (
        SELECT 1 FROM public.orders_visits_services
        WHERE ov_id = v_visit.id AND is_deleted = false
    ) THEN
        RETURN jsonb_build_object('success', false,
            'message', 'A visita possui serviços registrados e não pode ser transferida.');
    END IF;

    -- 6. Guard 5 — OS de destino válida (trava a linha)
    SELECT * INTO v_os2
    FROM public.orders
    WHERE id = v_target_order_id
    FOR UPDATE;

    IF NOT FOUND OR v_os2.is_deleted = true THEN
        RETURN jsonb_build_object('success', false,
            'message', 'OS de destino não encontrada.');
    END IF;

    IF COALESCE(v_os2.parent_id, 0) = 0 THEN
        RETURN jsonb_build_object('success', false,
            'message', 'A OS de destino deve ser uma Ordem de Serviço.');
    END IF;

    -- Guard 6 — destino diferente da origem
    IF v_os2.id = v_visit.o_id THEN
        RETURN jsonb_build_object('success', false,
            'message', 'A OS de destino não pode ser a OS da visita em andamento.');
    END IF;

    IF v_os2.status_id NOT IN (3, 4, 6) THEN   -- Autorizada / Agendada / Suspensa (D11)
        RETURN jsonb_build_object('success', false,
            'message', 'A OS de destino deve estar Autorizada, Agendada ou Suspensa.');
    END IF;

    -- 7. Guard 7 — destino sem outra visita aberta
    IF EXISTS (
        SELECT 1 FROM public.orders_visits
        WHERE o_id = v_os2.id
          AND id <> v_visit.id
          AND is_deleted = false
          AND is_canceled = false
          AND ov_status_id = 1
          AND ov_ended_at IS NULL
    ) THEN
        RETURN jsonb_build_object('success', false,
            'message', 'A OS de destino já possui uma visita em andamento.');
    END IF;

    -- 8. OS de origem (trava a linha)
    SELECT * INTO v_os1
    FROM public.orders
    WHERE id = v_visit.o_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false,
            'message', 'OS de origem não encontrada.');
    END IF;

    -- 9. Guard 8 — situação anterior à visita (semântica NEW → ancora na última
    --    linha de status 5 e pega a imediatamente anterior por ordem de inserção;
    --    usa id, nunca order_status_at — scheduleOrder grava data futura / R4)
    SELECT max(l.id) INTO v_anchor_id
    FROM public.orders_statuses_logs l
    WHERE l.order_id = v_os1.id
      AND l.order_status_id = 5;

    IF v_anchor_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'message', 'Sem histórico de situação anterior à visita. Operação indisponível para visitas iniciadas antes da ativação do log.');
    END IF;

    SELECT l.order_status_id, l.order_status_at
    INTO v_pre
    FROM public.orders_statuses_logs l
    WHERE l.order_id = v_os1.id
      AND l.id < v_anchor_id
    ORDER BY l.id DESC
    LIMIT 1;

    IF NOT FOUND OR v_pre.order_status_id IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'message', 'Sem histórico de situação anterior à visita. Operação indisponível para visitas iniciadas antes da ativação do log.');
    END IF;

    v_restored_id := v_pre.order_status_id;
    v_restored_at := v_pre.order_status_at;

    -- 10. Máscara nova da visita na OS de destino
    v_new_counter := COALESCE(v_os2.ov_counter, 0) + 1;
    v_new_mask     := v_os2.order_mask || '.' || LPAD(v_new_counter::text, 2, '0');

    -- 11. Efeito 1 — visita passa a pertencer à OS2
    UPDATE public.orders_visits
    SET o_id = v_os2.id,
        ov_mask = v_new_mask,
        ov_updated_user_id = v_user_id,
        ov_updated_at = v_now
    WHERE id = v_visit.id;

    -- 12. Efeito 2 — OS2 entra em execução (trigger grava a situação 5 no log)
    UPDATE public.orders
    SET status_id = 5,
        status_at = v_now,
        ov_counter = v_new_counter,
        updated_user_id = v_user_id,
        updated_at = v_now
    WHERE id = v_os2.id;

    -- 13. Efeito 4 — ov_counter da OS1: decrementa somente se nenhuma visita
    --     restante usa o sufixo corrente; senão mantém o MAX dos restantes (D8)
    SELECT COALESCE(max(substring(v2.ov_mask from '([0-9]+)$')::int), -1)
    INTO v_remaining_max
    FROM public.orders_visits v2
    WHERE v2.o_id = v_os1.id
      AND v2.id <> v_visit.id
      AND v2.is_deleted = false;

    IF EXISTS (
        SELECT 1 FROM public.orders_visits v3
        WHERE v3.o_id = v_os1.id
          AND v3.id <> v_visit.id
          AND v3.is_deleted = false
          AND substring(v3.ov_mask from '([0-9]+)$')::int = COALESCE(v_os1.ov_counter, 0)
    ) THEN
        v_os1_counter := GREATEST(v_remaining_max, COALESCE(v_os1.ov_counter, 0));
    ELSE
        v_os1_counter := GREATEST(COALESCE(v_os1.ov_counter, 0) - 1, 0);
    END IF;

    -- 14. Efeito 3 — OS1 restaurada à situação anterior (trigger grava no log)
    UPDATE public.orders
    SET status_id = v_restored_id,
        status_at = v_restored_at,
        ov_counter = v_os1_counter,
        updated_user_id = v_user_id,
        updated_at = v_now
    WHERE id = v_os1.id;

    -- 15. Efeito 5 — equipe acompanha a nova OS/máscara
    UPDATE public.users
    SET o_id_in_progress = v_os2.id,
        op_id_in_progress = v_os2.parent_id,
        ov_id_in_progress_mask = v_new_mask
    WHERE id IN (
        SELECT t.user_id FROM public.orders_visits_teams t WHERE t.ov_id = v_visit.id
    );

    -- 16. Efeito 6 — notificações aos seguidores das duas OS: automáticas via
    --     trg_followers_orders_status_changed (AFTER UPDATE OF status_id)
    -- 17. Efeito 7 — SS pai: automático via trg_order_status_inheritance
    --     (AFTER UPDATE OF status_id, status_at em cada OS atualizada)

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Visita transferida para ' || v_new_mask || '.',
        'visit_id', v_visit.id,
        'new_mask', v_new_mask,
        'source_order_id', v_os1.id,
        'restored_status_id', v_restored_id,
        'restored_status_at', v_restored_at
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false,
        'message', 'Erro ao transferir visita: ' || SQLERRM);
END;
$_$;

--
-- Name: FUNCTION flow_order_visit_reassign_v1(payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.flow_order_visit_reassign_v1(payload jsonb) IS 'Flow: reassign-order-visit v1.0.0 — transplanta a visita em andamento da OS de origem para a OS de destino e restaura a situação anterior da origem via orders_statuses_logs (semântica NEW, ancorada por id).';

--
-- Name: fn_add_assets_available(bigint, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_add_assets_available(p_integration_id bigint, p_items jsonb, p_contract_version integer DEFAULT 1) RETURNS TABLE(external_id text, result text, message text, asset_available_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_integration public.cfg_assets_available_integrations%ROWTYPE;
    v_mapping public.cfg_assets_available_integrations_mappings%ROWTYPE;
    v_node public.cfg_units_assets_tags%ROWTYPE;
    v_item JSONB;
    v_external_id TEXT;
    v_status TEXT;
    v_is_available BOOLEAN;
    v_source_text TEXT;
    v_source_tz TIMESTAMPTZ;
    v_source_at TIMESTAMP WITHOUT TIME ZONE;
    v_event_id TEXT;
    v_reason TEXT;
    v_reason_id INTEGER;
    v_unit_company_id BIGINT;
    v_duplicate_event BOOLEAN;
    v_new_asset_available_id INTEGER;
    v_processed_at_text TEXT;
    v_error TEXT;
    v_outcome TEXT;
    v_count INTEGER;
BEGIN
    IF p_contract_version IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'Versão de contrato não suportada: %', p_contract_version
            USING ERRCODE = '22023';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'p_items deve ser um array JSON'
            USING ERRCODE = '22023';
    END IF;

    v_count := jsonb_array_length(p_items);
    IF v_count = 0 OR v_count > 500 THEN
        RAISE EXCEPTION 'O lote deve conter entre 1 e 500 itens'
            USING ERRCODE = '22023';
    END IF;

    SELECT i.* INTO v_integration
    FROM public.cfg_assets_available_integrations i
    WHERE i.id = p_integration_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Integração % não encontrada', p_integration_id
            USING ERRCODE = 'P0002';
    END IF;

    IF v_integration.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'Integração % está inativa', p_integration_id
            USING ERRCODE = '55000';
    END IF;

    -- Serializa lotes da mesma integração: a checagem de idempotência e a
    -- aplicação do evento passam a ser atômicas também sob concorrência.
    PERFORM pg_advisory_xact_lock(
        hashtextextended('assets_available_integration:' || p_integration_id::TEXT, 0)
    );

    v_processed_at_text := to_char(
        timezone('America/Sao_Paulo', now()),
        'YYYY-MM-DD HH24:MI:SS'
    );

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS items(value)
    LOOP
        external_id := NULL;
        result := NULL;
        message := NULL;
        asset_available_id := NULL;

        v_external_id := NULL;
        v_status := NULL;
        v_is_available := NULL;
        v_source_text := NULL;
        v_source_tz := NULL;
        v_source_at := NULL;
        v_event_id := NULL;
        v_reason := NULL;
        v_reason_id := NULL;
        v_unit_company_id := NULL;
        v_duplicate_event := FALSE;
        v_new_asset_available_id := NULL;
        v_mapping := NULL;
        v_node := NULL;

        BEGIN
            -- ── Validação do contrato ───────────────────────────────────
            IF v_item IS NULL OR jsonb_typeof(v_item) IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'Cada item deve ser um objeto JSON'
                    USING ERRCODE = '22023';
            END IF;

            IF jsonb_typeof(v_item -> 'external_id') IS NULL
               OR jsonb_typeof(v_item -> 'external_id') NOT IN ('string', 'number') THEN
                RAISE EXCEPTION 'external_id é obrigatório e deve ser texto ou número'
                    USING ERRCODE = '22023';
            END IF;

            v_external_id := v_item ->> 'external_id';
            IF btrim(v_external_id) = '' OR length(v_external_id) > 200 THEN
                RAISE EXCEPTION 'external_id deve ter entre 1 e 200 caracteres'
                    USING ERRCODE = '22023';
            END IF;

            IF jsonb_typeof(v_item -> 'status') IS DISTINCT FROM 'string' THEN
                RAISE EXCEPTION 'status é obrigatório e deve ser texto'
                    USING ERRCODE = '22023';
            END IF;

            v_status := btrim(v_item ->> 'status');
            IF v_status IN ('available', 'unavailable') THEN
                v_is_available := (v_status = 'available');
            ELSIF v_integration.config ? 'status_map' THEN
                IF jsonb_typeof(v_integration.config -> 'status_map' -> v_status)
                   IS DISTINCT FROM 'boolean' THEN
                    RAISE EXCEPTION 'Status externo não mapeado para esta integração: %',
                        left(v_status, 80)
                        USING ERRCODE = '22023';
                END IF;
                v_is_available := (v_integration.config -> 'status_map' ->> v_status)::BOOLEAN;
            ELSE
                RAISE EXCEPTION 'status deve ser available ou unavailable'
                    USING ERRCODE = '22023';
            END IF;

            IF jsonb_typeof(v_item -> 'source_reported_at') IS DISTINCT FROM 'string' THEN
                RAISE EXCEPTION 'source_reported_at é obrigatório e deve ser texto ISO 8601'
                    USING ERRCODE = '22023';
            END IF;

            v_source_text := btrim(v_item ->> 'source_reported_at');
            IF v_source_text !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
                RAISE EXCEPTION 'source_reported_at deve informar offset explícito (ex.: -03:00 ou Z)'
                    USING ERRCODE = '22023';
            END IF;

            BEGIN
                v_source_tz := v_source_text::TIMESTAMPTZ;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'source_reported_at inválido: %', left(v_source_text, 80)
                    USING ERRCODE = '22023';
            END;

            v_source_at := v_source_tz AT TIME ZONE 'America/Sao_Paulo';

            IF jsonb_typeof(v_item -> 'source_event_id') IS NOT NULL
               AND jsonb_typeof(v_item -> 'source_event_id') <> 'null' THEN
                IF jsonb_typeof(v_item -> 'source_event_id') NOT IN ('string', 'number') THEN
                    RAISE EXCEPTION 'source_event_id deve ser texto ou número'
                        USING ERRCODE = '22023';
                END IF;
                v_event_id := v_item ->> 'source_event_id';
                IF btrim(v_event_id) = '' OR length(v_event_id) > 200 THEN
                    RAISE EXCEPTION 'source_event_id deve ter entre 1 e 200 caracteres'
                        USING ERRCODE = '22023';
                END IF;
            END IF;

            IF jsonb_typeof(v_item -> 'reason') IS NOT NULL
               AND jsonb_typeof(v_item -> 'reason') <> 'null' THEN
                IF jsonb_typeof(v_item -> 'reason') <> 'string' THEN
                    RAISE EXCEPTION 'reason deve ser texto'
                        USING ERRCODE = '22023';
                END IF;
                v_reason := NULLIF(btrim(v_item ->> 'reason'), '');
            END IF;

            -- ── Idempotência por evento externo ────────────────────────
            IF v_event_id IS NOT NULL THEN
                SELECT EXISTS (
                    SELECT 1
                    FROM public.logs_assets_available_integrations_events l
                    WHERE l.integration_id = v_integration.id
                      AND l.source_event_id = v_event_id
                      AND l.result = 'applied'
                ) INTO v_duplicate_event;

                IF v_duplicate_event THEN
                    PERFORM public.fn_log_assets_available_integration_event(
                        p_integration_id => v_integration.id,
                        p_mapping_id => NULL,
                        p_unit_asset_tag_id => NULL,
                        p_external_id => v_external_id,
                        p_source_event_id => v_event_id,
                        p_source_reported_at => v_source_at,
                        p_is_available => v_is_available,
                        p_result => 'duplicate',
                        p_message => 'Evento externo já aplicado',
                        p_asset_available_id => NULL
                    );
                    external_id := v_external_id;
                    result := 'duplicate';
                    message := 'Evento externo já aplicado';
                    RETURN NEXT;
                    CONTINUE;
                END IF;
            END IF;

            -- ── Mapeamento ─────────────────────────────────────────────
            SELECT m.* INTO v_mapping
            FROM public.cfg_assets_available_integrations_mappings m
            WHERE m.integration_id = v_integration.id
              AND m.external_id = v_external_id;

            IF NOT FOUND THEN
                PERFORM public.fn_log_assets_available_integration_event(
                    p_integration_id => v_integration.id,
                    p_mapping_id => NULL,
                    p_unit_asset_tag_id => NULL,
                    p_external_id => v_external_id,
                    p_source_event_id => v_event_id,
                    p_source_reported_at => v_source_at,
                    p_is_available => v_is_available,
                    p_result => 'pending_mapping',
                    p_message => 'ID externo sem mapeamento',
                    p_asset_available_id => NULL
                );
                external_id := v_external_id;
                result := 'pending_mapping';
                message := 'ID externo sem mapeamento';
                RETURN NEXT;
                CONTINUE;
            END IF;

            IF v_mapping.is_active IS NOT TRUE THEN
                PERFORM public.fn_log_assets_available_integration_event(
                    p_integration_id => v_integration.id,
                    p_mapping_id => v_mapping.id,
                    p_unit_asset_tag_id => v_mapping.unit_asset_tag_id,
                    p_external_id => v_external_id,
                    p_source_event_id => v_event_id,
                    p_source_reported_at => v_source_at,
                    p_is_available => v_is_available,
                    p_result => 'pending_mapping',
                    p_message => 'Mapeamento inativo',
                    p_asset_available_id => NULL
                );
                external_id := v_external_id;
                result := 'pending_mapping';
                message := 'Mapeamento inativo';
                RETURN NEXT;
                CONTINUE;
            END IF;

            SELECT t.* INTO v_node
            FROM public.cfg_units_assets_tags t
            WHERE t.id = v_mapping.unit_asset_tag_id;

            IF NOT FOUND OR v_node.is_deleted IS TRUE OR v_node.is_active IS NOT TRUE THEN
                RAISE EXCEPTION 'Ativo mapeado não existe ou está inativo'
                    USING ERRCODE = '22023';
            END IF;

            -- Escopo de empresa: o alvo precisa pertencer à empresa da integração.
            SELECT u.company_id INTO v_unit_company_id
            FROM public.units u
            WHERE u.id = v_node.unit_id;

            IF v_unit_company_id IS NULL
               OR v_unit_company_id IS DISTINCT FROM v_integration.company_id THEN
                RAISE EXCEPTION 'Unidade do ativo fora do escopo da empresa da integração'
                    USING ERRCODE = '22023';
            END IF;

            -- ── Motivo externo → motivo interno (somente mapa explícito) ─
            IF v_reason IS NOT NULL AND v_integration.config ? 'reason_map' THEN
                IF jsonb_typeof(v_integration.config -> 'reason_map' -> v_reason)
                   IS DISTINCT FROM 'number' THEN
                    RAISE EXCEPTION 'Motivo externo não mapeado: %', left(v_reason, 80)
                        USING ERRCODE = '22023';
                END IF;

                v_reason_id := (v_integration.config -> 'reason_map' ->> v_reason)::INTEGER;

                IF NOT EXISTS (
                    SELECT 1
                    FROM public.cfg_assets_unavailable_reasons r
                    WHERE r.id = v_reason_id
                      AND r.is_available IS TRUE
                      AND r.is_deleted IS NOT TRUE
                ) THEN
                    RAISE EXCEPTION 'Motivo interno % inexistente ou inativo', v_reason_id
                        USING ERRCODE = '22023';
                END IF;
            END IF;

            IF v_integration.config ->> 'require_reason' = 'true'
               AND v_is_available IS FALSE
               AND v_reason IS NULL THEN
                RAISE EXCEPTION 'Motivo é obrigatório para indisponibilidade nesta integração'
                    USING ERRCODE = '22023';
            END IF;

            -- ── Ordem das leituras ────────────────────────────────────
            -- Mesma leitura já processada: a fonte ainda não gerou leitura nova
            -- (ex.: GuaibaFlow lê a cada ~15 min). Não é erro → 'unchanged'.
            -- config.record_every_reading = true: grava toda leitura em
            -- assets_available, mesmo repetida ou sem mudança de estado.
            IF (v_integration.config ->> 'record_every_reading') IS DISTINCT FROM 'true'
               AND v_mapping.last_source_reported_at IS NOT NULL
               AND v_source_at = v_mapping.last_source_reported_at THEN
                PERFORM public.fn_log_assets_available_integration_event(
                    p_integration_id => v_integration.id,
                    p_mapping_id => v_mapping.id,
                    p_unit_asset_tag_id => v_mapping.unit_asset_tag_id,
                    p_external_id => v_external_id,
                    p_source_event_id => v_event_id,
                    p_source_reported_at => v_source_at,
                    p_is_available => v_is_available,
                    p_result => 'unchanged',
                    p_message => 'Leitura já processada (sem leitura nova na fonte)',
                    p_asset_available_id => NULL
                );
                external_id := v_external_id;
                result := 'unchanged';
                message := 'Leitura já processada (sem leitura nova na fonte)';
                RETURN NEXT;
                CONTINUE;
            END IF;

            IF v_mapping.last_source_reported_at IS NOT NULL
               AND v_source_at < v_mapping.last_source_reported_at THEN
                RAISE EXCEPTION 'Leitura mais antiga que a última aplicada para este mapeamento'
                    USING ERRCODE = '22023';
            END IF;

            IF v_node.last_reported_at IS NOT NULL
               AND v_node.last_reported_at > v_source_at THEN
                RAISE EXCEPTION 'Leitura mais antiga que o estado atual do ativo'
                    USING ERRCODE = '22023';
            END IF;

            -- ── Sem mudança relevante: não cria histórico ──────────────
            -- (ignorado quando config.record_every_reading = true)
            IF (v_integration.config ->> 'record_every_reading') IS DISTINCT FROM 'true'
               AND v_node.last_is_available IS NOT DISTINCT FROM v_is_available
               AND (
                   v_is_available IS TRUE
                   OR COALESCE(v_node.last_asset_unavailable_reason_id, 0)
                      = COALESCE(v_reason_id, 0)
               ) THEN
                UPDATE public.cfg_assets_available_integrations_mappings m
                SET last_source_reported_at = v_source_at,
                    last_is_available = v_is_available,
                    updated_at = timezone('America/Sao_Paulo', now())
                WHERE m.id = v_mapping.id;

                PERFORM public.fn_log_assets_available_integration_event(
                    p_integration_id => v_integration.id,
                    p_mapping_id => v_mapping.id,
                    p_unit_asset_tag_id => v_mapping.unit_asset_tag_id,
                    p_external_id => v_external_id,
                    p_source_event_id => v_event_id,
                    p_source_reported_at => v_source_at,
                    p_is_available => v_is_available,
                    p_result => 'unchanged',
                    p_message => 'Estado sem mudança relevante',
                    p_asset_available_id => NULL
                );

                external_id := v_external_id;
                result := 'unchanged';
                message := 'Estado sem mudança relevante';
                RETURN NEXT;
                CONTINUE;
            END IF;

            -- ── Aplicação pelo fluxo oficial (histórico + estado + cascata) ─
            v_new_asset_available_id := public.report_unit_asset_tag_availability(
                p_unit_asset_tag_id => v_node.id::INTEGER,
                p_is_available => v_is_available,
                p_reason_id => v_reason_id,
                p_comments => 'Leitura obtida via integração de APIs.',
                p_reported_by_id => NULL,
                p_file_path => NULL,
                p_file_name => NULL,
                p_unit_id => v_node.unit_id::INTEGER,
                p_asset_tag_id => v_node.asset_tag_id::INTEGER,
                p_asset_tag_sub_id => v_node.asset_tag_sub_id::INTEGER,
                p_operation_record => NULL,
                p_created_at => v_processed_at_text,
                p_reported_at => to_char(v_source_at, 'YYYY-MM-DD HH24:MI:SS'),
                p_reported_latitude => NULL,
                p_reported_longitude => NULL,
                p_unit_latitude => NULL,
                p_unit_longitude => NULL,
                p_unit_reported_distance => NULL,
                p_provider_company_id => v_integration.provider_company_id::INTEGER,
                p_is_web => FALSE
            );

            UPDATE public.cfg_assets_available_integrations_mappings m
            SET last_source_reported_at = v_source_at,
                last_is_available = v_is_available,
                updated_at = timezone('America/Sao_Paulo', now())
            WHERE m.id = v_mapping.id;

            PERFORM public.fn_log_assets_available_integration_event(
                p_integration_id => v_integration.id,
                p_mapping_id => v_mapping.id,
                p_unit_asset_tag_id => v_mapping.unit_asset_tag_id,
                p_external_id => v_external_id,
                p_source_event_id => v_event_id,
                p_source_reported_at => v_source_at,
                p_is_available => v_is_available,
                p_result => 'applied',
                p_message => NULL,
                p_asset_available_id => v_new_asset_available_id
            );

            external_id := v_external_id;
            result := 'applied';
            message := NULL;
            asset_available_id := v_new_asset_available_id;
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            -- Cada item é atômico: falha aqui desfaz só as alterações do item.
            v_error := left(
                regexp_replace(SQLERRM, '[[:cntrl:]]+', ' ', 'g'),
                500
            );
            v_outcome := CASE WHEN SQLSTATE = '22023' THEN 'rejected' ELSE 'error' END;

            PERFORM public.fn_log_assets_available_integration_event(
                p_integration_id => v_integration.id,
                p_mapping_id => v_mapping.id,
                p_unit_asset_tag_id => v_mapping.unit_asset_tag_id,
                p_external_id => v_external_id,
                p_source_event_id => v_event_id,
                p_source_reported_at => v_source_at,
                p_is_available => v_is_available,
                p_result => v_outcome,
                p_message => v_error,
                p_asset_available_id => NULL
            );

            external_id := v_external_id;
            result := v_outcome;
            message := v_error;
            asset_available_id := NULL;
            RETURN NEXT;
        END;
    END LOOP;

    RETURN;
END;
$_$;

--
-- Name: FUNCTION fn_add_assets_available(p_integration_id bigint, p_items jsonb, p_contract_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_add_assets_available(p_integration_id bigint, p_items jsonb, p_contract_version integer) IS 'Ingestão do contrato canônico v1 de disponibilidade. Resolve mapeamento, valida escopo, deduplica e aplica via report_unit_asset_tag_availability. Executável apenas por service_role.';

--
-- Name: fn_assets_loans_conclude_inspection(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_assets_loans_conclude_inspection(p_loan_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id  BIGINT;
    v_loan     public.assets_loans%ROWTYPE;
    v_total    INT;
    v_pending  INT;
    v_no_photo INT;
BEGIN
    IF NOT public.fc_has_route_permission('assets_loans', 'create') THEN
        RAISE EXCEPTION 'Sem permissão para concluir vistorias.' USING ERRCODE = '42501';
    END IF;

    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_loan FROM public.assets_loans WHERE id = p_loan_id FOR UPDATE;
    IF NOT FOUND OR v_loan.is_deleted THEN
        RAISE EXCEPTION 'Registro % não encontrado.', p_loan_id USING ERRCODE = 'P0002';
    END IF;

    IF v_loan.record_type NOT IN ('receipt', 'cedencia') THEN
        RAISE EXCEPTION 'Empréstimos são encerrados pela devolução, não por esta função.'
            USING ERRCODE = '22023';
    END IF;

    IF v_loan.status <> 'analysis' THEN
        RAISE EXCEPTION 'A vistoria já foi concluída.' USING ERRCODE = '22023';
    END IF;

    SELECT count(*),
           count(*) FILTER (WHERE c.status = 'pending'),
           count(*) FILTER (
               WHERE c.status = 'damaged'
                 AND NOT EXISTS (
                     SELECT 1 FROM public.assets_loans_checklists_images i
                      WHERE i.checklist_id = c.id
                 )
           )
      INTO v_total, v_pending, v_no_photo
      FROM public.assets_loans_checklists c
     WHERE c.loan_id = p_loan_id
       AND c.phase = 'single';

    IF v_total = 0 THEN
        RAISE EXCEPTION 'A vistoria não tem itens de checklist.' USING ERRCODE = '22023';
    END IF;
    IF v_pending > 0 THEN
        RAISE EXCEPTION 'Preencha todos os itens do checklist (% pendente(s)).', v_pending
            USING ERRCODE = '22023';
    END IF;
    IF v_no_photo > 0 THEN
        RAISE EXCEPTION 'Todo item danificado precisa de ao menos uma foto (% sem foto).', v_no_photo
            USING ERRCODE = '22023';
    END IF;
    IF v_loan.signature_delivery_path IS NULL OR v_loan.signature_delivery_name IS NULL THEN
        RAISE EXCEPTION 'A assinatura do vistoriador é obrigatória para concluir.'
            USING ERRCODE = '22023';
    END IF;

    -- Sinaliza ao trigger de guarda que este encerramento passou pelas validações.
    PERFORM set_config('siges.assets_loans_conclude', 'on', true);

    UPDATE public.assets_loans
       SET status = 'closed',
           inspector_delivery_user_id = v_user_id,
           updated_at = timezone('America/Sao_Paulo', now())
     WHERE id = p_loan_id;

    PERFORM set_config('siges.assets_loans_conclude', 'off', true);
END;
$$;

--
-- Name: FUNCTION fn_assets_loans_conclude_inspection(p_loan_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_assets_loans_conclude_inspection(p_loan_id bigint) IS 'Conclui Recebimento/Cedência: itens preenchidos, foto em item danificado, assinatura do vistoriador.';

--
-- Name: fn_assets_loans_create(bigint, character varying, character varying, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_assets_loans_create(p_asset_id bigint, p_record_type character varying, p_borrower_name character varying, p_expected_return_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id   BIGINT;
    v_type_id   BIGINT;
    v_loan_id   BIGINT;
    v_items     INT;
    v_now       TIMESTAMP := timezone('America/Sao_Paulo', now());
BEGIN
    IF NOT public.fc_has_route_permission('assets_loans', 'create') THEN
        RAISE EXCEPTION 'Sem permissão para criar registros de empréstimo/vistoria.'
            USING ERRCODE = '42501';
    END IF;

    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    IF p_record_type IS NULL OR p_record_type NOT IN ('loan', 'receipt', 'cedencia') THEN
        RAISE EXCEPTION 'Tipo de registro inválido: %', p_record_type USING ERRCODE = '22023';
    END IF;

    IF NULLIF(btrim(COALESCE(p_borrower_name, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Informe o nome (solicitante / entregue por / cedido para).'
            USING ERRCODE = '22023';
    END IF;

    IF p_record_type = 'loan' AND p_expected_return_date IS NULL THEN
        RAISE EXCEPTION 'A data prevista de devolução é obrigatória para empréstimo.'
            USING ERRCODE = '22023';
    END IF;

    -- Trava o ativo para não criar dois registros em paralelo.
    SELECT a.type_id INTO v_type_id FROM public.assets a WHERE a.id = p_asset_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ativo % não encontrado.', p_asset_id USING ERRCODE = 'P0002';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.assets_loans l
         WHERE l.asset_id = p_asset_id
           AND NOT l.is_deleted
           AND l.status <> 'closed'
    ) THEN
        RAISE EXCEPTION 'Este ativo já possui um registro não encerrado. Conclua-o antes de criar outro.'
            USING ERRCODE = '23505';
    END IF;

    SELECT count(*) INTO v_items
      FROM public.cfg_assets_types_loans_checklists atc
      JOIN public.cfg_loans_checklists c ON c.id = atc.checklist_id
     WHERE atc.asset_type_id = v_type_id
       AND COALESCE(c.is_active, TRUE);

    IF v_items = 0 THEN
        RAISE EXCEPTION 'O tipo deste ativo não tem itens de checklist configurados (Ajustes > Checklists de empréstimo).'
            USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.assets_loans (
        asset_id, record_type, borrower_name, lender_user_id,
        expected_return_date, notes, status,
        created_user_id, created_at, updated_at
    ) VALUES (
        p_asset_id, p_record_type, btrim(p_borrower_name), v_user_id,
        CASE WHEN p_record_type = 'loan' THEN p_expected_return_date ELSE NULL END,
        NULLIF(btrim(COALESCE(p_notes, '')), ''), 'analysis',
        v_user_id, v_now, v_now
    )
    RETURNING id INTO v_loan_id;

    INSERT INTO public.assets_loans_checklists (loan_id, loan_checklist_id, phase, status, created_at)
    SELECT v_loan_id, atc.checklist_id, ph.phase, 'pending', v_now
      FROM public.cfg_assets_types_loans_checklists atc
      JOIN public.cfg_loans_checklists c ON c.id = atc.checklist_id
     CROSS JOIN LATERAL (
            SELECT unnest(
                CASE WHEN p_record_type = 'loan'
                     THEN ARRAY['before', 'after']
                     ELSE ARRAY['single'] END
            ) AS phase
         ) ph
     WHERE atc.asset_type_id = v_type_id
       AND COALESCE(c.is_active, TRUE)
     ORDER BY ph.phase, COALESCE(c.sort_order, 0), c.id;

    RETURN v_loan_id;
END;
$$;

--
-- Name: FUNCTION fn_assets_loans_create(p_asset_id bigint, p_record_type character varying, p_borrower_name character varying, p_expected_return_date date, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_assets_loans_create(p_asset_id bigint, p_record_type character varying, p_borrower_name character varying, p_expected_return_date date, p_notes text) IS 'Cria Empréstimo/Recebimento/Cedência com os itens do checklist do tipo do ativo, numa transação.';

--
-- Name: fn_audit_visit_costs_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_visit_costs_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Log da mudança (pode ser expandido para tabela de auditoria)
  IF OLD.ov_costs_status IS DISTINCT FROM NEW.ov_costs_status THEN
    RAISE NOTICE 'Visit % costs status changed from % to %', 
      NEW.id, OLD.ov_costs_status, NEW.ov_costs_status;
  END IF;
  
  RETURN NEW;
END;
$$;

--
-- Name: fn_guard_assets_loans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_assets_loans() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF TG_OP = 'DELETE' THEN
        IF OLD.status = 'closed' THEN
            RAISE EXCEPTION 'Registro concluído não pode ser excluído.' USING ERRCODE = '42501';
        END IF;
        RETURN OLD;
    END IF;

    -- UPDATE
    IF OLD.status = 'closed' THEN
        RAISE EXCEPTION 'Registro concluído não pode ser alterado ou cancelado.' USING ERRCODE = '42501';
    END IF;

    IF NEW.record_type IS DISTINCT FROM OLD.record_type THEN
        RAISE EXCEPTION 'O tipo do registro não pode ser alterado.' USING ERRCODE = '42501';
    END IF;

    IF NEW.record_type <> 'loan'
       AND NEW.status = 'closed'
       AND COALESCE(current_setting('siges.assets_loans_conclude', true), 'off') <> 'on' THEN
        RAISE EXCEPTION 'Recebimento/Cedência só pode ser concluído pela conclusão da vistoria.'
            USING ERRCODE = '42501';
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: fn_guard_assets_loans_checklists(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_assets_loans_checklists() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_loan_id BIGINT := COALESCE(NEW.loan_id, OLD.loan_id);
    v_type    VARCHAR;
    v_status  VARCHAR;
BEGIN
    SELECT l.record_type, l.status INTO v_type, v_status
      FROM public.assets_loans l WHERE l.id = v_loan_id;

    IF TG_OP <> 'DELETE' THEN
        IF (v_type = 'loan' AND NEW.phase NOT IN ('before', 'after'))
           OR (v_type <> 'loan' AND NEW.phase <> 'single') THEN
            RAISE EXCEPTION 'Fase "%" incompatível com o tipo de registro "%".', NEW.phase, v_type
                USING ERRCODE = '22023';
        END IF;
    END IF;

    IF auth.uid() IS NOT NULL AND v_status = 'closed' THEN
        RAISE EXCEPTION 'Checklist de registro concluído não pode ser alterado.' USING ERRCODE = '42501';
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;

--
-- Name: fn_guard_assets_loans_checklists_images(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_assets_loans_checklists_images() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_status VARCHAR;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    SELECT l.status INTO v_status
      FROM public.assets_loans_checklists c
      JOIN public.assets_loans l ON l.id = c.loan_id
     WHERE c.id = COALESCE(NEW.checklist_id, OLD.checklist_id);

    IF v_status = 'closed' THEN
        RAISE EXCEPTION 'Imagens de registro concluído não podem ser alteradas.' USING ERRCODE = '42501';
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;

--
-- Name: fn_guard_orders_visits_signatures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_orders_visits_signatures() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_leader_changed BOOLEAN;
    v_requester_changed BOOLEAN;
    v_user_id BIGINT;
BEGIN
    v_leader_changed :=
           NEW.ov_signature_leader_path IS DISTINCT FROM OLD.ov_signature_leader_path
        OR NEW.ov_signature_leader_name IS DISTINCT FROM OLD.ov_signature_leader_name
        OR NEW.ov_signature_leader_at   IS DISTINCT FROM OLD.ov_signature_leader_at;

    v_requester_changed :=
           NEW.ov_signature_requester_path IS DISTINCT FROM OLD.ov_signature_requester_path
        OR NEW.ov_signature_requester_name IS DISTINCT FROM OLD.ov_signature_requester_name
        OR NEW.ov_signature_requester_at   IS DISTINCT FROM OLD.ov_signature_requester_at;

    IF NOT (v_leader_changed OR v_requester_changed) THEN
        RETURN NEW;
    END IF;

    -- Rotinas de servidor (service_role / sem sessão de usuário).
    IF auth.uid() IS NULL THEN
        RETURN NEW;
    END IF;

    -- Regra 1: visita aprovada ou arquivada → assinaturas congeladas.
    IF COALESCE(OLD.ov_is_filed, false) OR COALESCE(OLD.ov_processing_id, 0) = 5 THEN
        RAISE EXCEPTION 'Assinaturas não podem ser alteradas em visita aprovada ou arquivada.'
            USING ERRCODE = '42501';
    END IF;

    -- Regra 2: assinatura do líder → só o líder da visita.
    IF v_leader_changed THEN
        SELECT u.id INTO v_user_id
          FROM public.users u
         WHERE u.uuid = auth.uid()
         LIMIT 1;

        IF v_user_id IS NULL OR v_user_id IS DISTINCT FROM OLD.ov_team_leader_id THEN
            RAISE EXCEPTION 'Somente o líder da equipe desta visita pode assinar ou excluir a assinatura do líder.'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: FUNCTION fn_guard_orders_visits_signatures(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_guard_orders_visits_signatures() IS 'Bloqueia alterar assinaturas em visita aprovada/arquivada e restringe a assinatura do líder ao líder da visita.';

--
-- Name: fn_guard_users_admin_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_users_admin_flags() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller RECORD;
    v_admin_changed BOOLEAN;
    v_super_changed BOOLEAN;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN NEW;  -- SQL Editor / service_role / jobs
    END IF;

    IF TG_OP = 'INSERT' THEN
        v_admin_changed := COALESCE(NEW.is_admin, false);
        v_super_changed := COALESCE(NEW.is_admin_super, false);
    ELSE
        v_admin_changed := NEW.is_admin IS DISTINCT FROM OLD.is_admin;
        v_super_changed := NEW.is_admin_super IS DISTINCT FROM OLD.is_admin_super;
    END IF;

    IF NOT (v_admin_changed OR v_super_changed) THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_caller FROM public.fn_users_caller();

    IF v_super_changed AND NOT COALESCE(v_caller.is_admin_super, false) THEN
        RAISE EXCEPTION 'Somente super administrador pode alterar is_admin_super.' USING ERRCODE = '42501';
    END IF;
    IF v_admin_changed AND NOT (COALESCE(v_caller.is_admin, false) OR COALESCE(v_caller.is_admin_super, false)) THEN
        RAISE EXCEPTION 'Somente administrador pode alterar is_admin.' USING ERRCODE = '42501';
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: fn_guard_users_team_vehicle_leader(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_users_team_vehicle_leader() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_is_admin  BOOLEAN;
    v_is_leader BOOLEAN;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN NEW;  -- SQL Editor / service_role / jobs
    END IF;

    SELECT COALESCE(u.is_admin, false) OR COALESCE(u.is_admin_super, false),
           COALESCE(u.is_team_leader, false)
      INTO v_is_admin, v_is_leader
      FROM public.users u
     WHERE u.uuid = auth.uid()
     LIMIT 1;

    -- Vale para TODOS os usuários logados, inclusive admin.
    IF TG_OP = 'UPDATE' AND NEW.team_id IS NULL AND OLD.team_id IS NOT NULL THEN
        RAISE EXCEPTION 'Todo usuário precisa estar em uma equipe. Transfira-o para outra equipe em vez de removê-lo.'
            USING ERRCODE = '23514';
    END IF;

    IF COALESCE(v_is_admin, false) THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        -- Cadastro feito por não admin nunca nasce líder.
        NEW.is_team_leader := false;
        RETURN NEW;
    END IF;

    IF NEW.is_team_leader IS DISTINCT FROM OLD.is_team_leader THEN
        RAISE EXCEPTION 'Somente administrador pode definir líder de equipe.'
            USING ERRCODE = '42501';
    END IF;

    IF (NEW.team_id IS DISTINCT FROM OLD.team_id
        OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id)
       AND NOT COALESCE(v_is_leader, false) THEN
        RAISE EXCEPTION 'Somente líder de equipe ou administrador pode alterar equipe ou veículo.'
            USING ERRCODE = '42501';
    END IF;

    IF NEW.team_id IS DISTINCT FROM OLD.team_id THEN
        IF COALESCE(OLD.is_ov_in_progress, false) OR COALESCE(OLD.ov_id_in_progress, 0) > 0 THEN
            RAISE EXCEPTION 'Não é possível mudar a equipe de quem está com uma visita em andamento.'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

--
-- Name: fn_jsonb_contains_forbidden_keys(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_jsonb_contains_forbidden_keys(p_value jsonb, p_forbidden_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    WITH RECURSIVE walk(value) AS (
        SELECT p_value
        WHERE p_value IS NOT NULL
        UNION ALL
        SELECT child.value
        FROM walk w
        CROSS JOIN LATERAL (
            SELECT e.value
            FROM jsonb_each(
                CASE WHEN jsonb_typeof(w.value) = 'object' THEN w.value ELSE '{}'::jsonb END
            ) AS e(key, value)
            UNION ALL
            SELECT a.value
            FROM jsonb_array_elements(
                CASE WHEN jsonb_typeof(w.value) = 'array' THEN w.value ELSE '[]'::jsonb END
            ) AS a(value)
        ) AS child
    )
    SELECT EXISTS (
        SELECT 1
        FROM walk w
        WHERE jsonb_typeof(w.value) = 'object'
          AND EXISTS (
              SELECT 1
              FROM jsonb_object_keys(w.value) AS k(key)
              WHERE lower(k.key) = ANY (p_forbidden_keys)
          )
    );
$$;

--
-- Name: fn_log_assets_available_integration_event(bigint, bigint, bigint, text, text, timestamp without time zone, boolean, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_log_assets_available_integration_event(p_integration_id bigint, p_mapping_id bigint, p_unit_asset_tag_id bigint, p_external_id text, p_source_event_id text, p_source_reported_at timestamp without time zone, p_is_available boolean, p_result text, p_message text, p_asset_available_id bigint) RETURNS bigint
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    INSERT INTO public.logs_assets_available_integrations_events (
        integration_id, mapping_id, unit_asset_tag_id, external_id,
        source_event_id, source_reported_at, is_available, result, message,
        asset_available_id
    ) VALUES (
        p_integration_id, p_mapping_id, p_unit_asset_tag_id, p_external_id,
        p_source_event_id, p_source_reported_at, p_is_available, p_result,
        left(regexp_replace(COALESCE(p_message, ''), '[[:cntrl:]]+', ' ', 'g'), 500),
        p_asset_available_id
    )
    RETURNING id;
$$;

--
-- Name: fn_offline_change_versions(bigint, bigint[], bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_offline_change_versions(p_company_id bigint, p_unit_ids bigint[] DEFAULT '{}'::bigint[], p_asset_type_ids bigint[] DEFAULT '{}'::bigint[], p_order_type_ids bigint[] DEFAULT '{}'::bigint[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT jsonb_build_object(
    'units', COALESCE((
        SELECT jsonb_object_agg(x.unit_id::text,
            (SELECT count(*) || ':' || COALESCE(max(GREATEST(a.created_at, a.updated_at, a.deleted_at))::text, '')
               FROM public.assets a WHERE a.unit_id = x.unit_id)
            || '|' ||
            (SELECT count(*) || ':' || COALESCE(max(GREATEST(t.created_at, t.updated_at, t.deleted_at))::text, '')
               FROM public.cfg_units_assets_tags t WHERE t.unit_id = x.unit_id))
          FROM (SELECT DISTINCT unnest(p_unit_ids) AS unit_id) x
    ), '{}'::jsonb),

    'asset_types', COALESCE((
        SELECT jsonb_object_agg(x.type_id::text,
            (SELECT count(*) || ':' || COALESCE(max(GREATEST(p.created_at, p.updated_at, p.deleted_at))::text, '')
               FROM public.maintenances_plans p WHERE p.asset_type_id = x.type_id)
            || '|' ||
            (SELECT count(*) || ':' || COALESCE(max(GREATEST(s.created_at, s.updated_at, s.deleted_at))::text, '')
               FROM public.maintenances_plans_sections s
               JOIN public.maintenances_plans p ON p.id = s.maintenance_plan_id
              WHERE p.asset_type_id = x.type_id)
            || '|' ||
            (SELECT count(*) || ':' || COALESCE(max(GREATEST(sa.created_at, sa.updated_at, sa.deleted_at))::text, '')
               FROM public.maintenances_plans_sections_activities sa
               JOIN public.maintenances_plans_sections s ON s.id = sa.maintenance_plan_section_id
               JOIN public.maintenances_plans p ON p.id = s.maintenance_plan_id
              WHERE p.asset_type_id = x.type_id))
          FROM (SELECT DISTINCT unnest(p_asset_type_ids) AS type_id) x
    ), '{}'::jsonb),

    'order_types', COALESCE((
        SELECT jsonb_object_agg(x.type_id::text, COALESCE((
            SELECT md5(string_agg(
                       concat_ws(':', ota.id, ota.activity_id, ota.is_available,
                                 ca.description, ca.code, ca.is_available, ca.is_deleted),
                       ',' ORDER BY ota.id))
              FROM public.cfg_orders_types_activities ota
              LEFT JOIN public.cfg_activities ca ON ca.id = ota.activity_id
             WHERE ota.o_type_id = x.type_id), ''))
          FROM (SELECT DISTINCT unnest(p_order_type_ids) AS type_id) x
    ), '{}'::jsonb),

    'materials', (
        SELECT count(*) || ':' || COALESCE(max(GREATEST(m.created_at, m.updated_at, m.deleted_at))::text, '')
          FROM public.materials m WHERE m.provider_company_id = p_company_id),

    'vehicles', (
        SELECT count(*) || ':' || COALESCE(max(GREATEST(v.created_at, v.updated_at, v.deleted_at))::text, '')
          FROM public.vehicles v WHERE v.company_id = p_company_id),

    'users', (
        SELECT count(*) || ':' || COALESCE(max(GREATEST(u.created_at, u.updated_at))::text, '')
          FROM public.users u)
);
$$;

--
-- Name: FUNCTION fn_offline_change_versions(p_company_id bigint, p_unit_ids bigint[], p_asset_type_ids bigint[], p_order_type_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_offline_change_versions(p_company_id bigint, p_unit_ids bigint[], p_asset_type_ids bigint[], p_order_type_ids bigint[]) IS 'Modo offline: versão (contagem + última data, ou md5) de cada grupo de dados baixado no aparelho; o app baixa de novo só o que mudou.';

--
-- Name: fn_offline_enabled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_offline_enabled() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT COALESCE(u.offline_enabled, c.offline_enabled, false)
      FROM public.users u
      LEFT JOIN public.cfg_teams t ON t.id = u.team_id
      LEFT JOIN public.cfg_companies c ON c.id = COALESCE(t.company_id, u.company_id)
     WHERE u.uuid = auth.uid()
     LIMIT 1;
$$;

--
-- Name: FUNCTION fn_offline_enabled(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_offline_enabled() IS 'Modo offline liberado para o usuário logado (usuário > empresa > false). SECURITY INVOKER.';

--
-- Name: fn_orders_completed_counts(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_completed_counts(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_today        date := (timezone('America/Sao_Paulo', now()))::date;
    v_monday       date;
    v_month_start  date;
    v_prev_month   date;
    v_from         date;
    v_search       text := NULLIF(btrim(COALESCE(p_filters->>'search', '')), '');
    v_result       jsonb;
BEGIN
    v_monday      := v_today - (EXTRACT(ISODOW FROM v_today)::int - 1);
    v_month_start := date_trunc('month', v_today)::date;
    v_prev_month  := (v_month_start - INTERVAL '1 month')::date;
    v_from        := LEAST(v_monday - 7, v_prev_month);

    WITH f AS (
        SELECT o.status_at
          FROM public.v_orders o
         WHERE o.parent_id > 0
           AND o.status_id = 8
           AND o.status_at >= v_from
           AND o.status_at <  v_today + 1
           AND (NOT (p_filters ? 'system_parent_id')    OR o.system_parent_id    = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'system_parent_id')::bigint)))
           AND (NOT (p_filters ? 'system_id')           OR o.system_id           = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'system_id')::bigint)))
           AND (NOT (p_filters ? 'unit_type_parent_id') OR o.unit_type_parent_id = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'unit_type_parent_id')::bigint)))
           AND (NOT (p_filters ? 'unit_type_id')        OR o.unit_type_id        = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'unit_type_id')::bigint)))
           AND (NOT (p_filters ? 'unit_id')             OR o.unit_id             = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'unit_id')::bigint)))
           AND (NOT (p_filters ? 'asset_tag_id')        OR o.asset_tag_id        = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'asset_tag_id')::bigint)))
           AND (NOT (p_filters ? 'asset_tag_sub_id')    OR o.asset_tag_sub_id    = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'asset_tag_sub_id')::bigint)))
           AND (NOT (p_filters ? 'object_id')           OR o.object_id           = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'object_id')::bigint)))
           AND (NOT (p_filters ? 'type_id')             OR o.type_id             = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'type_id')::bigint)))
           AND (NOT (p_filters ? 'type_sub_id')         OR o.type_sub_id         = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'type_sub_id')::bigint)))
           AND (NOT (p_filters ? 'contract_id')         OR o.contract_id         = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'contract_id')::bigint)))
           AND (NOT (p_filters ? 'plan_id')             OR o.plan_id             = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'plan_id')::bigint)))
           AND (NOT (p_filters ? 'requester_team_id')   OR o.requester_team_id   = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'requester_team_id')::bigint)))
           AND (NOT (p_filters ? 'team_id')             OR o.team_id             = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'team_id')::bigint)))
           AND (NOT (p_filters ? 'priority_id')         OR o.priority_id         = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'priority_id')::bigint)))
           AND (NOT (p_filters ? 'provider_company_id') OR o.provider_company_id = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'provider_company_id')::bigint)))
           AND (NOT (p_filters ? 'cause_reason_id')     OR o.cause_reason_id     = ANY (ARRAY(SELECT jsonb_array_elements_text(p_filters->'cause_reason_id')::bigint)))
           AND (v_search IS NULL OR
                o.order_mask            ILIKE '%' || v_search || '%' OR
                o.unit_description      ILIKE '%' || v_search || '%' OR
                o.type_description      ILIKE '%' || v_search || '%' OR
                o.requested_services    ILIKE '%' || v_search || '%')
    )
    SELECT jsonb_build_object(
               'today',     count(*) FILTER (WHERE status_at >= v_today),
               'yesterday', count(*) FILTER (WHERE status_at >= v_today - 1 AND status_at < v_today),
               'thisWeek',  count(*) FILTER (WHERE status_at >= v_monday),
               'lastWeek',  count(*) FILTER (WHERE status_at >= v_monday - 7 AND status_at < v_monday),
               'thisMonth', count(*) FILTER (WHERE status_at >= v_month_start),
               'lastMonth', count(*) FILTER (WHERE status_at >= v_prev_month AND status_at < v_month_start)
           )
      INTO v_result
      FROM f;

    RETURN v_result;
END;
$$;

--
-- Name: FUNCTION fn_orders_completed_counts(p_filters jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_orders_completed_counts(p_filters jsonb) IS 'Contagens de OS concluídas por período (hoje/ontem/semana/semana passada/mês/mês passado) em America/Sao_Paulo, sobre v_orders.';

--
-- Name: fn_orders_daily_priorities_save(bigint, date, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_daily_priorities_save(p_contract_id bigint, p_date date, p_order_ids bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id     BIGINT;
    v_schedule_id BIGINT;
    v_today       DATE := (timezone('America/Sao_Paulo', now()))::date;
BEGIN
    IF NOT public.fc_has_route_permission('orders_daily_schedule', 'create') THEN
        RAISE EXCEPTION 'Sem permissão para ordenar as prioridades da programação diária.' USING ERRCODE = '42501';
    END IF;

    IF p_contract_id IS NULL OR p_date IS NULL THEN
        RAISE EXCEPTION 'Contrato e data são obrigatórios.' USING ERRCODE = '22023';
    END IF;

    IF p_date < v_today THEN
        RAISE EXCEPTION 'Dias passados são somente leitura.' USING ERRCODE = '22023';
    END IF;

    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;

    INSERT INTO public.orders_daily_schedules (contract_id, schedule_date, created_user_id, updated_user_id)
    VALUES (p_contract_id, p_date, v_user_id, v_user_id)
    ON CONFLICT (contract_id, schedule_date)
    DO UPDATE SET updated_user_id = EXCLUDED.updated_user_id,
                  updated_at      = timezone('America/Sao_Paulo', now())
    RETURNING id INTO v_schedule_id;

    -- Serializa gravações concorrentes do mesmo dia.
    PERFORM 1 FROM public.orders_daily_schedules WHERE id = v_schedule_id FOR UPDATE;

    DELETE FROM public.orders_daily_schedules_priorities WHERE schedule_id = v_schedule_id;

    INSERT INTO public.orders_daily_schedules_priorities (schedule_id, order_id, position)
    SELECT v_schedule_id,
           x.order_id,
           ROW_NUMBER() OVER (ORDER BY x.ord)
      FROM (
            SELECT DISTINCT ON (u.order_id) u.order_id, u.ord
              FROM unnest(COALESCE(p_order_ids, ARRAY[]::BIGINT[])) WITH ORDINALITY AS u(order_id, ord)
             ORDER BY u.order_id, u.ord
           ) x
      JOIN public.orders o ON o.id = x.order_id
     WHERE o.contract_id = p_contract_id
       AND o.parent_id IS NOT NULL
       AND o.status_id NOT IN (7, 8);

    RETURN v_schedule_id;
END;
$$;

--
-- Name: fn_orders_daily_schedule_board(bigint, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_daily_schedule_board(p_contract_id bigint, p_date date, p_read_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_schedule_id  BIGINT;
    v_updated_at   TIMESTAMP;
    v_source_id    BIGINT;   -- cabeçalho de onde vem a prioridade (o do dia ou o herdado)
    v_inherited    DATE;
    v_items        jsonb := '[]'::jsonb;
    v_priorities   jsonb := '[]'::jsonb;
    v_orders       jsonb := '[]'::jsonb;
    v_ids          BIGINT[];
BEGIN
    IF p_contract_id IS NULL OR p_date IS NULL THEN
        RAISE EXCEPTION 'Contrato e data são obrigatórios.' USING ERRCODE = '22023';
    END IF;

    SELECT s.id, s.updated_at
      INTO v_schedule_id, v_updated_at
      FROM public.orders_daily_schedules s
     WHERE s.contract_id = p_contract_id
       AND s.schedule_date = p_date;

    IF v_schedule_id IS NOT NULL THEN
        v_source_id := v_schedule_id;
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                   'order_id', i.order_id, 'team_id', i.team_id, 'position', i.position)), '[]'::jsonb)
          INTO v_items
          FROM public.orders_daily_schedules_items i
         WHERE i.schedule_id = v_schedule_id;
    ELSIF NOT p_read_only THEN
        -- Dia SEM registro nenhum: última prioridade registrada antes dele.
        -- (Dia com registro e prioridade vazia = esvaziada de propósito: não herda.)
        SELECT s.id, s.schedule_date
          INTO v_source_id, v_inherited
          FROM public.orders_daily_schedules s
         WHERE s.contract_id = p_contract_id
           AND s.schedule_date < p_date
           AND EXISTS (SELECT 1 FROM public.orders_daily_schedules_priorities p WHERE p.schedule_id = s.id)
         ORDER BY s.schedule_date DESC
         LIMIT 1;
    END IF;

    IF v_source_id IS NOT NULL THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object('order_id', p.order_id, 'position', p.position)), '[]'::jsonb)
          INTO v_priorities
          FROM public.orders_daily_schedules_priorities p
         WHERE p.schedule_id = v_source_id;
    END IF;

    IF p_read_only THEN
        SELECT array_agg(DISTINCT x.order_id)
          INTO v_ids
          FROM (
                SELECT (e ->> 'order_id')::BIGINT AS order_id FROM jsonb_array_elements(v_items) e
                UNION
                SELECT (e ->> 'order_id')::BIGINT FROM jsonb_array_elements(v_priorities) e
               ) x;
        IF v_ids IS NOT NULL THEN
            SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY v.requested_at), '[]'::jsonb)
              INTO v_orders
              FROM public.v_orders_daily_schedule v
             WHERE v.id = ANY (v_ids);
        END IF;
    ELSE
        SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY v.requested_at), '[]'::jsonb)
          INTO v_orders
          FROM public.v_orders_daily_schedule v
         WHERE v.contract_id = p_contract_id
           AND v.parent_id IS NOT NULL
           AND v.status_id NOT IN (7, 8);
    END IF;

    RETURN jsonb_build_object(
        'schedule',       CASE WHEN v_schedule_id IS NULL THEN NULL
                               ELSE jsonb_build_object('id', v_schedule_id, 'updated_at', v_updated_at) END,
        'items',          v_items,
        'priorities',     v_priorities,
        'inherited_from', v_inherited,
        'orders',         v_orders
    );
END;
$$;

--
-- Name: fn_orders_daily_schedule_log(bigint, date, bigint, character varying, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_daily_schedule_log(p_contract_id bigint, p_date date, p_order_id bigint, p_action character varying, p_from_team_id bigint DEFAULT NULL::bigint, p_to_team_id bigint DEFAULT NULL::bigint, p_to_position integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_id      BIGINT;
    v_today   DATE := (timezone('America/Sao_Paulo', now()))::date;
BEGIN
    IF NOT public.fc_has_route_permission('orders_daily_schedule', 'create') THEN
        RAISE EXCEPTION 'Sem permissão para movimentar a programação diária.' USING ERRCODE = '42501';
    END IF;

    IF p_contract_id IS NULL OR p_date IS NULL OR p_order_id IS NULL OR p_action IS NULL THEN
        RAISE EXCEPTION 'Contrato, data, OS e ação são obrigatórios.' USING ERRCODE = '22023';
    END IF;

    IF p_date < v_today THEN
        RAISE EXCEPTION 'Dias passados são somente leitura.' USING ERRCODE = '22023';
    END IF;

    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;

    INSERT INTO public.orders_daily_schedules_logs
        (contract_id, schedule_date, order_id, action, from_team_id, to_team_id, to_position, user_id)
    VALUES
        (p_contract_id, p_date, p_order_id, p_action, p_from_team_id, p_to_team_id,
         CASE WHEN p_to_position > 0 THEN p_to_position END, v_user_id)
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;

--
-- Name: fn_orders_daily_schedule_my_day(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_daily_schedule_my_day(p_date date DEFAULT NULL::date) RETURNS TABLE(order_id bigint, team_id bigint, "position" integer, schedule_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT i.order_id, i.team_id, i.position, s.schedule_date
      FROM public.orders_daily_schedules s
      JOIN public.orders_daily_schedules_items i ON i.schedule_id = s.id
      JOIN public.orders o ON o.id = i.order_id
     WHERE s.schedule_date = COALESCE(p_date, (timezone('America/Sao_Paulo', now()))::date)
       AND i.team_id = (SELECT u.team_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1)
       AND o.status_id NOT IN (7, 8)
     ORDER BY i.position;
$$;

--
-- Name: fn_orders_daily_schedule_save(bigint, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_daily_schedule_save(p_contract_id bigint, p_date date, p_items jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id     BIGINT;
    v_schedule_id BIGINT;
    v_today       DATE := (timezone('America/Sao_Paulo', now()))::date;
    v_bad         RECORD;
BEGIN
    IF NOT public.fc_has_route_permission('orders_daily_schedule', 'create') THEN
        RAISE EXCEPTION 'Sem permissão para programar (criar) a programação diária.' USING ERRCODE = '42501';
    END IF;

    IF p_contract_id IS NULL OR p_date IS NULL THEN
        RAISE EXCEPTION 'Contrato e data são obrigatórios.' USING ERRCODE = '22023';
    END IF;

    IF p_date < v_today THEN
        RAISE EXCEPTION 'Dias passados são somente leitura.' USING ERRCODE = '22023';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RAISE EXCEPTION 'Itens inválidos.' USING ERRCODE = '22023';
    END IF;

    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;

    -- Valida cada item contra a OS real.
    SELECT o.order_mask, i.order_id, o.contract_id, o.status_id, o.team_id, i.team_id AS item_team_id
      INTO v_bad
      FROM (
            SELECT (e.elem ->> 'order_id')::BIGINT AS order_id,
                   (e.elem ->> 'team_id')::BIGINT  AS team_id
              FROM jsonb_array_elements(p_items) AS e(elem)
           ) i
      LEFT JOIN public.orders o ON o.id = i.order_id
     WHERE o.id IS NULL
        OR o.contract_id IS DISTINCT FROM p_contract_id
        OR o.parent_id IS NULL
        OR o.status_id NOT IN (3, 4, 5, 6)
        OR o.team_id IS DISTINCT FROM i.team_id
     LIMIT 1;

    IF FOUND THEN
        RAISE EXCEPTION 'OS % não pode ser programada nesta coluna (situação ou equipe mudou). Recarregue a tela.',
            COALESCE(v_bad.order_mask, v_bad.order_id::text)
            USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.orders_daily_schedules (contract_id, schedule_date, created_user_id, updated_user_id)
    VALUES (p_contract_id, p_date, v_user_id, v_user_id)
    ON CONFLICT (contract_id, schedule_date)
    DO UPDATE SET updated_user_id = EXCLUDED.updated_user_id,
                  updated_at      = timezone('America/Sao_Paulo', now())
    RETURNING id INTO v_schedule_id;

    -- Serializa gravações concorrentes do mesmo dia.
    PERFORM 1 FROM public.orders_daily_schedules WHERE id = v_schedule_id FOR UPDATE;

    DELETE FROM public.orders_daily_schedules_items WHERE schedule_id = v_schedule_id;

    INSERT INTO public.orders_daily_schedules_items (schedule_id, order_id, team_id, position)
    SELECT v_schedule_id,
           i.order_id,
           i.team_id,
           ROW_NUMBER() OVER (PARTITION BY i.team_id ORDER BY i.ord)
      FROM (
            SELECT (e.elem ->> 'order_id')::BIGINT AS order_id,
                   (e.elem ->> 'team_id')::BIGINT  AS team_id,
                   e.ord
              FROM jsonb_array_elements(p_items) WITH ORDINALITY AS e(elem, ord)
           ) i
    ON CONFLICT (schedule_id, order_id) DO NOTHING;

    RETURN v_schedule_id;
END;
$$;

--
-- Name: fn_orders_dashboard_filter_id(jsonb, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_dashboard_filter_id(p_filters jsonb, p_key text, p_value bigint) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT CASE
        WHEN p_filters IS NULL
          OR NOT (p_filters ? p_key)
          OR p_filters -> p_key = 'null'::jsonb
          OR p_filters -> p_key = '""'::jsonb
          OR p_filters -> p_key = '[]'::jsonb
          OR lower(p_filters ->> p_key) IN ('null', 'undefined')
        THEN true
        WHEN jsonb_typeof(p_filters -> p_key) = 'array'
        THEN NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(p_filters -> p_key) AS items(value)
            WHERE lower(value) NOT IN ('', 'null', 'undefined')
        ) OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(p_filters -> p_key) AS items(value)
            WHERE lower(value) NOT IN ('', 'null', 'undefined')
              AND value = p_value::text
        )
        ELSE p_filters ->> p_key = p_value::text
    END;
$$;

--
-- Name: fn_orders_dashboard_filter_ids(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_dashboard_filter_ids(p_filters jsonb, p_key text) RETURNS bigint[]
    LANGUAGE sql IMMUTABLE
    AS $_$
    SELECT CASE
        WHEN p_filters IS NULL
          OR NOT (p_filters ? p_key)
          OR jsonb_typeof(p_filters -> p_key) = 'null'
        THEN NULL
        ELSE (
            SELECT CASE
                       WHEN count(*) = 0 THEN NULL
                       ELSE COALESCE(array_agg(v::bigint) FILTER (WHERE v ~ '^-?[0-9]+$'), '{}'::bigint[])
                   END
              FROM jsonb_array_elements_text(
                       CASE WHEN jsonb_typeof(p_filters -> p_key) = 'array'
                            THEN p_filters -> p_key
                            ELSE jsonb_build_array(p_filters ->> p_key)
                       END
                   ) AS t(v)
             WHERE lower(v) NOT IN ('', 'null', 'undefined')
        )
    END;
$_$;

--
-- Name: fn_orders_dashboard_stats(jsonb, jsonb, jsonb, boolean, date, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_dashboard_stats(p_filters jsonb DEFAULT '{}'::jsonb, p_ss_filters jsonb DEFAULT NULL::jsonb, p_os_filters jsonb DEFAULT NULL::jsonb, p_parent_view boolean DEFAULT false, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_skip_ss boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH
clock AS (
    SELECT timezone('America/Sao_Paulo', now())::date AS today
),
effective_ss_filters AS (
    SELECT COALESCE(p_ss_filters, p_filters, '{}'::jsonb) AS filters
),
effective_os_filters AS (
    SELECT COALESCE(p_os_filters, p_filters, '{}'::jsonb) AS filters
),
-- Filtros convertidos UMA vez em bigint[] (NULL = sem filtro).
ss_f AS MATERIALIZED (
    SELECT
        filters,
        NULLIF(filters ->> 'search', '') AS search,
        public.fn_orders_dashboard_filter_ids(filters, 'systemParentId') AS "systemParentId",
        public.fn_orders_dashboard_filter_ids(filters, 'systemId') AS "systemId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitTypeParentId') AS "unitTypeParentId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitTypeId') AS "unitTypeId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitId') AS "unitId",
        public.fn_orders_dashboard_filter_ids(filters, 'assetTagId') AS "assetTagId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderObjectId') AS "orderObjectId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTypeId') AS "orderTypeId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTypeSubId') AS "orderTypeSubId",
        public.fn_orders_dashboard_filter_ids(filters, 'contractId') AS "contractId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderPlanId') AS "orderPlanId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTeamId') AS "orderTeamId",
        public.fn_orders_dashboard_filter_ids(filters, 'responsibleTeamId') AS "responsibleTeamId",
        public.fn_orders_dashboard_filter_ids(filters, 'priorityId') AS "priorityId",
        public.fn_orders_dashboard_filter_ids(filters, 'providerCompanyId') AS "providerCompanyId",
        public.fn_orders_dashboard_filter_ids(filters, 'causeReasonId') AS "causeReasonId"
    FROM effective_ss_filters
),
os_f AS MATERIALIZED (
    SELECT
        filters,
        NULLIF(filters ->> 'search', '') AS search,
        public.fn_orders_dashboard_filter_ids(filters, 'systemParentId') AS "systemParentId",
        public.fn_orders_dashboard_filter_ids(filters, 'systemId') AS "systemId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitTypeParentId') AS "unitTypeParentId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitTypeId') AS "unitTypeId",
        public.fn_orders_dashboard_filter_ids(filters, 'unitId') AS "unitId",
        public.fn_orders_dashboard_filter_ids(filters, 'assetTagId') AS "assetTagId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderObjectId') AS "orderObjectId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTypeId') AS "orderTypeId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTypeSubId') AS "orderTypeSubId",
        public.fn_orders_dashboard_filter_ids(filters, 'contractId') AS "contractId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderPlanId') AS "orderPlanId",
        public.fn_orders_dashboard_filter_ids(filters, 'orderTeamId') AS "orderTeamId",
        public.fn_orders_dashboard_filter_ids(filters, 'responsibleTeamId') AS "responsibleTeamId",
        public.fn_orders_dashboard_filter_ids(filters, 'priorityId') AS "priorityId",
        public.fn_orders_dashboard_filter_ids(filters, 'providerCompanyId') AS "providerCompanyId",
        public.fn_orders_dashboard_filter_ids(filters, 'causeReasonId') AS "causeReasonId",
        public.fn_orders_dashboard_filter_ids(filters, 'statusId') AS "statusId"
    FROM effective_os_filters
),
-- MATERIALIZED: v_orders é montada uma vez (antes: duas, uma para SS e outra para OS).
-- status 7/8 (fechadas) descartados já aqui: nem SS (status 1) nem OS os usam.
source_orders AS MATERIALIZED (
    SELECT
        o.requested_at,
        o.status_id,
        o.parent_id,
        o.asset_tag_id,
        o.asset_tag_description,
        o.system_parent_id,
        o.system_id,
        o.unit_type_parent_id,
        o.unit_type_id,
        o.unit_id,
        o.object_id,
        o.type_id,
        o.type_sub_id,
        o.contract_id,
        o.plan_id,
        o.requester_team_id,
        o.team_id,
        o.priority_id,
        o.provider_company_id,
        o.cause_reason_id,
        o.order_mask,
        o.unit_description,
        o.type_description,
        o.requested_services
    FROM public.v_orders AS o
    WHERE NOT p_parent_view
      AND o.status_id NOT IN (7, 8)

    UNION ALL

    SELECT
        o.requested_at,
        o.status_id,
        o.parent_id,
        o.asset_tag_id,
        o.asset_tag_description,
        o.system_parent_id,
        o.system_id,
        o.unit_type_parent_id,
        o.unit_type_id,
        o.unit_id,
        o.object_id,
        o.type_id,
        o.type_sub_id,
        o.contract_id,
        o.plan_id,
        o.requester_team_id,
        o.team_id,
        o.priority_id,
        o.provider_company_id,
        o.cause_reason_id,
        o.order_mask,
        o.unit_description,
        o.type_description,
        o.requested_services
    FROM public.v_orders_parent AS o
    WHERE p_parent_view
      AND o.status_id NOT IN (7, 8)
),
ss_orders AS MATERIALIZED (
    SELECT
        o.requested_at,
        o.asset_tag_id,
        o.asset_tag_description
    FROM source_orders AS o
    CROSS JOIN ss_f AS f
    WHERE NOT p_skip_ss
      AND o.status_id = 1
      AND o.parent_id IS NULL
      AND (p_start_date IS NULL OR o.requested_at >= p_start_date::timestamp)
      AND (p_end_date IS NULL OR o.requested_at < (p_end_date + 1)::timestamp)
      AND (f."systemParentId" IS NULL OR o.system_parent_id = ANY (f."systemParentId"))
      AND (f."systemId" IS NULL OR o.system_id = ANY (f."systemId"))
      AND (f."unitTypeParentId" IS NULL OR o.unit_type_parent_id = ANY (f."unitTypeParentId"))
      AND (f."unitTypeId" IS NULL OR o.unit_type_id = ANY (f."unitTypeId"))
      AND (f."unitId" IS NULL OR o.unit_id = ANY (f."unitId"))
      AND (f."assetTagId" IS NULL OR o.asset_tag_id = ANY (f."assetTagId"))
      AND (f."orderObjectId" IS NULL OR o.object_id = ANY (f."orderObjectId"))
      AND (f."orderTypeId" IS NULL OR o.type_id = ANY (f."orderTypeId"))
      AND (f."orderTypeSubId" IS NULL OR o.type_sub_id = ANY (f."orderTypeSubId"))
      AND (f."contractId" IS NULL OR o.contract_id = ANY (f."contractId"))
      AND (f."orderPlanId" IS NULL OR o.plan_id = ANY (f."orderPlanId"))
      AND (f."orderTeamId" IS NULL OR o.requester_team_id = ANY (f."orderTeamId"))
      AND (f."responsibleTeamId" IS NULL OR o.team_id = ANY (f."responsibleTeamId"))
      AND (f."priorityId" IS NULL OR o.priority_id = ANY (f."priorityId"))
      AND (f."providerCompanyId" IS NULL OR o.provider_company_id = ANY (f."providerCompanyId"))
      AND (f."causeReasonId" IS NULL OR o.cause_reason_id = ANY (f."causeReasonId"))
      AND (
          f.search IS NULL
          OR o.order_mask ILIKE '%' || f.search || '%'
          OR o.unit_description ILIKE '%' || f.search || '%'
          OR EXISTS (
              SELECT 1 FROM public.units AS u
              WHERE u.id = o.unit_id
                AND u.description_full ILIKE '%' || f.search || '%'
          )
          OR o.type_description ILIKE '%' || f.search || '%'
          OR o.requested_services ILIKE '%' || f.search || '%'
      )
),
os_orders AS MATERIALIZED (
    SELECT
        o.status_id,
        o.asset_tag_id,
        o.asset_tag_description
    FROM source_orders AS o
    CROSS JOIN os_f AS f
    WHERE o.status_id NOT IN (7, 8)
      AND (
          (p_parent_view AND o.parent_id IS NULL AND o.status_id IN (2, 3, 4, 5, 6))
          OR (NOT p_parent_view AND o.parent_id IS NOT NULL)
      )
      AND (p_start_date IS NULL OR o.requested_at >= p_start_date::timestamp)
      AND (p_end_date IS NULL OR o.requested_at < (p_end_date + 1)::timestamp)
      AND (f."systemParentId" IS NULL OR o.system_parent_id = ANY (f."systemParentId"))
      AND (f."systemId" IS NULL OR o.system_id = ANY (f."systemId"))
      AND (f."unitTypeParentId" IS NULL OR o.unit_type_parent_id = ANY (f."unitTypeParentId"))
      AND (f."unitTypeId" IS NULL OR o.unit_type_id = ANY (f."unitTypeId"))
      AND (f."unitId" IS NULL OR o.unit_id = ANY (f."unitId"))
      AND (f."assetTagId" IS NULL OR o.asset_tag_id = ANY (f."assetTagId"))
      AND (f."orderObjectId" IS NULL OR o.object_id = ANY (f."orderObjectId"))
      AND (f."orderTypeId" IS NULL OR o.type_id = ANY (f."orderTypeId"))
      AND (f."orderTypeSubId" IS NULL OR o.type_sub_id = ANY (f."orderTypeSubId"))
      AND (f."contractId" IS NULL OR o.contract_id = ANY (f."contractId"))
      AND (f."orderPlanId" IS NULL OR o.plan_id = ANY (f."orderPlanId"))
      AND (f."orderTeamId" IS NULL OR o.requester_team_id = ANY (f."orderTeamId"))
      AND (f."responsibleTeamId" IS NULL OR o.team_id = ANY (f."responsibleTeamId"))
      AND (f."priorityId" IS NULL OR o.priority_id = ANY (f."priorityId"))
      AND (f."providerCompanyId" IS NULL OR o.provider_company_id = ANY (f."providerCompanyId"))
      AND (f."causeReasonId" IS NULL OR o.cause_reason_id = ANY (f."causeReasonId"))
      AND (
          f.search IS NULL
          OR o.order_mask ILIKE '%' || f.search || '%'
          OR o.unit_description ILIKE '%' || f.search || '%'
          OR EXISTS (
              SELECT 1 FROM public.units AS u
              WHERE u.id = o.unit_id
                AND u.description_full ILIKE '%' || f.search || '%'
          )
          OR o.type_description ILIKE '%' || f.search || '%'
          OR o.requested_services ILIKE '%' || f.search || '%'
      )
),
ss_counts AS (
    SELECT
        count(*) FILTER (WHERE requested_at >= c.today::timestamp) AS today,
        count(*) FILTER (WHERE requested_at >= (c.today - 1)::timestamp AND requested_at < c.today::timestamp) AS yesterday,
        count(*) FILTER (WHERE requested_at >= (c.today - 7)::timestamp AND requested_at < (c.today - 1)::timestamp) AS "sevenDays",
        count(*) FILTER (WHERE requested_at >= (c.today - 15)::timestamp AND requested_at < (c.today - 7)::timestamp) AS fifteenDays,
        count(*) FILTER (WHERE requested_at >= (c.today - 30)::timestamp AND requested_at < (c.today - 15)::timestamp) AS "between16And30",
        count(*) FILTER (WHERE requested_at < (c.today - 30)::timestamp) AS "moreThan30"
    FROM ss_orders
    CROSS JOIN clock AS c
),
ss_sectors AS (
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', sector_id,
                'label', label,
                'count', count
            ) ORDER BY label
        ),
        '[]'::jsonb
    ) AS data
    FROM (
        SELECT
            COALESCE(asset_tag_id::text, 'null') AS sector_id,
            COALESCE(asset_tag_description, 'Sem Setor') AS label,
            count(*) AS count
        FROM ss_orders
        CROSS JOIN clock AS c
        CROSS JOIN effective_ss_filters AS f
        WHERE CASE f.filters ->> 'period'
            WHEN 'Hoje' THEN requested_at >= c.today::timestamp
            WHEN 'Ontem' THEN requested_at >= (c.today - 1)::timestamp AND requested_at < c.today::timestamp
            WHEN '2-7 dias' THEN requested_at >= (c.today - 7)::timestamp AND requested_at < (c.today - 1)::timestamp
            WHEN '8-15 dias' THEN requested_at >= (c.today - 15)::timestamp AND requested_at < (c.today - 7)::timestamp
            WHEN '16-30 dias' THEN requested_at >= (c.today - 30)::timestamp AND requested_at < (c.today - 15)::timestamp
            WHEN '> 30 dias' THEN requested_at < (c.today - 30)::timestamp
            ELSE true
        END
        GROUP BY sector_id, label
    ) AS sectors
),
os_counts AS (
    SELECT COALESCE(jsonb_object_agg(status_id::text, count), '{}'::jsonb) AS data
    FROM (
        SELECT status_id, count(*) AS count
        FROM os_orders
        GROUP BY status_id
    ) AS counts
),
os_sectors AS (
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', sector_id,
                'label', label,
                'count', count
            ) ORDER BY count DESC
        ),
        '[]'::jsonb
    ) AS data
    FROM (
        SELECT
            COALESCE(o.asset_tag_id::text, 'null') AS sector_id,
            COALESCE(o.asset_tag_description, 'Sem Setor') AS label,
            count(*) AS count
        FROM os_orders AS o
        CROSS JOIN os_f AS f
        WHERE (f."statusId" IS NULL OR o.status_id = ANY (f."statusId"))
        GROUP BY sector_id, label
    ) AS sectors
)
SELECT jsonb_build_object(
    'ssCounts', (SELECT to_jsonb(ss_counts) FROM ss_counts),
    'osCounts', (SELECT data FROM os_counts),
    'ssSectorCounts', (SELECT data FROM ss_sectors),
    'osSectorCounts', (SELECT data FROM os_sectors)
);
$$;

--
-- Name: fn_orders_visits_dashboard_summary(jsonb, text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_orders_visits_dashboard_summary(p_filters jsonb DEFAULT '{}'::jsonb, p_start text DEFAULT NULL::text, p_end text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_selection text[] DEFAULT NULL::text[], p_is_all boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_today    date := (timezone('America/Sao_Paulo', now()))::date;
    v_start    timestamp;
    v_end      timestamp;
    v_search   text := NULLIF(btrim(COALESCE(p_search, '')), '');
    v_sel      text[] := COALESCE(p_selection, '{}'::text[]);
    v_stage_ids int[];
    v_cp       boolean;
    v_cr       boolean;
    v_approved boolean;
    v_result   jsonb;
BEGIN
    -- Mesmo formato do app: 'AAAA-MM-DD' (início 00:00:00, fim 23:59:59) ou já com hora.
    v_start := CASE
        WHEN NULLIF(p_start, '') IS NULL THEN date_trunc('month', v_today)::timestamp
        WHEN p_start ~ '[T ]' THEN replace(p_start, 'T', ' ')::timestamp
        ELSE (p_start || ' 00:00:00')::timestamp END;
    v_end := CASE
        WHEN NULLIF(p_end, '') IS NULL THEN ((date_trunc('month', v_today) + INTERVAL '1 month')::date - 1 || ' 23:59:59')::timestamp
        WHEN p_end ~ '[T ]' THEN replace(p_end, 'T', ' ')::timestamp
        ELSE (p_end || ' 23:59:59')::timestamp END;

    v_stage_ids := ARRAY(SELECT s::int FROM unnest(v_sel) s WHERE s ~ '^[0-9]+$');
    v_cp := 'costs-pending'  = ANY (v_sel);
    v_cr := 'costs-rejected' = ANY (v_sel);
    v_approved := '5' = ANY (v_sel);

    WITH f AS MATERIALIZED (
        SELECT
            public.fn_orders_dashboard_filter_ids(p_filters, 'contractId')        AS contract_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'systemParentId')    AS system_parent_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'systemId')          AS system_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'unitTypeParentId')  AS unit_type_parent_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'unitId')            AS unit_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'orderObjectId')     AS object_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'orderTypeId')       AS type_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'orderTypeSubId')    AS type_sub_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'assetTagId')        AS asset_tag_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'assetTagSubId')     AS asset_tag_sub_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'causeReasonId')     AS cause_reason_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'orderPlanId')       AS plan_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'orderTeamId')       AS order_team_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'responsibleTeamId') AS responsible_team_ids,
            public.fn_orders_dashboard_filter_ids(p_filters, 'providerCompanyId') AS provider_company_ids
    ),
    base AS MATERIALIZED (
        SELECT o.id,
               o.ov_processing_id                      AS proc,
               o.ov_costs_status                       AS costs,
               COALESCE(o.ov_total_value, 0)::numeric  AS total,
               o.o_plan_description                    AS plan_label,
               o.o_unit_description                    AS unit_label,
               o.ov_started_at
          FROM public.v_orders_visits o
          CROSS JOIN f
         WHERE (o.ov_started_at >= v_start OR (o.ov_started_at IS NULL AND o.o_requested_at >= v_start))
           AND (o.ov_started_at <= v_end   OR (o.ov_started_at IS NULL AND o.o_requested_at <= v_end))
           AND (f.contract_ids         IS NULL OR o.o_contract_id         = ANY (f.contract_ids))
           AND (f.system_parent_ids    IS NULL OR o.o_system_parent_id    = ANY (f.system_parent_ids))
           AND (f.system_ids           IS NULL OR o.o_system_id           = ANY (f.system_ids))
           AND (f.unit_type_parent_ids IS NULL OR o.o_unit_type_parent_id = ANY (f.unit_type_parent_ids))
           AND (f.unit_ids             IS NULL OR o.o_unit_id             = ANY (f.unit_ids))
           AND (f.object_ids           IS NULL OR o.o_object_id           = ANY (f.object_ids))
           AND (f.type_ids             IS NULL OR o.o_type_id             = ANY (f.type_ids))
           AND (f.type_sub_ids         IS NULL OR o.o_type_sub_id         = ANY (f.type_sub_ids))
           AND (f.asset_tag_ids        IS NULL OR o.o_asset_tag_id        = ANY (f.asset_tag_ids))
           AND (f.asset_tag_sub_ids    IS NULL OR o.o_asset_tag_sub_id    = ANY (f.asset_tag_sub_ids))
           AND (f.cause_reason_ids     IS NULL OR o.o_cause_reason_id     = ANY (f.cause_reason_ids))
           AND (f.plan_ids             IS NULL OR o.o_plan_id             = ANY (f.plan_ids))
           AND (f.order_team_ids       IS NULL OR o.o_team_id             = ANY (f.order_team_ids))
           AND (f.responsible_team_ids IS NULL OR o.o_team_id             = ANY (f.responsible_team_ids))
           AND (f.provider_company_ids IS NULL OR o.o_provider_company_id = ANY (f.provider_company_ids))
           AND (v_search IS NULL
                OR o.ov_mask                   ILIKE '%' || v_search || '%'
                OR o.o_unit_description        ILIKE '%' || v_search || '%'
                OR o.client_name               ILIKE '%' || v_search || '%'
                OR o.o_mask                    ILIKE '%' || v_search || '%'
                OR o.ov_team_leader_name_short ILIKE '%' || v_search || '%')
    ),
    sel AS MATERIALIZED (
        SELECT b.*
          FROM base b
         WHERE p_is_all
            OR b.proc = ANY (v_stage_ids)
            OR (v_cp AND b.proc = 5 AND (b.costs IS NULL OR b.costs IN ('pending', 'waiting')))
            OR (v_cr AND b.proc = 5 AND b.costs = 'rejected')
    ),
    appr AS (
        SELECT s.id
          FROM sel s
         WHERE CASE
                   WHEN v_approved THEN s.costs = 'approved'
                   WHEN v_cp       THEN s.costs IS NULL OR s.costs IN ('pending', 'waiting')
                   WHEN v_cr       THEN s.costs = 'rejected'
                   ELSE true
               END
    )
    SELECT jsonb_build_object(
        'all', (SELECT jsonb_build_object('count', count(*), 'total', COALESCE(sum(total), 0)) FROM base),
        'stages', COALESCE((
            SELECT jsonb_object_agg(proc::text, jsonb_build_object(
                       'count', cnt,
                       'total', tot))
              FROM (SELECT proc,
                           count(*) AS cnt,
                           COALESCE(sum(total) FILTER (WHERE proc <> 5 OR costs = 'approved'), 0) AS tot
                      FROM base WHERE proc IS NOT NULL GROUP BY proc) st
        ), '{}'::jsonb),
        'costsRejected', (SELECT jsonb_build_object('count', count(*), 'total', COALESCE(sum(total), 0))
                            FROM base WHERE proc = 5 AND costs = 'rejected'),
        'costsPending',  (SELECT jsonb_build_object('count', count(*), 'total', COALESCE(sum(total), 0))
                            FROM base WHERE proc = 5 AND (costs IS NULL OR costs IN ('pending', 'waiting'))),
        'selection', (SELECT jsonb_build_object('count', count(*)) FROM sel),
        'composition', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('label', label, 'value', value) ORDER BY value DESC, label)
              FROM (SELECT COALESCE(NULLIF(plan_label, ''), 'Sem Plano') AS label, sum(total) AS value
                      FROM sel GROUP BY 1) c
        ), '[]'::jsonb),
        'trend', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('day', day, 'count', cnt) ORDER BY day)
              FROM (SELECT ov_started_at::date AS day, count(*) AS cnt
                      FROM sel WHERE ov_started_at IS NOT NULL
                     GROUP BY 1 ORDER BY 1 DESC LIMIT 10) t
        ), '[]'::jsonb),
        'units', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('label', label, 'value', value) ORDER BY value DESC, label)
              FROM (SELECT COALESCE(NULLIF(unit_label, ''), 'Sem Unidade') AS label, sum(total) AS value
                      FROM sel GROUP BY 1) u
        ), '[]'::jsonb),
        'appropriationIds', COALESCE((SELECT jsonb_agg(id ORDER BY id) FROM appr), '[]'::jsonb)
    )
      INTO v_result;

    RETURN v_result;
END;
$_$;

--
-- Name: FUNCTION fn_orders_visits_dashboard_summary(p_filters jsonb, p_start text, p_end text, p_search text, p_selection text[], p_is_all boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_orders_visits_dashboard_summary(p_filters jsonb, p_start text, p_end text, p_search text, p_selection text[], p_is_all boolean) IS 'Gestão > Visitas: contadores, totais, gráficos e ids de apropriação sobre v_orders_visits (período/filtros/busca/seleção de etapas).';

--
-- Name: fn_sync_units_clients_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_units_clients_ids() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Web antiga pode serializar a linha inteira e mandar NULL; normaliza
    IF NEW.clients_ids IS NULL THEN
      NEW.clients_ids := '{}'::bigint[];
    END IF;

    -- Multi-cliente desligado nas Fases 1A/1B (remover na Fase 1D, após o Gate 4)
    IF cardinality(NEW.clients_ids) > 1 THEN
      RAISE EXCEPTION 'Multi-cliente desligado nesta fase (Fase 1A/1B)';
    END IF;

    IF NEW.client_id IS NOT NULL THEN
      -- Web antiga manda no escalar; app novo deve mandar somente o array
      NEW.clients_ids := ARRAY[NEW.client_id]::bigint[];
    ELSIF cardinality(NEW.clients_ids) > 0 THEN
      NEW.client_id := NEW.clients_ids[1];
    END IF;

    RETURN NEW;
  END IF;

  -- UPDATE
  -- Web antiga pode mandar clients_ids NULL ao serializar a linha inteira;
  -- preservar o array atual evita quebrar o fluxo legado.
  IF NEW.clients_ids IS NULL THEN
    NEW.clients_ids := OLD.clients_ids;
  END IF;

  IF NEW.client_id IS DISTINCT FROM OLD.client_id
     AND cardinality(OLD.clients_ids) > 1
     AND NEW.clients_ids IS NOT DISTINCT FROM OLD.clients_ids THEN
    RAISE EXCEPTION 'Unidade % tem múltiplos clientes; edite na versão nova', OLD.id;
  END IF;

  IF cardinality(NEW.clients_ids) > 1 THEN
    RAISE EXCEPTION 'Multi-cliente desligado nesta fase (Fase 1A/1B)';
  END IF;

  IF NEW.client_id IS DISTINCT FROM OLD.client_id THEN
    -- Escrita da web antiga (ou de fluxo legado que ainda usa o escalar)
    NEW.clients_ids := CASE
      WHEN NEW.client_id IS NULL THEN '{}'::bigint[]
      ELSE ARRAY[NEW.client_id]::bigint[]
    END;
  ELSIF NEW.clients_ids IS DISTINCT FROM OLD.clients_ids THEN
    -- Escrita do app novo (somente array)
    NEW.client_id := CASE
      WHEN cardinality(NEW.clients_ids) > 0 THEN NEW.clients_ids[1]
      ELSE NULL
    END;
  END IF;

  RETURN NEW;
END;
$$;

--
-- Name: fn_touch_assets_available_integration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_touch_assets_available_integration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    NEW.updated_at := timezone('America/Sao_Paulo', now());
    RETURN NEW;
END;
$$;

--
-- Name: fn_tracker_issue_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tracker_issue_token(p_device_id text, p_device_info text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_token TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '28000';
    END IF;
    IF p_device_id IS NULL OR length(p_device_id) NOT BETWEEN 8 AND 100 THEN
        RAISE EXCEPTION 'device_id inválido' USING ERRCODE = '22023';
    END IF;

    SELECT u.id INTO v_user_id
      FROM public.users u
     WHERE u.uuid = auth.uid()
     LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não encontrado' USING ERRCODE = '28000';
    END IF;

    UPDATE public.users_tracker_tokens
       SET revoked_at = timezone('America/Sao_Paulo', now())
     WHERE user_id = v_user_id
       AND device_id = p_device_id
       AND revoked_at IS NULL;

    -- 256 bits aleatórios (gen_random_uuid usa o CSPRNG do Postgres).
    v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');

    INSERT INTO public.users_tracker_tokens (user_id, token_hash, device_id, device_info)
    VALUES (
        v_user_id,
        encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
        p_device_id,
        left(p_device_info, 300)
    );

    RETURN v_token;
END;
$$;

--
-- Name: fn_tracker_report_location(text, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tracker_report_location(p_token text, p_latitude double precision, p_longitude double precision, p_accuracy double precision DEFAULT NULL::double precision) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_token_id BIGINT;
    v_user_id BIGINT;
    v_is_available BOOLEAN;
    v_in_visit BOOLEAN;
    v_now TIMESTAMP WITHOUT TIME ZONE := timezone('America/Sao_Paulo', now());
BEGIN
    IF p_token IS NULL OR length(p_token) <> 64 THEN
        RETURN 'invalid';
    END IF;

    SELECT t.id, t.user_id INTO v_token_id, v_user_id
      FROM public.users_tracker_tokens t
     WHERE t.token_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex')
       AND t.revoked_at IS NULL
     LIMIT 1;
    IF v_token_id IS NULL THEN
        RETURN 'invalid';
    END IF;

    IF p_latitude IS NULL OR p_longitude IS NULL
       OR p_latitude NOT BETWEEN -90 AND 90
       OR p_longitude NOT BETWEEN -180 AND 180
       OR (p_latitude = 0 AND p_longitude = 0) THEN
        RETURN 'rejected';
    END IF;

    -- Mesma regra do app (useLocationTracker/App.tsx): visita aberta =
    -- is_ov_in_progress OU ov_id_in_progress > 0.
    SELECT COALESCE(u.is_available, false),
           COALESCE(u.is_ov_in_progress, false) OR COALESCE(u.ov_id_in_progress, 0) > 0
      INTO v_is_available, v_in_visit
      FROM public.users u
     WHERE u.id = v_user_id;

    UPDATE public.users_tracker_tokens SET last_used_at = v_now WHERE id = v_token_id;

    -- Regra de rastreamento (LGPD): só enquanto disponível ou em visita.
    IF NOT (v_is_available OR v_in_visit) THEN
        RETURN 'paused';
    END IF;

    UPDATE public.users
       SET latitude = p_latitude,
           longitude = p_longitude,
           tracker_accuracy = CASE
               WHEN p_accuracy IS NULL OR p_accuracy < 0 THEN tracker_accuracy
               ELSE p_accuracy
           END,
           tracker_heartbeat_at = v_now,
           tracked_at = v_now
     WHERE id = v_user_id;

    RETURN 'ok';
END;
$$;

--
-- Name: fn_tracker_revoke_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tracker_revoke_token(p_device_id text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    UPDATE public.users_tracker_tokens t
       SET revoked_at = timezone('America/Sao_Paulo', now())
      FROM public.users u
     WHERE u.id = t.user_id
       AND u.uuid = auth.uid()
       AND t.device_id = p_device_id
       AND t.revoked_at IS NULL;
$$;

--
-- Name: fn_users_caller(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_caller() RETURNS TABLE(user_id bigint, is_admin boolean, is_admin_super boolean, can_manage_peers boolean, company_id bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT u.id,
           COALESCE(u.is_admin, false),
           COALESCE(u.is_admin_super, false),
           COALESCE(u.is_team_leader, false)
             OR COALESCE(u.is_ov_in_progress, false)
             OR COALESCE(u.ov_id_in_progress, 0) > 0,
           COALESCE(t.company_id, u.company_id)
      FROM public.users u
      LEFT JOIN public.cfg_teams t ON t.id = u.team_id
     WHERE u.uuid = auth.uid()
     LIMIT 1;
$$;

--
-- Name: fn_users_can_write(uuid, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_can_write(p_uuid uuid, p_email text, p_team_id bigint, p_company_id bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller         RECORD;
    v_target_company BIGINT;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN false;
    END IF;

    -- a) própria linha
    IF p_uuid = auth.uid()
       OR (p_email IS NOT NULL AND lower(p_email) = lower(COALESCE(auth.jwt() ->> 'email', ''))) THEN
        RETURN true;
    END IF;

    SELECT * INTO v_caller FROM public.fn_users_caller();
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    -- b) admin
    IF v_caller.is_admin OR v_caller.is_admin_super THEN
        RETURN true;
    END IF;

    -- c) líder / visita em andamento, mesma empresa
    IF v_caller.can_manage_peers THEN
        SELECT COALESCE(t.company_id, p_company_id) INTO v_target_company
          FROM (SELECT 1) x
          LEFT JOIN public.cfg_teams t ON t.id = p_team_id;
        IF v_target_company IS NULL THEN
            RETURN true;  -- sem equipe e sem empresa
        END IF;
        RETURN v_caller.company_id IS NOT NULL AND v_target_company = v_caller.company_id;
    END IF;

    RETURN false;
END;
$$;

--
-- Name: fn_users_cancel_account_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_cancel_account_deletion() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
BEGIN
    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    UPDATE public.users_account_deletion_requests
       SET status = 'cancelled',
           cancelled_at = timezone('America/Sao_Paulo', now())
     WHERE user_id = v_user_id AND status = 'pending';
END;
$$;

--
-- Name: users_account_deletion_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users_account_deletion_requests (
    id bigint NOT NULL,
    user_id bigint NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    reason text,
    requested_at timestamp without time zone DEFAULT timezone('America/Sao_Paulo'::text, now()) NOT NULL,
    cancelled_at timestamp without time zone,
    processed_at timestamp without time zone,
    processed_user_id bigint,
    processed_notes text,
    CONSTRAINT users_account_deletion_requests_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'cancelled'::character varying, 'done'::character varying])::text[])))
);

--
-- Name: TABLE users_account_deletion_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.users_account_deletion_requests IS 'Pedidos de exclusão de conta feitos pelo próprio usuário (Perfil > Excluir conta).';

--
-- Name: fn_users_request_account_deletion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_request_account_deletion(p_reason text DEFAULT NULL::text) RETURNS public.users_account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_row     public.users_account_deletion_requests;
BEGIN
    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_row
      FROM public.users_account_deletion_requests
     WHERE user_id = v_user_id AND status = 'pending'
     LIMIT 1;
    IF FOUND THEN
        RETURN v_row;
    END IF;

    INSERT INTO public.users_account_deletion_requests (user_id, reason)
    VALUES (v_user_id, NULLIF(btrim(COALESCE(p_reason, '')), ''))
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$$;

--
-- Name: fn_users_sync_position_to_tracker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_sync_position_to_tracker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_new_at TIMESTAMP WITHOUT TIME ZONE := COALESCE(NEW.tracker_heartbeat_at, NEW.tracked_at);
BEGIN
    IF NEW.latitude IS NULL OR NEW.longitude IS NULL OR v_new_at IS NULL THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.users_tracker AS t
           (user_id, latitude, longitude, tracker_accuracy, tracked_at, tracker_heartbeat_at)
    VALUES (NEW.id, NEW.latitude, NEW.longitude, NEW.tracker_accuracy,
            COALESCE(NEW.tracked_at, v_new_at), v_new_at)
    ON CONFLICT (user_id) DO UPDATE
       SET latitude             = EXCLUDED.latitude,
           longitude            = EXCLUDED.longitude,
           tracker_accuracy     = COALESCE(EXCLUDED.tracker_accuracy, t.tracker_accuracy),
           tracked_at           = EXCLUDED.tracked_at,
           tracker_heartbeat_at = EXCLUDED.tracker_heartbeat_at
     WHERE t.tracker_heartbeat_at IS NULL
        OR EXCLUDED.tracker_heartbeat_at > t.tracker_heartbeat_at;

    RETURN NEW;
END;
$$;

--
-- Name: fn_users_tracker_report_session(double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_users_tracker_report_session(p_latitude double precision, p_longitude double precision, p_accuracy double precision DEFAULT NULL::double precision) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_is_available BOOLEAN;
    v_in_visit BOOLEAN;
    v_now TIMESTAMP WITHOUT TIME ZONE := timezone('America/Sao_Paulo', now());
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN 'invalid';
    END IF;

    SELECT u.id,
           COALESCE(u.is_available, false),
           COALESCE(u.is_ov_in_progress, false) OR COALESCE(u.ov_id_in_progress, 0) > 0
      INTO v_user_id, v_is_available, v_in_visit
      FROM public.users u
     WHERE u.uuid = auth.uid()
     LIMIT 1;
    IF v_user_id IS NULL THEN
        RETURN 'invalid';
    END IF;

    IF p_latitude IS NULL OR p_longitude IS NULL
       OR p_latitude NOT BETWEEN -90 AND 90
       OR p_longitude NOT BETWEEN -180 AND 180
       OR (p_latitude = 0 AND p_longitude = 0) THEN
        RETURN 'rejected';
    END IF;

    IF NOT (v_is_available OR v_in_visit) THEN
        RETURN 'paused';
    END IF;

    INSERT INTO public.users_tracker AS t
           (user_id, latitude, longitude, tracker_accuracy, tracked_at, tracker_heartbeat_at)
    VALUES (v_user_id, p_latitude, p_longitude,
            CASE WHEN p_accuracy IS NULL OR p_accuracy < 0 THEN NULL ELSE p_accuracy END,
            v_now, v_now)
    ON CONFLICT (user_id) DO UPDATE
       SET latitude = EXCLUDED.latitude,
           longitude = EXCLUDED.longitude,
           tracker_accuracy = COALESCE(EXCLUDED.tracker_accuracy, t.tracker_accuracy),
           tracked_at = EXCLUDED.tracked_at,
           tracker_heartbeat_at = EXCLUDED.tracker_heartbeat_at;

    RETURN 'ok';
END;
$$;

--
-- Name: fn_validate_assets_available_integration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_assets_available_integration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
    IF NEW.config IS NULL THEN
        NEW.config := '{}'::jsonb;
    END IF;

    IF jsonb_typeof(NEW.config) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'config da integração deve ser um objeto JSON'
            USING ERRCODE = '22023';
    END IF;

    -- Segredo nunca na configuração: vai para Credentials do n8n/secret manager.
    IF public.fn_jsonb_contains_forbidden_keys(
        NEW.config,
        ARRAY[
            'api_key', 'apikey', 'api_secret', 'password', 'token',
            'access_token', 'refresh_token', 'secret', 'client_secret',
            'authorization', 'auth_header', 'bearer'
        ]
    ) THEN
        RAISE EXCEPTION 'config não pode conter credenciais; use as Credentials do n8n/secret manager'
            USING ERRCODE = '22023';
    END IF;

    IF NEW.config ? 'status_path' THEN
        IF jsonb_typeof(NEW.config -> 'status_path') IS DISTINCT FROM 'string'
           OR btrim(NEW.config ->> 'status_path') = '' THEN
            RAISE EXCEPTION 'status_path deve ser um caminho não vazio'
                USING ERRCODE = '22023';
        END IF;
    END IF;

    IF NEW.config ? 'status_map' THEN
        IF jsonb_typeof(NEW.config -> 'status_map') IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'status_map deve ser um objeto'
                USING ERRCODE = '22023';
        END IF;

        IF NOT (NEW.config ? 'status_path') THEN
            RAISE EXCEPTION 'status_map exige status_path'
                USING ERRCODE = '22023';
        END IF;

        IF NOT EXISTS (
            SELECT 1 FROM jsonb_object_keys(NEW.config -> 'status_map')
        ) THEN
            RAISE EXCEPTION 'status_map não pode ser vazio'
                USING ERRCODE = '22023';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM jsonb_each(NEW.config -> 'status_map') AS e(key, value)
            WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'boolean'
        ) THEN
            RAISE EXCEPTION 'status_map deve mapear valores externos para booleanos'
                USING ERRCODE = '22023';
        END IF;
    END IF;

    IF NEW.config ? 'reason_map' THEN
        IF jsonb_typeof(NEW.config -> 'reason_map') IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'reason_map deve ser um objeto'
                USING ERRCODE = '22023';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM jsonb_each(NEW.config -> 'reason_map') AS e(key, value)
            WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'number'
               OR (e.value #>> '{}') !~ '^[0-9]{1,10}$'
               OR (e.value #>> '{}')::BIGINT > 2147483647
        ) THEN
            RAISE EXCEPTION 'reason_map deve mapear códigos externos para IDs internos inteiros'
                USING ERRCODE = '22023';
        END IF;
    END IF;

    IF NEW.config ? 'require_reason'
       AND jsonb_typeof(NEW.config -> 'require_reason') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'require_reason deve ser booleano'
            USING ERRCODE = '22023';
    END IF;

    RETURN NEW;
END;
$_$;

--
-- Name: fn_validate_department_clients_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_department_clients_ids() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  invalid_ids bigint[];
BEGIN
  -- Normalização defensiva (mesmo padrão do fn_sync_units_clients_ids)
  IF TG_OP = 'INSERT' THEN
    IF NEW.clients_ids IS NULL THEN
      NEW.clients_ids := '{}'::bigint[];
    END IF;
  ELSE
    IF NEW.clients_ids IS NULL THEN
      NEW.clients_ids := OLD.clients_ids;
    END IF;
  END IF;

  -- Bloquear NULL dentro do array (erro explícito em vez de violação genérica)
  IF array_position(NEW.clients_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'clients_ids não pode conter NULL dentro do array (depto %)', NEW.id;
  END IF;

  -- Deduplicar e ordenar (mantém comparação determinística)
  SELECT array_agg(DISTINCT x ORDER BY x)
  INTO NEW.clients_ids
  FROM unnest(NEW.clients_ids) AS x;

  -- Validar existência dos ids em clients
  SELECT array_agg(x)
  INTO invalid_ids
  FROM unnest(NEW.clients_ids) AS x
  LEFT JOIN public.clients c ON c.id = x
  WHERE c.id IS NULL;

  IF invalid_ids IS NOT NULL THEN
    RAISE EXCEPTION 'clients_ids contém ids inexistentes em clients: %', invalid_ids;
  END IF;

  RETURN NEW;
END;
$$;

--
-- Name: generate_impersonation_link(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_impersonation_link(p_target_user_id bigint, p_redirect_to text DEFAULT NULL::text, p_service_role_key text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uuid UUID;
    v_email TEXT;
    v_temp_password TEXT;
    v_original_password TEXT;
BEGIN
    -- Get user info from public.users
    SELECT u.uuid, u.email INTO v_uuid, v_email
    FROM public.users u
    WHERE u.id = p_target_user_id;

    IF v_uuid IS NULL THEN
        RETURN json_build_object('error', 'User not found');
    END IF;

    IF v_email IS NULL THEN
        RETURN json_build_object('error', 'User has no email');
    END IF;

    -- Save original password hash before overwriting
    SELECT encrypted_password INTO v_original_password
    FROM auth.users
    WHERE id = v_uuid;

    IF v_original_password IS NOT NULL THEN
        -- Upsert: only save if no pending restore (restored_at IS NULL)
        INSERT INTO public.impersonation_password_backup
            (user_uuid, user_email, original_encrypted_password)
        VALUES
            (v_uuid, v_email, v_original_password)
        ON CONFLICT DO NOTHING;
    END IF;

    -- Generate a random temp password (24 chars)
    v_temp_password := encode(gen_random_bytes(18), 'hex');

    -- Update the user's password in auth.users
    UPDATE auth.users
    SET encrypted_password = crypt(v_temp_password, gen_salt('bf')),
        updated_at = now()
    WHERE id = v_uuid;

    IF NOT FOUND THEN
        RETURN json_build_object('error', 'User not found in auth.users');
    END IF;

    -- Return email and temp password for frontend login
    RETURN json_build_object(
        'email', v_email,
        'password', v_temp_password,
        'uuid', v_uuid
    );
END;
$$;

--
-- Name: get_audit_table_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_table_config() RETURNS TABLE(table_name text, is_enabled boolean, table_exists boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.users u
        WHERE u.uuid = auth.uid()
          AND u.is_admin_super IS TRUE
    ) THEN
        RAISE EXCEPTION 'Apenas o super admin pode consultar a configuração de auditoria'
            USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT c.table_name,
           EXISTS (
               SELECT 1
               FROM pg_trigger tr
               WHERE tr.tgrelid = to_regclass(format('%I.%I', 'public', c.table_name))
                 AND tr.tgname = 'trg_audit_' || c.table_name
                 AND NOT tr.tgisinternal
           ),
           to_regclass(format('%I.%I', 'public', c.table_name)) IS NOT NULL
    FROM public.cfg_audits_tables c
    ORDER BY c.table_name;
END;
$$;

--
-- Name: FUNCTION get_audit_table_config(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_audit_table_config() IS 'Lista tabelas de auditoria gerenciáveis; acesso exclusivo a super admins.';

--
-- Name: get_team_shifts_calendar(date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_shifts_calendar(p_reference_month date, p_department_id bigint) RETURNS TABLE(team_id bigint, shift_date date, shift_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id BIGINT;
    v_is_admin_super BOOLEAN;
BEGIN
    SELECT u.id, u.is_admin_super
      INTO v_user_id, v_is_admin_super
      FROM public.users u
     WHERE u.uuid = auth.uid();

    IF v_user_id IS NULL
       OR (
           v_is_admin_super IS NOT TRUE
           AND NOT EXISTS (
               SELECT 1
                 FROM public.cfg_profiles_access pa
                 JOIN public.cfg_routes r ON r.id = pa.route_id
                 JOIN public.users u ON u.profile_id = pa.profile_id
                WHERE u.id = v_user_id
                  AND r.route_key = 'dashboard_teams_shifts_calendar'
                  AND r.is_available IS TRUE
                  AND pa.can_view IS TRUE
           )
       ) THEN
        RAISE EXCEPTION 'Você não tem permissão para consultar o calendário de turnos'
            USING ERRCODE = '42501';
    END IF;

    IF p_reference_month IS NULL
       OR p_reference_month <> date_trunc('month', p_reference_month)::date
       OR p_department_id IS NULL THEN
        RAISE EXCEPTION 'Informe o primeiro dia do mês e um departamento válido'
            USING ERRCODE = '22023';
    END IF;

    RETURN QUERY
    SELECT c.team_id, c.shift_date, c.shift_type
      FROM public.teams_shifts_calendar c
      JOIN public.cfg_teams t ON t.id = c.team_id
     WHERE t.department_id = p_department_id
       AND t.is_evaluable IS TRUE
       AND c.shift_date >= p_reference_month
       AND c.shift_date < (p_reference_month + INTERVAL '1 month')::date
     ORDER BY c.shift_date, c.team_id;
END;
$$;

--
-- Name: get_unit_asset_tag_cascade_info(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unit_asset_tag_cascade_info(p_node_id bigint) RETURNS TABLE(under_cascade boolean, cascade_root_name text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_under boolean := FALSE;
    v_root_name text := NULL;
    v_parent_count integer := 0;
    v_cascade_driven_count integer := 0;
BEGIN
    BEGIN
        SELECT count(*), count(*) FILTER (WHERE pr.cascade_parent_id IS NOT NULL)
        INTO v_parent_count, v_cascade_driven_count
        FROM (
            SELECT n.parent_id AS pid
            FROM public.cfg_units_assets_tags n
            WHERE n.id = p_node_id AND n.parent_id IS NOT NULL
            UNION
            SELECT l.parent_id
            FROM public.cfg_units_assets_tags_links l
            WHERE l.unit_asset_tag_id = p_node_id
        ) par
        JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid;
    EXCEPTION WHEN undefined_object THEN
        v_parent_count := 0;
        v_cascade_driven_count := 0;
    END;

    -- (a) Todos os pais cascade-driven
    v_under := (v_parent_count > 0 AND v_cascade_driven_count = v_parent_count);

    -- (b) O próprio nó está forçado
    IF NOT v_under THEN
        SELECT COALESCE(n.cascade_parent_id IS NOT NULL AND n.cascade_parent_id <> n.id, FALSE)
        INTO v_under
        FROM public.cfg_units_assets_tags n
        WHERE n.id = p_node_id;
        v_under := COALESCE(v_under, FALSE);
    END IF;

    IF v_under THEN
        -- Raiz preferencial: o nó forçado aponta para a raiz de sua cascata
        SELECT r.asset_tag_tag_sub_description INTO v_root_name
        FROM public.cfg_units_assets_tags n
        JOIN public.cfg_units_assets_tags r ON r.id = n.cascade_parent_id
        WHERE n.id = p_node_id
          AND n.cascade_parent_id IS NOT NULL AND n.cascade_parent_id <> n.id
        LIMIT 1;

        -- Fallback: raiz via pai cascade-driven
        IF v_root_name IS NULL THEN
            SELECT r.asset_tag_tag_sub_description INTO v_root_name
            FROM (
                SELECT n.parent_id AS pid
                FROM public.cfg_units_assets_tags n
                WHERE n.id = p_node_id AND n.parent_id IS NOT NULL
                UNION
                SELECT l.parent_id
                FROM public.cfg_units_assets_tags_links l
                WHERE l.unit_asset_tag_id = p_node_id
            ) par
            JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid
            JOIN public.cfg_units_assets_tags r ON r.id = pr.cascade_parent_id
            WHERE pr.cascade_parent_id IS NOT NULL
            LIMIT 1;
        END IF;
    END IF;

    RETURN QUERY SELECT v_under, v_root_name;
END;
$$;

--
-- Name: get_users_within_distance(double precision, double precision, double precision, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_users_within_distance(user_lat double precision, user_lon double precision, max_dist_km double precision, min_age integer, max_age integer) RETURNS SETOF public.users
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT *
  FROM users
  WHERE
    (6371 * acos(
      cos(radians(user_lat)) * cos(radians(latitude)) *
      cos(radians(longitude) - radians(user_lon)) +
      sin(radians(user_lat)) * sin(radians(latitude))
    )) <= max_dist_km
    AND age >= min_age
    AND age <= max_age;
END;
$$;

--
-- Name: handle_followers_orders_status_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_followers_orders_status_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_follower      RECORD;
    v_order         RECORD;
    v_user_name     TEXT;
    v_body          TEXT;
    v_timestamp     TEXT;
BEGIN
    -- Condição: só processa se o status_id mudou OU se é re-agendamento (status 4)
    IF OLD.status_id IS NOT DISTINCT FROM NEW.status_id AND NEW.status_id != 4 THEN
        RETURN NEW;
    END IF;

    -- Timestamp formatado no fuso horário de Brasília
    v_timestamp := TO_CHAR(
        TIMEZONE('America/Sao_Paulo', CURRENT_TIMESTAMP),
        'DD/MM/YYYY HH24:MI'
    );

    -- Buscar detalhes da OS (cliente, unidade, serviços)
    SELECT
        o.order_mask,
        o.requested_services,
        c.name              AS client_name,
        u.description_full  AS unit_description,
        s.description       AS status_description
    INTO v_order
    FROM public.orders o
    LEFT JOIN public.clients       c ON c.id = o.client_id
    LEFT JOIN public.units         u ON u.id = o.unit_id
    LEFT JOIN public.cfg_orders_statuses s ON s.id = NEW.status_id
    WHERE o.id = NEW.id;

    -- Buscar o nome curto do líder da equipe (com tratamento de erro)
    v_user_name := 'N/A';
    BEGIN
        SELECT name_short
        INTO v_user_name
        FROM public.users
        WHERE id = NEW.team_leader_id;
    EXCEPTION WHEN OTHERS THEN
        v_user_name := 'N/A';
    END;

    IF v_user_name IS NULL OR v_user_name = '' THEN
        v_user_name := 'N/A';
    END IF;

    -- Iterar sobre cada seguidor da OS
    FOR v_follower IN
        SELECT
            f.user_id,
            u.mobile_whatsapp
        FROM public.orders_followers f
        JOIN public.users u ON u.id = f.user_id
        WHERE f.o_id = NEW.id
    LOOP
        -- Montar o corpo da notificação
        v_body :=
            'Atualização Situação OS ' || COALESCE(v_order.order_mask, '') || chr(10) ||
            'Cliente: '    || COALESCE(v_order.client_name, 'N/A')     || chr(10) ||
            'Unidade: '    || COALESCE(v_order.unit_description, 'N/A') || chr(10) ||
            'Serviços: '   || COALESCE(v_order.requested_services, 'N/A') || chr(10) ||
            'Situação: '   || COALESCE(v_order.status_description, 'N/A') || chr(10) ||
            'Data hora: '  || v_timestamp                               || chr(10) ||
            'Líder: '      || v_user_name;

        -- Inserir notificação para o seguidor (evitar duplicidade)
        IF NOT EXISTS (
            SELECT 1 FROM public.users_notifications
            WHERE user_id_to = v_follower.user_id
            AND o_id = NEW.id
            AND type = 'order_status_change'
            AND created_at >= TIMEZONE('America/Sao_Paulo', CURRENT_TIMESTAMP) - INTERVAL '10 seconds'
        ) THEN
            INSERT INTO public.users_notifications (
                user_id_to,
                user_id_from,
                title,
                body,
                type,
                user_to_whatsapp,
                o_id,
                created_at,
                is_read
            ) VALUES (
                v_follower.user_id,
                NEW.updated_user_id,
                'Atualização Situação OS ' || COALESCE(v_order.order_mask, ''),
                v_body,
                'order_status_change',
                v_follower.mobile_whatsapp,
                NEW.id,
                TIMEZONE('America/Sao_Paulo', CURRENT_TIMESTAMP),
                FALSE
            );
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;

--
-- Name: FUNCTION handle_followers_orders_status_changed(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_followers_orders_status_changed() IS 'Flow: followers-orders-status-changed v1.4.0 — Notifica os seguidores de uma OS quando sua situação é alterada. Dispara após UPDATE em orders.status_id.';

