--
-- Name: increment_notice_view_count(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_notice_view_count(p_notice_id integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_count INTEGER;
BEGIN
    UPDATE public.cfg_app_notices
       SET view_count = COALESCE(view_count, 0) + 1
     WHERE id = p_notice_id
       AND is_active = TRUE
    RETURNING view_count INTO v_new_count;

    -- Aviso inexistente/inativo: retorna 0 sem erro
    RETURN COALESCE(v_new_count, 0);
END;
$$;

--
-- Name: match_documents(extensions.vector, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_documents(query_embedding extensions.vector, match_count integer DEFAULT NULL::integer, filter jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id bigint, content text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
begin
  return query
  select
    id,
    content,
    metadata,
    1 - (documents.embedding <=> query_embedding) as similarity
  from documents
  where metadata @> filter
  order by documents.embedding <=> query_embedding
  limit match_count;
end;
$$;

--
-- Name: match_knowledge(extensions.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_knowledge(query_embedding extensions.vector, match_threshold double precision, match_count integer) RETURNS TABLE(id uuid, content text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    k.id,
    k.content,
    k.metadata,
    1 - (k.embedding <=> query_embedding) AS similarity
  FROM ai_knowledge k
  WHERE 1 - (k.embedding <=> query_embedding) > match_threshold
  ORDER BY similarity DESC
  LIMIT match_count;
END;
$$;

--
-- Name: nearby_units(double precision, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nearby_units(user_lat double precision, user_lng double precision, radius_meters double precision DEFAULT 5000, status_filter text DEFAULT 'all'::text) RETURNS TABLE(id bigint, client_id bigint, description text, code text, installation_code_power_supply text, address_full text, latitude double precision, longitude double precision, unit_type_parent_id bigint, unit_type_id bigint, system_parent_id bigint, system_id bigint, status_id bigint, is_available boolean, description_full text, img_file_path text, img_file_name text, distance_meters double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id,
        u.client_id,
        u.description,
        u.code,
        u.installation_code_power_supply,
        u.address_full,
        u.latitude,
        u.longitude,
        u.unit_type_parent_id,
        u.unit_type_id,
        u.system_parent_id,
        u.system_id,
        u.status_id,
        u.is_available,
        u.description_full,
        u.img_file_path,
        u.img_file_name,
        (
            6371000 * ACOS(
                COS(RADIANS(user_lat)) * COS(RADIANS(u.latitude)) *
                COS(RADIANS(u.longitude) - RADIANS(user_lng)) +
                SIN(RADIANS(user_lat)) * SIN(RADIANS(u.latitude))
            )
        )::DOUBLE PRECISION AS distance_meters
    FROM public.units u
    WHERE u.latitude IS NOT NULL
      AND u.longitude IS NOT NULL
      AND u.is_deleted = 'false'
      AND u.latitude BETWEEN user_lat - (radius_meters / 111320) AND user_lat + (radius_meters / 111320)
      AND u.longitude BETWEEN user_lng - (radius_meters / (111320 * COS(RADIANS(user_lat)))) AND user_lng + (radius_meters / (111320 * COS(RADIANS(user_lat))))
      AND (
          status_filter = 'all'
          OR (status_filter = 'active' AND u.is_available = true)
          OR (status_filter = 'inactive' AND u.is_available = false)
      )
    HAVING (
        6371000 * ACOS(
            COS(RADIANS(user_lat)) * COS(RADIANS(u.latitude)) *
            COS(RADIANS(u.longitude) - RADIANS(user_lng)) +
            SIN(RADIANS(user_lat)) * SIN(RADIANS(u.latitude))
        )
    ) <= radius_meters
    ORDER BY distance_meters ASC;
END;
$$;

--
-- Name: ov_asset_lock(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ov_asset_lock(p_ova_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_now     TIMESTAMP := timezone('America/Sao_Paulo', now());
    v_user_id BIGINT;
    v_row     RECORD;
    v_holder  RECORD;
BEGIN
    SELECT u.id INTO v_user_id FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    UPDATE public.orders_visits_assets a
       SET locked_user_id = v_user_id,
           locked_at      = CASE WHEN a.locked_user_id = v_user_id THEN a.locked_at ELSE v_now END,
           lock_token     = CASE WHEN a.locked_user_id = v_user_id AND a.lock_token IS NOT NULL
                                 THEN a.lock_token ELSE gen_random_uuid() END
     WHERE a.id = p_ova_id
       AND (a.locked_user_id IS NULL OR a.locked_user_id = v_user_id)
    RETURNING a.locked_user_id, a.locked_at, a.lock_token INTO v_row;

    IF FOUND THEN
        RETURN jsonb_build_object(
            'locked', true,
            'locked_user_id', v_row.locked_user_id,
            'locked_at', v_row.locked_at,
            'lock_token', v_row.lock_token
        );
    END IF;

    -- Não travou: ou o ativo não existe/sem acesso, ou é de outro técnico.
    SELECT a.locked_user_id, a.locked_at,
           COALESCE(NULLIF(u.name_short, ''), u.name_full) AS holder_name
      INTO v_holder
      FROM public.orders_visits_assets a
      LEFT JOIN public.users u ON u.id = a.locked_user_id
     WHERE a.id = p_ova_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ativo da visita % não encontrado ou sem permissão.', p_ova_id
            USING ERRCODE = 'P0002';
    END IF;

    RETURN jsonb_build_object(
        'locked', false,
        'locked_user_id', v_holder.locked_user_id,
        'locked_user_name', v_holder.holder_name,
        'locked_at', v_holder.locked_at
    );
END;
$$;

--
-- Name: FUNCTION ov_asset_lock(p_ova_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ov_asset_lock(p_ova_id bigint) IS 'Modo offline: pega/renova a trava do relatório do ativo para o usuário atual. SECURITY INVOKER.';

--
-- Name: ov_asset_unlock(bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ov_asset_unlock(p_ova_id bigint, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user     RECORD;
    v_holder   BIGINT;
    v_contract BIGINT;
    v_allowed  BOOLEAN := false;
BEGIN
    SELECT u.id, COALESCE(u.is_admin, false) OR COALESCE(u.is_admin_super, false) AS is_admin
      INTO v_user
      FROM public.users u WHERE u.uuid = auth.uid() LIMIT 1;
    IF v_user.id IS NULL THEN
        RAISE EXCEPTION 'Usuário não identificado.' USING ERRCODE = '42501';
    END IF;

    SELECT a.locked_user_id, o.contract_id
      INTO v_holder, v_contract
      FROM public.orders_visits_assets a
      JOIN public.orders_visits ov ON ov.id = a.ov_id
      LEFT JOIN public.orders o ON o.id = ov.o_id
     WHERE a.id = p_ova_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ativo da visita % não encontrado ou sem permissão.', p_ova_id
            USING ERRCODE = 'P0002';
    END IF;

    IF v_holder IS NULL THEN
        RETURN jsonb_build_object('unlocked', true, 'was_locked', false);
    END IF;

    IF v_holder = v_user.id THEN
        v_allowed := true;
    ELSIF p_force THEN
        v_allowed := v_user.is_admin OR EXISTS (
            SELECT 1 FROM public.contracts_managers m
             WHERE m.contract_id = v_contract
               AND m.manager_id  = v_user.id
               AND m.role        = 'manager'
               AND m.is_deleted  = false
        );
    END IF;

    IF NOT v_allowed THEN
        RAISE EXCEPTION 'Ativo travado por outro técnico. Só o gestor do contrato pode liberar.'
            USING ERRCODE = '42501';
    END IF;

    UPDATE public.orders_visits_assets
       SET locked_user_id = NULL,
           locked_at      = NULL,
           lock_token     = NULL
     WHERE id = p_ova_id;

    RETURN jsonb_build_object(
        'unlocked', true,
        'was_locked', true,
        'forced', v_holder <> v_user.id,
        'previous_user_id', v_holder
    );
END;
$$;

--
-- Name: FUNCTION ov_asset_unlock(p_ova_id bigint, p_force boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ov_asset_unlock(p_ova_id bigint, p_force boolean) IS 'Modo offline: solta a trava (própria; ou forçada por gestor do contrato/admin). SECURITY INVOKER.';

--
-- Name: recalculate_all_scores(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_all_scores(p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT DISTINCT leader_department_id
        FROM public.v_order_visit_scores
        WHERE score_year = p_year
          AND score_month = p_month
    LOOP
        PERFORM public.recalculate_department_scores(rec.leader_department_id, p_year, p_month);
    END LOOP;
END;
$$;

--
-- Name: recalculate_department_scores(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_department_scores(p_department_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT DISTINCT ov.leader_id
        FROM public.v_order_visit_scores ov
        WHERE ov.leader_department_id = p_department_id
          AND ov.score_year = p_year
          AND ov.score_month = p_month
    LOOP
        PERFORM public.recalculate_leader_monthly_score(rec.leader_id, p_year, p_month);
    END LOOP;
END;
$$;

--
-- Name: recalculate_leader_monthly_score(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_leader_monthly_score(p_leader_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_total_visits int;
    v_total_evals int;
    v_failed_evals int;
    v_total_penalty numeric(10,2);
    v_avg_compliance numeric(5,2);
    v_best_compliance numeric(5,2);
    v_worst_compliance numeric(5,2);
    v_leader_name varchar;
    v_dept_id bigint;
    v_dept_name varchar;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' AND NOT EXISTS (
        SELECT 1
        FROM public.users u
        WHERE u.uuid = auth.uid()
          AND (
              u.is_admin_super = TRUE
              OR EXISTS (
                  SELECT 1
                  FROM public.cfg_profiles_access pa
                  JOIN public.cfg_routes r ON r.id = pa.route_id
                  WHERE pa.profile_id = u.profile_id
                    AND r.route_key = 'dashboard_contracts_evaluations'
                    AND r.is_available = TRUE
                    AND pa.can_view = TRUE
              )
          )
    ) THEN
        RAISE EXCEPTION 'Permission denied to recalculate leader scores'
            USING ERRCODE = '42501';
    END IF;

    SELECT u.name_short, d.id, d.description
    INTO v_leader_name, v_dept_id, v_dept_name
    FROM public.users u
    JOIN public.cfg_teams t ON t.id = u.team_id
    JOIN public.cfg_departments d ON d.id = t.department_id
    WHERE u.id = p_leader_id;

    SELECT
        COUNT(*)::int,
        COALESCE(SUM(total_evaluations), 0)::int,
        COALESCE(SUM(failed_evaluations), 0)::int,
        COALESCE(SUM(penalty_score), 0)::numeric(10,2),
        CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(AVG(compliance_score), 2) END,
        COALESCE(MAX(compliance_score), 0)::numeric(5,2),
        COALESCE(MIN(compliance_score), 0)::numeric(5,2)
    INTO v_total_visits, v_total_evals, v_failed_evals, v_total_penalty,
         v_avg_compliance, v_best_compliance, v_worst_compliance
    FROM public.v_order_visit_scores
    WHERE leader_id = p_leader_id
      AND score_year = p_year
      AND score_month = p_month;

    INSERT INTO public.leader_monthly_scores (
        leader_id, leader_name, department_id, department_name,
        score_year, score_month,
        total_visits, total_evaluations, failed_evaluations,
        total_penalty_score, avg_compliance_score,
        best_compliance_score, worst_compliance_score,
        updated_at
    ) VALUES (
        p_leader_id, v_leader_name, v_dept_id, v_dept_name,
        p_year, p_month,
        v_total_visits, v_total_evals, v_failed_evals,
        v_total_penalty, v_avg_compliance,
        v_best_compliance, v_worst_compliance,
        now()
    )
    ON CONFLICT (leader_id, score_year, score_month)
    DO UPDATE SET
        leader_name = EXCLUDED.leader_name,
        department_name = EXCLUDED.department_name,
        total_visits = EXCLUDED.total_visits,
        total_evaluations = EXCLUDED.total_evaluations,
        failed_evaluations = EXCLUDED.failed_evaluations,
        total_penalty_score = EXCLUDED.total_penalty_score,
        avg_compliance_score = EXCLUDED.avg_compliance_score,
        best_compliance_score = EXCLUDED.best_compliance_score,
        worst_compliance_score = EXCLUDED.worst_compliance_score,
        updated_at = now();

    INSERT INTO public.leader_scores_history (
        leader_id, ov_id, order_id, score_year, score_month,
        total_evaluations, failed_evaluations, penalty_score,
        max_possible_score, compliance_score, evaluated_at
    )
    SELECT
        leader_id, ov_id, order_id, score_year, score_month,
        total_evaluations, failed_evaluations, penalty_score,
        max_possible_score, compliance_score, ov_ended_at
    FROM public.v_order_visit_scores
    WHERE leader_id = p_leader_id
      AND score_year = p_year
      AND score_month = p_month
    ON CONFLICT (ov_id)
    DO UPDATE SET
        total_evaluations = EXCLUDED.total_evaluations,
        failed_evaluations = EXCLUDED.failed_evaluations,
        penalty_score = EXCLUDED.penalty_score,
        max_possible_score = EXCLUDED.max_possible_score,
        compliance_score = EXCLUDED.compliance_score;

    WITH ranked AS (
        SELECT
            id,
            ROW_NUMBER() OVER (
                PARTITION BY department_id, score_year, score_month
                ORDER BY
                    ROUND(avg_compliance_score) DESC,
                    total_visits DESC,
                    failed_evaluations ASC,
                    leader_id ASC
            ) AS new_rank
        FROM public.leader_monthly_scores
        WHERE department_id = v_dept_id
          AND score_year = p_year
          AND score_month = p_month
    )
    UPDATE public.leader_monthly_scores lms
    SET ranking_position = ranked.new_rank
    FROM ranked
    WHERE lms.id = ranked.id;
END;
$$;

--
-- Name: report_unit_asset_tag_availability(integer, boolean, integer, text, integer, text, text, integer, integer, integer, numeric, text, text, double precision, double precision, double precision, double precision, double precision, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_unit_asset_tag_availability(p_unit_asset_tag_id integer, p_is_available boolean, p_reason_id integer, p_comments text, p_reported_by_id integer, p_file_path text, p_file_name text, p_unit_id integer, p_asset_tag_id integer, p_asset_tag_sub_id integer, p_operation_record numeric, p_created_at text, p_reported_at text, p_reported_latitude double precision, p_reported_longitude double precision, p_unit_latitude double precision, p_unit_longitude double precision, p_unit_reported_distance double precision, p_provider_company_id integer, p_is_web boolean) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_id INTEGER;
    v_rate NUMERIC;
    v_has_active_children boolean := FALSE;
    v_do_cascade_disable boolean := FALSE;
    v_parent_name TEXT := NULL;
    v_parent_count integer := 0;
    v_cascade_driven_parents integer := 0;
    v_block boolean := FALSE;
    v_root_name TEXT := NULL;
    v_n integer := 0;
    v_reach_ids bigint[] := NULL;
BEGIN
    -- ── 0) GUARDA OR: bloquear informe apenas quando ──────────────────
    --    (a) o próprio nó estiver forçado por cascata (cascade_parent_id setado ≠ id)
    --    OU (b) TODOS os pais diretos (primário + secundário) tenham
    --         cascade_parent_id NOT NULL (cascade-driven).
    --    Regra OR: disponível se qualquer pai estiver disponível.
    BEGIN
        SELECT count(*), count(*) FILTER (WHERE pr.cascade_parent_id IS NOT NULL)
        INTO v_parent_count, v_cascade_driven_parents
        FROM (
            SELECT n.parent_id AS pid
            FROM public.cfg_units_assets_tags n
            WHERE n.id = p_unit_asset_tag_id AND n.parent_id IS NOT NULL
            UNION
            SELECT l.parent_id
            FROM public.cfg_units_assets_tags_links l
            WHERE l.unit_asset_tag_id = p_unit_asset_tag_id
        ) par
        JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid;
    EXCEPTION WHEN undefined_object THEN
        -- Tabela de links ainda não existe (migration parcial): degrade graciosamente
        v_parent_count := 0;
        v_cascade_driven_parents := 0;
    END;

    IF p_unit_asset_tag_id IS NOT NULL THEN
        IF v_parent_count > 0 AND v_cascade_driven_parents = v_parent_count THEN
            v_block := TRUE;
        END IF;
        -- Além disso, se o próprio nó já estiver marcado como forçado:
        IF NOT v_block THEN
            SELECT COALESCE(cascade_parent_id IS NOT NULL AND cascade_parent_id <> id, FALSE)
            INTO v_block
            FROM public.cfg_units_assets_tags
            WHERE id = p_unit_asset_tag_id;
        END IF;
    END IF;

    IF v_block THEN
        -- Nome da raiz de cascata (pai cascade-driven, senão a raiz do próprio nó)
        SELECT r.asset_tag_tag_sub_description INTO v_root_name
        FROM (
            SELECT n.parent_id AS pid
            FROM public.cfg_units_assets_tags n
            WHERE n.id = p_unit_asset_tag_id AND n.parent_id IS NOT NULL
            UNION
            SELECT l.parent_id
            FROM public.cfg_units_assets_tags_links l
            WHERE l.unit_asset_tag_id = p_unit_asset_tag_id
        ) par
        JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid
        JOIN public.cfg_units_assets_tags r ON r.id = pr.cascade_parent_id
        WHERE pr.cascade_parent_id IS NOT NULL
        LIMIT 1;

        IF v_root_name IS NULL THEN
            SELECT r.asset_tag_tag_sub_description INTO v_root_name
            FROM public.cfg_units_assets_tags n
            JOIN public.cfg_units_assets_tags r ON r.id = n.cascade_parent_id
            WHERE n.id = p_unit_asset_tag_id
              AND n.cascade_parent_id IS NOT NULL AND n.cascade_parent_id <> n.id
            LIMIT 1;
        END IF;

        RAISE EXCEPTION 'NODE_UNDER_CASCADE: setor sob cascata de um ancestral indisponível; informe a disponibilidade pelo setor pai (%).',
            COALESCE(v_root_name, 'setor pai');
    END IF;
    -- ═══ fim da guarda: daqui em diante o informe é LIBERADO ═══

    v_parent_name := COALESCE(
        (SELECT c.asset_tag_tag_sub_description
         FROM public.cfg_units_assets_tags c
         WHERE c.id = p_unit_asset_tag_id),
        'setor pai'
    );

    -- Filhos ativos: primários E secundários (DAG)
    SELECT EXISTS (
        SELECT 1 FROM public.cfg_units_assets_tags d
        WHERE d.parent_id = p_unit_asset_tag_id
          AND d.is_deleted = FALSE AND d.is_active = TRUE
        UNION ALL
        SELECT 1
        FROM public.cfg_units_assets_tags_links l
        JOIN public.cfg_units_assets_tags d ON d.id = l.unit_asset_tag_id
        WHERE l.parent_id = p_unit_asset_tag_id
          AND d.is_deleted = FALSE AND d.is_active = TRUE
    ) INTO v_has_active_children;

    v_do_cascade_disable := (p_is_available = FALSE) AND v_has_active_children;

    -- ── 1) Rate do próprio nó (regra original) ──────────────────────────
    IF p_is_available THEN
        SELECT asset_available_rate INTO v_rate
        FROM public.cfg_units_assets_tags WHERE id = p_unit_asset_tag_id;
    ELSE
        v_rate := 0;
    END IF;

    -- ── 2) Histórico do nó informado (idêntico ao RPC original) ─────────
    INSERT INTO public.assets_available (
        unit_asset_tag_id, unit_id, asset_tag_id, asset_tag_sub_id,
        is_available, asset_unavailable_reason_id, comments,
        created_user_id, reported_user_id, file_path, file_name,
        operation_record, created_at, reported_at,
        reported_latitude, reported_longitude, unit_latitude, unit_longitude,
        unit_reported_distance_m, provider_company_id, is_web, processing_id
    ) VALUES (
        p_unit_asset_tag_id,
        p_unit_id, p_asset_tag_id, p_asset_tag_sub_id,
        p_is_available, COALESCE(p_reason_id, 0), p_comments,
        p_reported_by_id, p_reported_by_id, p_file_path, p_file_name,
        p_operation_record, p_created_at::TIMESTAMP, p_reported_at::TIMESTAMP,
        p_reported_latitude, p_reported_longitude, p_unit_latitude, p_unit_longitude,
        p_unit_reported_distance, p_provider_company_id, p_is_web, 2
    ) RETURNING id INTO v_new_id;

    -- ── 3) Snapshot do nó informado + marcador de raiz de cascata ──────
    UPDATE public.cfg_units_assets_tags
    SET
        last_asset_available_id = v_new_id,
        last_is_available = p_is_available,
        last_asset_available_rate = v_rate,
        last_created_at = p_created_at::TIMESTAMP,
        last_reported_at = p_reported_at::TIMESTAMP,
        last_reported_user_id = p_reported_by_id,
        last_file_path = p_file_path,
        last_file_name = p_file_name,
        last_comments = p_comments,
        last_asset_unavailable_reason_id = p_reason_id,
        last_operation_record = p_operation_record,
        last_provider_company_id = p_provider_company_id,
        last_processing_id = 2,
        cascade_parent_id = CASE
            WHEN p_is_available THEN NULL                        -- raiz liberada
            WHEN v_do_cascade_disable THEN p_unit_asset_tag_id   -- vira raiz de cascata
            ELSE cascade_parent_id END,
        pre_cascade_state = CASE WHEN p_is_available THEN NULL ELSE pre_cascade_state END
    WHERE id = p_unit_asset_tag_id;

    -- ── 4) CASCATA DESCENDO (fixpoint com regra OR) ─────────────────────
    -- Alcançáveis do nó informado (arestas primárias + secundárias, cycle-safe
    -- via UNION). Materializado uma vez: a estrutura não muda durante o loop.
    IF v_do_cascade_disable THEN
        WITH RECURSIVE edges AS (
            SELECT d.parent_id, d.id AS child_id
            FROM public.cfg_units_assets_tags d
            WHERE d.parent_id IS NOT NULL
              AND d.is_deleted = FALSE AND d.is_active = TRUE
            UNION
            SELECT l.parent_id, l.unit_asset_tag_id
            FROM public.cfg_units_assets_tags_links l
            JOIN public.cfg_units_assets_tags d ON d.id = l.unit_asset_tag_id
            WHERE d.is_deleted = FALSE AND d.is_active = TRUE
        ),
        reach AS (
            SELECT child_id AS id FROM edges WHERE parent_id = p_unit_asset_tag_id
            UNION
            SELECT e.child_id FROM edges e JOIN reach r ON e.parent_id = r.id
        )
        SELECT array_agg(id) INTO v_reach_ids FROM reach;

        -- Itera até não haver candidato: um nó só é forçado quando TODOS os
        -- seus pais estão indisponíveis (regra OR) — a força se propaga em
        -- camadas (pais primeiro, depois netos etc.).
        LOOP
            WITH candidate AS (
                SELECT c.id, to_jsonb(c) AS full_row
                FROM public.cfg_units_assets_tags c
                WHERE c.id = ANY(v_reach_ids)
                  AND c.is_deleted = FALSE AND c.is_active = TRUE
                  AND c.cascade_parent_id IS NULL
                  AND c.last_is_available IS DISTINCT FROM FALSE
                  AND EXISTS (
                      SELECT 1
                      FROM (
                          SELECT n.parent_id AS pid
                          FROM public.cfg_units_assets_tags n
                          WHERE n.id = c.id AND n.parent_id IS NOT NULL
                          UNION
                          SELECT l.parent_id
                          FROM public.cfg_units_assets_tags_links l
                          WHERE l.unit_asset_tag_id = c.id
                      ) par
                  )
                  AND NOT EXISTS (
                      SELECT 1
                      FROM (
                          SELECT n.parent_id AS pid
                          FROM public.cfg_units_assets_tags n
                          WHERE n.id = c.id AND n.parent_id IS NOT NULL
                          UNION
                          SELECT l.parent_id
                          FROM public.cfg_units_assets_tags_links l
                          WHERE l.unit_asset_tag_id = c.id
                      ) par
                      JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid
                      WHERE pr.last_is_available IS DISTINCT FROM FALSE
                  )
            ),
            upd AS (
                UPDATE public.cfg_units_assets_tags u
                SET cascade_parent_id = p_unit_asset_tag_id,
                    pre_cascade_state = candidate.full_row,
                    last_is_available = FALSE,
                    last_asset_available_rate = 0,
                    last_asset_available_id = v_new_id,
                    last_created_at = p_created_at::TIMESTAMP,
                    last_reported_at = p_reported_at::TIMESTAMP,
                    last_reported_user_id = p_reported_by_id,
                    last_comments = 'Indisponível em cascata — setor pai: ' || v_parent_name,
                    last_asset_unavailable_reason_id = p_reason_id,
                    last_processing_id = 3,
                    last_flow_rate = 0, last_power = 0, last_pressure = 0,
                    last_voltage = 0, last_amperage = 0,
                    last_operation_record = NULL,
                    last_file_path = NULL, last_file_name = NULL,
                    last_provider_company_id = p_provider_company_id
                FROM candidate
                WHERE u.id = candidate.id
                RETURNING u.id, u.unit_id, u.asset_tag_id, u.asset_tag_sub_id
            )
            -- Geo/origem herdados do pai (p_* = valores do informe do setor pai)
            INSERT INTO public.assets_available (
                unit_asset_tag_id, unit_id, asset_tag_id, asset_tag_sub_id,
                is_available, asset_unavailable_reason_id, comments,
                created_user_id, reported_user_id,
                reported_latitude, reported_longitude,
                unit_latitude, unit_longitude,
                unit_reported_distance_m, is_web,
                created_at, reported_at, processing_id
            )
            SELECT upd.id, upd.unit_id, upd.asset_tag_id, upd.asset_tag_sub_id,
                   FALSE, COALESCE(p_reason_id, 0),
                   'Indisponibilidade em cascata — setor pai: ' || v_parent_name,
                   p_reported_by_id, p_reported_by_id,
                   p_reported_latitude, p_reported_longitude,
                   p_unit_latitude, p_unit_longitude,
                   p_unit_reported_distance, p_is_web,
                   p_created_at::TIMESTAMP, p_reported_at::TIMESTAMP, 3
            FROM upd;

            GET DIAGNOSTICS v_n = ROW_COUNT;
            EXIT WHEN v_n = 0;
        END LOOP;
    END IF;

    -- ── 5) CASCATA SUBINDO (loop cross-root com regra OR) ───────────────
    -- Restaura de pre_cascade_state QUALQUER nó forçado que tenha ao menos
    -- UM pai disponível agora — inclusive nós forçados por outra raiz
    -- (filho de dois pais: um pai voltou → filho liberado). Repete até não
    -- houver restauração (propaga para netos etc.).
    -- Quem já estava indisponível antes da cascata NÃO tinha snapshot
    -- (nunca foi marcado) → permanece indisponível com motivo próprio.
    IF p_is_available THEN
        LOOP
            WITH marked AS (
                SELECT c.id, c.pre_cascade_state AS pre
                FROM public.cfg_units_assets_tags c
                WHERE c.cascade_parent_id IS NOT NULL
                  AND c.cascade_parent_id <> c.id
                  AND c.pre_cascade_state IS NOT NULL
                  AND EXISTS (
                      SELECT 1
                      FROM (
                          SELECT n.parent_id AS pid
                          FROM public.cfg_units_assets_tags n
                          WHERE n.id = c.id AND n.parent_id IS NOT NULL
                          UNION
                          SELECT l.parent_id
                          FROM public.cfg_units_assets_tags_links l
                          WHERE l.unit_asset_tag_id = c.id
                      ) par
                      JOIN public.cfg_units_assets_tags pr ON pr.id = par.pid
                      WHERE pr.last_is_available IS DISTINCT FROM FALSE
                  )
            ),
            upd AS (
                UPDATE public.cfg_units_assets_tags u
                SET last_is_available        = (m.pre->>'last_is_available')::boolean,
                    last_asset_available_rate = COALESCE((m.pre->>'last_asset_available_rate')::numeric, 0),
                    last_asset_available_id  = COALESCE((m.pre->>'last_asset_available_id')::bigint, 0),
                    last_created_at          = (m.pre->>'last_created_at')::timestamp,
                    last_reported_at         = (m.pre->>'last_reported_at')::timestamp,
                    last_reported_user_id    = (m.pre->>'last_reported_user_id')::bigint,
                    last_file_path           = m.pre->>'last_file_path',
                    last_file_name           = m.pre->>'last_file_name',
                    last_comments            = NULLIF(m.pre->>'last_comments', 'Indisponível em cascata — setor pai: ' || v_parent_name),
                    last_asset_unavailable_reason_id = (m.pre->>'last_asset_unavailable_reason_id')::bigint,
                    last_operation_record    = (m.pre->>'last_operation_record')::numeric,
                    last_provider_company_id = (m.pre->>'last_provider_company_id')::bigint,
                    last_status_id           = (m.pre->>'last_status_id')::bigint,
                    last_processing_id       = COALESCE((m.pre->>'last_processing_id')::bigint, 1),
                    last_flow_rate           = (m.pre->>'last_flow_rate')::numeric,
                    last_power               = (m.pre->>'last_power')::numeric,
                    last_pressure            = (m.pre->>'last_pressure')::numeric,
                    last_voltage             = (m.pre->>'last_voltage')::numeric,
                    last_amperage            = (m.pre->>'last_amperage')::numeric,
                    cascade_parent_id        = NULL,
                    pre_cascade_state        = NULL
                FROM marked m
                WHERE u.id = m.id
                RETURNING u.id, u.unit_id, u.asset_tag_id, u.asset_tag_sub_id, u.last_is_available
            )
            -- Geo/origem também herdados do pai (mesmo evento de informe)
            INSERT INTO public.assets_available (
                unit_asset_tag_id, unit_id, asset_tag_id, asset_tag_sub_id,
                is_available, comments,
                created_user_id, reported_user_id,
                reported_latitude, reported_longitude,
                unit_latitude, unit_longitude,
                unit_reported_distance_m, is_web,
                created_at, reported_at, processing_id
            )
            SELECT upd.id, upd.unit_id, upd.asset_tag_id, upd.asset_tag_sub_id,
                   upd.last_is_available,
                   'Disponibilidade restaurada em cascata — setor pai: ' || v_parent_name,
                   p_reported_by_id, p_reported_by_id,
                   p_reported_latitude, p_reported_longitude,
                   p_unit_latitude, p_unit_longitude,
                   p_unit_reported_distance, p_is_web,
                   p_created_at::TIMESTAMP, p_reported_at::TIMESTAMP, 3
            FROM upd;

            GET DIAGNOSTICS v_n = ROW_COUNT;
            EXIT WHEN v_n = 0;
        END LOOP;
    END IF;

    RETURN v_new_id;
END;
$$;

--
-- Name: restore_original_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_original_password(p_user_uuid uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_original_password TEXT;
BEGIN
    -- Get the most recent unrestored backup
    SELECT original_encrypted_password INTO v_original_password
    FROM public.impersonation_password_backup
    WHERE user_uuid = p_user_uuid
      AND restored_at IS NULL
    ORDER BY backed_up_at DESC
    LIMIT 1;

    IF v_original_password IS NULL THEN
        RETURN json_build_object('error', 'No backup found for this user');
    END IF;

    -- Restore the original password
    UPDATE auth.users
    SET encrypted_password = v_original_password,
        updated_at = now()
    WHERE id = p_user_uuid;

    -- Mark as restored
    UPDATE public.impersonation_password_backup
    SET restored_at = now()
    WHERE user_uuid = p_user_uuid
      AND restored_at IS NULL;

    RETURN json_build_object('success', true, 'uuid', p_user_uuid);
END;
$$;

--
-- Name: reverse_order_visit_approval(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_order_visit_approval(p_visit_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_authenticated_user_id bigint;
BEGIN
    SELECT id INTO v_authenticated_user_id
    FROM public.users
    WHERE uuid = auth.uid();

    IF auth.uid() IS NULL OR v_authenticated_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuário não autenticado para reverter aprovação da visita';
    END IF;

    PERFORM 1
    FROM public.orders_visits
    WHERE id = p_visit_id
      AND ov_processing_id = 5
      AND COALESCE(is_deleted, false) = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Visita aprovada não encontrada';
    END IF;

    UPDATE public.orders_visits_assets
    SET processing_id = 2
    WHERE ov_id = p_visit_id;

    UPDATE public.orders_visits
    SET ov_processing_id = 2,
        ov_assets_approved_no_filed_amount = 0,
        ov_approved_at = NULL,
        ov_approved_user_id = NULL,
        ov_costs_status = 'pending',
        ov_costs_waiting_at = NULL,
        ov_costs_approved_at = NULL,
        ov_costs_rejected_at = NULL,
        ov_costs_rejection_reason = NULL,
        updated_user_id = v_authenticated_user_id,
        updated_at = now()
    WHERE id = p_visit_id;

    DELETE FROM public.orders_visits_maintenances_plans
    WHERE ov_id = p_visit_id;
END;
$$;

--
-- Name: save_team_shifts_calendar(date, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_team_shifts_calendar(p_reference_month date, p_department_id bigint, p_entries jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_user_id BIGINT;
    v_is_admin_super BOOLEAN;
    v_item JSONB;
    v_team_id BIGINT;
    v_shift_date DATE;
    v_change_count INTEGER;
    v_unique_count INTEGER;
BEGIN
    SELECT u.id, u.is_admin_super
      INTO v_user_id, v_is_admin_super
      FROM public.users u
     WHERE u.uuid = auth.uid();

    IF v_user_id IS NULL
       OR (
           v_is_admin_super IS NOT TRUE
           AND NOT EXISTS (
               SELECT 1
                 FROM public.cfg_profiles_access pa
                 JOIN public.cfg_routes r ON r.id = pa.route_id
                 JOIN public.users u ON u.profile_id = pa.profile_id
                WHERE u.id = v_user_id
                  AND r.route_key = 'dashboard_teams_shifts_calendar'
                  AND r.is_available IS TRUE
                  AND pa.can_create IS TRUE
           )
       ) THEN
        RAISE EXCEPTION 'Você não tem permissão para alterar o calendário de turnos'
            USING ERRCODE = '42501';
    END IF;

    IF p_reference_month IS NULL
       OR p_reference_month <> date_trunc('month', p_reference_month)::date
       OR p_department_id IS NULL
       OR jsonb_typeof(p_entries) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Informe o primeiro dia do mês, o departamento e uma lista de turnos válida'
            USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM public.teams_shifts_months m
         WHERE m.reference_month = p_reference_month
           AND m.department_id = p_department_id
    ) THEN
        RAISE EXCEPTION 'Este mês está fechado e não pode mais ser editado'
            USING ERRCODE = '55000';
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_entries) AS entries(value)
    LOOP
        IF jsonb_typeof(v_item -> 'team_id') IS DISTINCT FROM 'number'
           OR jsonb_typeof(v_item -> 'shift_date') IS DISTINCT FROM 'string'
           OR jsonb_typeof(v_item -> 'shift_type') IS DISTINCT FROM 'string'
           OR v_item ->> 'shift_type' NOT IN ('TN', 'TE')
           OR (v_item ->> 'team_id') !~ '^[0-9]+$'
           OR (v_item ->> 'shift_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
            RAISE EXCEPTION 'Cada marcação deve informar team_id, shift_date e shift_type TN ou TE'
                USING ERRCODE = '22023';
        END IF;

        v_team_id := (v_item ->> 'team_id')::BIGINT;
        v_shift_date := (v_item ->> 'shift_date')::DATE;

        IF v_shift_date < p_reference_month
           OR v_shift_date >= (p_reference_month + INTERVAL '1 month')::date THEN
            RAISE EXCEPTION 'As marcações devem estar dentro do mês selecionado'
                USING ERRCODE = '22023';
        END IF;

        IF NOT EXISTS (
            SELECT 1
              FROM public.cfg_teams t
             WHERE t.id = v_team_id
               AND t.department_id = p_department_id
               AND t.is_evaluable IS TRUE
        ) THEN
            RAISE EXCEPTION 'Equipe não avaliável ou fora do departamento selecionado: %', v_team_id
                USING ERRCODE = '22023';
        END IF;
    END LOOP;

    SELECT count(*),
           count(DISTINCT (value ->> 'team_id') || ':' || (value ->> 'shift_date') || ':' || (value ->> 'shift_type'))
      INTO v_change_count, v_unique_count
      FROM jsonb_array_elements(p_entries) AS entries(value);

    IF v_change_count <> v_unique_count THEN
        RAISE EXCEPTION 'Há marcações duplicadas do mesmo tipo para a equipe e data'
            USING ERRCODE = '22023';
    END IF;

    DELETE FROM public.teams_shifts_calendar c
     USING public.cfg_teams t
     WHERE c.team_id = t.id
       AND t.department_id = p_department_id
       AND t.is_evaluable IS TRUE
       AND c.shift_date >= p_reference_month
       AND c.shift_date < (p_reference_month + INTERVAL '1 month')::date;

    INSERT INTO public.teams_shifts_calendar (team_id, shift_date, shift_type, updated_by, updated_at)
    SELECT (value ->> 'team_id')::BIGINT,
           (value ->> 'shift_date')::DATE,
           value ->> 'shift_type',
           v_user_id,
           timezone('America/Sao_Paulo', now())
      FROM jsonb_array_elements(p_entries) AS entries(value);

    UPDATE public.teams_shifts_records r
       SET normal_shifts = 0,
           extra_shifts = 0,
           updated_by = v_user_id,
           updated_at = timezone('America/Sao_Paulo', now())
      FROM public.cfg_teams t
     WHERE r.team_id = t.id
       AND r.reference_month = p_reference_month
       AND t.department_id = p_department_id
       AND t.is_evaluable IS TRUE;

    INSERT INTO public.teams_shifts_records (
        team_id, reference_month, normal_shifts, extra_shifts, created_by, updated_by, updated_at
    )
    SELECT c.team_id,
           p_reference_month,
           count(*) FILTER (WHERE c.shift_type = 'TN')::INTEGER,
           count(*) FILTER (WHERE c.shift_type = 'TE')::INTEGER,
           v_user_id,
           v_user_id,
           timezone('America/Sao_Paulo', now())
      FROM public.teams_shifts_calendar c
      JOIN public.cfg_teams t ON t.id = c.team_id
     WHERE t.department_id = p_department_id
       AND t.is_evaluable IS TRUE
       AND c.shift_date >= p_reference_month
       AND c.shift_date < (p_reference_month + INTERVAL '1 month')::date
     GROUP BY c.team_id
    ON CONFLICT (team_id, reference_month) DO UPDATE
       SET normal_shifts = EXCLUDED.normal_shifts,
           extra_shifts = EXCLUDED.extra_shifts,
           updated_by = EXCLUDED.updated_by,
           updated_at = EXCLUDED.updated_at;

    DELETE FROM public.teams_shifts_records r
     USING public.cfg_teams t
     WHERE r.team_id = t.id
       AND r.reference_month = p_reference_month
       AND r.normal_shifts = 0
       AND r.extra_shifts = 0
       AND r.note IS NULL
       AND t.department_id = p_department_id
       AND t.is_evaluable IS TRUE;
END;
$_$;

--
-- Name: FUNCTION save_team_shifts_calendar(p_reference_month date, p_department_id bigint, p_entries jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_team_shifts_calendar(p_reference_month date, p_department_id bigint, p_entries jsonb) IS 'Salva marcações diárias e sincroniza totais mensais em uma transação; somente super admins.';

--
-- Name: set_audit_table_config(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_audit_table_config(p_changes jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id bigint;
    v_item jsonb;
    v_table_name text;
    v_enabled boolean;
    v_table_oid regclass;
    v_change_count integer;
    v_unique_count integer;
BEGIN
    SELECT u.id
      INTO v_user_id
      FROM public.users u
     WHERE u.uuid = auth.uid()
       AND u.is_admin_super IS TRUE;

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Apenas o super admin pode alterar a configuração de auditoria'
            USING ERRCODE = '42501';
    END IF;

    IF jsonb_typeof(p_changes) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'A configuração deve ser enviada como uma lista de alterações'
            USING ERRCODE = '22023';
    END IF;

    SELECT count(*), count(DISTINCT value ->> 'table_name')
      INTO v_change_count, v_unique_count
      FROM jsonb_array_elements(p_changes) AS changes(value);

    IF v_change_count <> v_unique_count THEN
        RAISE EXCEPTION 'A lista contém tabelas duplicadas'
            USING ERRCODE = '22023';
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_changes) AS changes(value)
    LOOP
        IF jsonb_typeof(v_item -> 'table_name') IS DISTINCT FROM 'string'
           OR jsonb_typeof(v_item -> 'enabled') IS DISTINCT FROM 'boolean' THEN
            RAISE EXCEPTION 'Cada alteração deve informar table_name e enabled'
                USING ERRCODE = '22023';
        END IF;

        v_table_name := v_item ->> 'table_name';
        v_enabled := (v_item ->> 'enabled')::boolean;

        PERFORM 1
          FROM public.cfg_audits_tables c
         WHERE c.table_name = v_table_name
         FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tabela não permitida para auditoria: %', v_table_name
                USING ERRCODE = '22023';
        END IF;

        v_table_oid := to_regclass(format('%I.%I', 'public', v_table_name));

        IF v_enabled AND v_table_oid IS NULL THEN
            RAISE EXCEPTION 'A tabela public.% não existe neste banco', v_table_name
                USING ERRCODE = '42P01';
        END IF;

        IF v_enabled THEN
            IF NOT EXISTS (
                SELECT 1
                FROM pg_trigger tr
                WHERE tr.tgrelid = v_table_oid
                  AND tr.tgname = 'trg_audit_' || v_table_name
                  AND NOT tr.tgisinternal
            ) THEN
                EXECUTE format(
                    'CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I.%I FOR EACH ROW EXECUTE FUNCTION public.fc_audit_log()',
                    'trg_audit_' || v_table_name,
                    'public',
                    v_table_name
                );
            END IF;
        ELSIF v_table_oid IS NOT NULL THEN
            EXECUTE format(
                'DROP TRIGGER IF EXISTS %I ON %I.%I',
                'trg_audit_' || v_table_name,
                'public',
                v_table_name
            );
        END IF;

        UPDATE public.cfg_audits_tables
           SET is_enabled = v_enabled,
               updated_at = timezone('America/Sao_Paulo', now()),
               updated_by = v_user_id
         WHERE table_name = v_table_name;
    END LOOP;
END;
$$;

--
-- Name: FUNCTION set_audit_table_config(p_changes jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_audit_table_config(p_changes jsonb) IS 'Ativa/desativa triggers de auditoria atomicamente; acesso exclusivo a super admins.';

