-- Name: cfg_vehicles_rentals_contracts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cfg_vehicles_rentals_contracts (
    id bigint NOT NULL,
    vehicle_id bigint NOT NULL,
    monthly_value numeric(14,2) NOT NULL,
    start_date date NOT NULL,
    end_date date,
    active boolean DEFAULT true NOT NULL,
    description text,
    is_deleted boolean DEFAULT false NOT NULL,
    created_user_id bigint,
    created_at timestamp without time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp without time zone,
    value_unit numeric(14,6) DEFAULT 0 NOT NULL,
    CONSTRAINT cfg_vehicles_rentals_contracts_dates_ck CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT cfg_vehicles_rentals_contracts_value_ck CHECK ((monthly_value >= (0)::numeric)),
    CONSTRAINT cfg_vehicles_rentals_contracts_value_unit_ck CHECK (((value_unit IS NULL) OR (value_unit >= (0)::numeric)))
);

--
-- Name: TABLE cfg_vehicles_rentals_contracts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.cfg_vehicles_rentals_contracts IS 'Contrato(s) de aluguel mensal de veículo. Vigências sobrepostas para o mesmo veículo/mês são permitidas na tabela; a apuração escolhe a mais recente e sinaliza has_conflict.';

--
-- Name: COLUMN cfg_vehicles_rentals_contracts.value_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cfg_vehicles_rentals_contracts.value_unit IS 'Valor fixo por Km (R$/km) integrado ao mesmo contrato e vigência do aluguel.';

--
-- Name: cfg_vehicle_rate_contracts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cfg_vehicle_rate_contracts WITH (security_invoker='true') AS
 SELECT cfg_vehicles_rentals_contracts.id,
    cfg_vehicles_rentals_contracts.vehicle_id,
    cfg_vehicles_rentals_contracts.value_unit,
    cfg_vehicles_rentals_contracts.start_date,
    cfg_vehicles_rentals_contracts.end_date,
    cfg_vehicles_rentals_contracts.active,
    cfg_vehicles_rentals_contracts.description,
    cfg_vehicles_rentals_contracts.is_deleted,
    cfg_vehicles_rentals_contracts.created_user_id,
    cfg_vehicles_rentals_contracts.created_at,
    cfg_vehicles_rentals_contracts.updated_user_id,
    cfg_vehicles_rentals_contracts.updated_at
   FROM public.cfg_vehicles_rentals_contracts;

--
-- Name: cfg_vehicles_costs_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cfg_vehicles_costs_types (
    id bigint NOT NULL,
