--
-- Name: logs_app_client_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.logs_app_client_events (
    id bigint NOT NULL,
    created_at timestamp without time zone DEFAULT timezone('America/Sao_Paulo'::text, now()) NOT NULL,
    occurred_at timestamp with time zone,
    user_uuid uuid DEFAULT auth.uid(),
    event_type text NOT NULL,
    message text,
    stack text,
    screen text,
    url text,
    app_version text,
    platform text,
    user_agent text,
    session_id text,
    extra jsonb,
    CONSTRAINT logs_app_client_events_app_version_check CHECK (((app_version IS NULL) OR (length(app_version) <= 100))),
    CONSTRAINT logs_app_client_events_event_type_check CHECK ((event_type = ANY (ARRAY['error'::text, 'unhandled_rejection'::text, 'boundary'::text, 'reload'::text, 'unexpected_restart'::text, 'restored_after_kill'::text, 'app_restored_result'::text, 'offline_sync'::text]))),
    CONSTRAINT logs_app_client_events_extra_check CHECK (((extra IS NULL) OR ((jsonb_typeof(extra) = 'object'::text) AND (length((extra)::text) <= 4000)))),
    CONSTRAINT logs_app_client_events_message_check CHECK (((message IS NULL) OR (length(message) <= 2000))),
    CONSTRAINT logs_app_client_events_platform_check CHECK (((platform IS NULL) OR (length(platform) <= 30))),
    CONSTRAINT logs_app_client_events_screen_check CHECK (((screen IS NULL) OR (length(screen) <= 200))),
    CONSTRAINT logs_app_client_events_session_id_check CHECK (((session_id IS NULL) OR (length(session_id) <= 64))),
    CONSTRAINT logs_app_client_events_stack_check CHECK (((stack IS NULL) OR (length(stack) <= 8000))),
    CONSTRAINT logs_app_client_events_url_check CHECK (((url IS NULL) OR (length(url) <= 1000))),
    CONSTRAINT logs_app_client_events_user_agent_check CHECK (((user_agent IS NULL) OR (length(user_agent) <= 500)))
);

