    users.img_file_path,
    users.img_file_name,
    orders_visits.ov_started_at,
    orders_visits.ov_ended_at,
    users.is_available,
    users.is_ov_in_progress,
    orders_visits_teams.version_mode
   FROM ((public.orders_visits_teams
     JOIN public.users ON ((orders_visits_teams.user_id = users.id)))
