--

CREATE VIEW public.v_orders_visits_vehicles WITH (security_invoker='true') AS
 SELECT ovv.id,
    ovv.ov_id,
    ovv.vehicle_id,
    v.description AS vehicle_description,
    v.plates AS vehicle_plates,
    v.unit,
    ovv.recorder_start,
    ovv.recorder_end,
    ovv.amount,
    ovv.value_unit,
