--
-- Name: vehicles_monthly_expenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicles_monthly_expenses (
    id bigint NOT NULL,
    vehicle_id bigint NOT NULL,
    reference_month date NOT NULL,
    cost_type_id bigint NOT NULL,
    value numeric(14,2) NOT NULL,
    description text,
    created_user_id bigint,
    created_at timestamp without time zone DEFAULT now(),
    updated_user_id bigint,
    updated_at timestamp without time zone,
    odometer bigint,
    fuel_quantity numeric(12,3),
    plate_img_path text,
    plate_img_name text,
    odometer_img_path text,
    odometer_img_name text,
    invoice_img_path text,
    invoice_img_name text,
    CONSTRAINT vehicles_monthly_expenses_fuel_qty_ck CHECK (((fuel_quantity IS NULL) OR (fuel_quantity > (0)::numeric))),
    CONSTRAINT vehicles_monthly_expenses_month_ck CHECK ((reference_month = (date_trunc('month'::text, (reference_month)::timestamp with time zone))::date)),
    CONSTRAINT vehicles_monthly_expenses_odometer_ck CHECK (((odometer IS NULL) OR (odometer > 0))),
    CONSTRAINT vehicles_monthly_expenses_value_ck CHECK ((value > (0)::numeric))
);

--
-- Name: TABLE vehicles_monthly_expenses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vehicles_monthly_expenses IS 'Despesas variáveis reais do veículo em uma competência (combustível, pedágio, ...). Somadas na apuração junto com o aluguel do contrato; bloqueadas quando a competência está ALLOCATED/CLOSED.';

