--

COMMENT ON COLUMN public.vehicles_monthly_expenses.fuel_quantity IS 'Quantidade de combustível (Litros). Obrigatória no lançamento de combustível.';

--
-- Name: COLUMN vehicles_monthly_expenses.plate_img_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.vehicles_monthly_expenses.plate_img_path IS 'Caminho R2 da foto da placa (obrigatória no lançamento de combustível).';

--
-- Name: COLUMN vehicles_monthly_expenses.odometer_img_path; Type: COMMENT; Schema: public; Owner: -
