-- Name: logs_app_client_events Client events: super admin read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Client events: super admin read" ON public.logs_app_client_events FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.users u
