   FROM public.users
  WHERE (users.uuid = ( SELECT auth.uid() AS uid)))) OR (EXISTS ( SELECT 1
   FROM public.users
  WHERE ((users.uuid = ( SELECT auth.uid() AS uid)) AND (users.is_admin_super = true))))));

