-- Name: users_account_deletion_requests users_account_deletion_requests_admin_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY users_account_deletion_requests_admin_update ON public.users_account_deletion_requests FOR UPDATE TO authenticated USING (public.fc_has_route_permission('users'::character varying, 'edit'::character varying)) WITH CHECK (public.fc_has_route_permission('users'::character varying, 'edit'::character varying));

--
-- Name: users_account_deletion_requests users_account_deletion_requests_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY users_account_deletion_requests_select ON public.users_account_deletion_requests FOR SELECT TO authenticated USING (((user_id = ( SELECT u.id
   FROM public.users u
  WHERE (u.uuid = auth.uid())
 LIMIT 1)) OR public.fc_has_route_permission('users'::character varying, 'edit'::character varying)));

--
-- Name: users users_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY users_delete ON public.users FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.fn_users_caller() c(user_id, is_admin, is_admin_super, can_manage_peers, company_id)
  WHERE (c.is_admin OR c.is_admin_super))));

--
-- Name: users users_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY users_insert ON public.users FOR INSERT TO authenticated WITH CHECK (((uuid = auth.uid()) OR (EXISTS ( SELECT 1
   FROM public.fn_users_caller() c(user_id, is_admin, is_admin_super, can_manage_peers, company_id)
  WHERE (c.is_admin OR c.is_admin_super)))));

